window.__BOOK__={"meta":{"title_en":"The Little Prince","title_zh":"小王子","author_en":"Antoine de Saint-Exupéry","author_zh":"安托万·德·圣埃克苏佩里","voice":"en-GB-SoniaNeural (edge-tts)","ipa_note":"音标为宽式音位转写（英语近似发音，不标重音），仅供参考。","n_chapters":28,"n_paras":762,"n_sents":1635,"audio_paras":762},"chapters":[{"id":"ch00","title_en":"To Leon Werth","title_zh":"献词","paras":[{"id":"ch00p00","audio":true,"sents":[{"en":"I ask the indulgence of the children who may read this book for dedicating it to a grown-up.","zh":"我请求阅读这本书的孩子们的宽容，因为他们把它献给了成年人。","t":[138,5575]},{"en":"I have a serious reason: he is the best friend I have in the world.","zh":"我有严肃的理由：他是我在世界上最好的朋友。","t":[5575,9762]},{"en":"I have another reason: this grown-up understands everything, even books about children.","zh":"我还有另一个理由：这个成年人心智成熟，甚至能理解关于孩子的书籍。","t":[9762,15150]},{"en":"I have a third reason: he lives in France where he is hungry and cold.","zh":"我还有第三个理由：他住在法国，那里他饥寒交迫。","t":[15150,19675]},{"en":"He needs cheering up.","zh":"他需要有人让他振作起来。","t":[19675,21462]},{"en":"If all these reasons are not enough, I will dedicate the book to the child from whom this grown-up grew.","zh":"如果所有这些理由还不够，我将把这本书献给我这个成年人的孩童时期。","t":[21462,27300]},{"en":"All grown-ups were once children—although few of them remember it.","zh":"所有成年人都曾是孩子——尽管他们中的许多人已经忘记了。","t":[27300,31388]},{"en":"And so I correct my dedication: To Leon Werth, when he was a little boy.","zh":"因此，我修正了我的献词：献给莱昂·韦尔特，当他还是个小男孩的时候。","t":[31388,36000]}]}]},{"id":"ch01","title_en":"Chapter I","title_zh":"第 1 章","paras":[{"id":"ch01p00","audio":true,"sents":[{"en":"Once when I was six years old I saw a magnificent picture in a book, called True Stories from Nature, about the primeval forest.","zh":"有一次，当我六岁的时候，我在一本书上看到了一幅壮丽的图画，叫做《自然真实故事》，关于原始森林。","t":[138,8012]},{"en":"It was a picture of a boa constrictor in the act of swallowing an animal.","zh":"这是一幅蟒蛇正在吞食动物的图画。","t":[8012,12450]},{"en":"Here is a copy of the drawing.","zh":"这是一幅画的复制品。","t":[12450,14112]}]},{"id":"ch01p01","audio":true,"sents":[{"en":"In the book it said: \"Boa constrictors swallow their prey whole, without chewing it.","zh":"书上说：'蟒蛇会把猎物整个吞下，不嚼碎它。'","t":[112,5262]},{"en":"After that they are not able to move, and they sleep through the six months that they need for digestion.\"","zh":"之后它们就无法动弹，要睡上六个月来消化食物。","t":[5262,10512]}]},{"id":"ch01p02","audio":true,"sents":[{"en":"I pondered deeply, then, over the adventures of the jungle.","zh":"于是，我深深地思考着丛林中的冒险故事。","t":[138,4212]},{"en":"And after some work with a coloured pencil I succeeded in making my first drawing.","zh":"经过一番用彩色铅笔的功夫，我成功地画出了我的第一幅画。","t":[4212,9150]},{"en":"My Drawing Number One.","zh":"我的第一号画。","t":[9150,11000]},{"en":"It looked like this:","zh":"它看起来是这样的：","t":[11000,12188]}]},{"id":"ch01p03","audio":true,"sents":[{"en":"I showed my masterpiece to the grown-ups, and asked them whether the drawing frightened them.","zh":"我把我的杰作给大人们看，问他们这幅画是否吓到他们了。","t":[138,4900]}]},{"id":"ch01p04","audio":true,"sents":[{"en":"But they answered: \"Frighten?","zh":"但他们回答说：'吓到？","t":[100,2362]},{"en":"Why should any one be frightened by a hat?\"","zh":"谁会害怕一顶帽子呢？","t":[2362,4813]}]},{"id":"ch01p05","audio":true,"sents":[{"en":"My drawing was not a picture of a hat.","zh":"我的画不是一顶帽子的画。","t":[112,2850]},{"en":"It was a picture of a boa constrictor digesting an elephant.","zh":"它是一幅蟒蛇正在消化大象的画。","t":[2850,6838]},{"en":"But since the grown-ups were not able to understand it, I made another drawing: I drew the inside of the boa constrictor, so that the grown-ups could see it clearly.","zh":"但是因为大人们无法理解，我又画了另一幅画：我画了蟒蛇的内部，这样大人们就能清楚地看到了。","t":[6838,15700]},{"en":"They always need to have things explained.","zh":"他们总是需要有人给他们解释。","t":[15700,18275]},{"en":"My Drawing Number Two looked like this:","zh":"我的第二幅画看起来是这样的：","t":[18275,20525]}]},{"id":"ch01p06","audio":true,"sents":[{"en":"The grown-ups' response, this time, was to advise me to lay aside my drawings of boa constrictors, whether from the inside or the outside, and devote myself instead to geography, history, arithmetic and grammar.","zh":"这次大人们的反应是建议我把画蟒蛇的画放下，无论是从内部还是外部，而是应该致力于地理、历史、算术和语法。","t":[138,12875]},{"en":"That is why, at the age of six, I gave up what might have been a magnificent career as a painter.","zh":"这就是为什么在六岁的时候，我放弃了可能成为一名伟大画家的职业生涯。","t":[12875,18888]},{"en":"I had been disheartened by the failure of my Drawing Number One and my Drawing Number Two.","zh":"我的第一幅和第二幅画的失败让我感到灰心。","t":[18888,24188]},{"en":"Grown-ups never understand anything by themselves, and it is tiresome for children to be always and forever explaining things to them.","zh":"大人们自己从来不会理解任何事情，而孩子们总是不断地向他们解释，这很令人厌烦。","t":[24188,31500]}]},{"id":"ch01p07","audio":true,"sents":[{"en":"So then I chose another profession, and learned to pilot airplanes.","zh":"所以我选择了另一份职业，学会了驾驶飞机。","t":[125,4388]},{"en":"I have flown a little over all parts of the world; and it is true that geography has been very useful to me.","zh":"我飞遍世界的各个角落；地理学对我确实非常有用。","t":[4388,10600]},{"en":"At a glance I can distinguish China from Arizona.","zh":"一眼就能分辨出中国和亚利桑那。","t":[10600,14238]},{"en":"If one gets lost in the night, such knowledge is valuable.","zh":"如果在夜晚迷路，这样的知识就很有价值。","t":[14238,17650]}]},{"id":"ch01p08","audio":true,"sents":[{"en":"In the course of this life I have had a great many encounters with a great many people who have been concerned with matters of consequence.","zh":"在我的一生中，我与许多关心重要事务的人有过许多遭遇。","t":[112,7388]},{"en":"I have lived a great deal among grown-ups.","zh":"我在成年人中间生活了很多。","t":[7388,10212]},{"en":"I have seen them intimately, close at hand.","zh":"我近距离地观察过他们。","t":[10212,13400]},{"en":"And that hasn't much improved my opinion of them.","zh":"但这并没有改善我对他们的看法。","t":[13400,16113]}]},{"id":"ch01p09","audio":true,"sents":[{"en":"Whenever I met one of them who seemed to me at all clear-sighted, I tried the experiment of showing him my Drawing Number One, which I have always kept.","zh":"每当遇到一个在我看来有点洞察力的人，我就尝试向他展示我始终保留的我的第一幅画。","t":[138,8312]},{"en":"I would try to find out, so, if this was a person of true understanding.","zh":"我想找出，这样，这个人是否真的有理解力。","t":[8312,13062]},{"en":"But, whoever it was, he, or she, would always say: \"That is a hat.\"","zh":"但不管是谁，他或她总是会说：'那是一顶帽子。'","t":[13062,17774]}]},{"id":"ch01p10","audio":true,"sents":[{"en":"Then I would never talk to that person about boa constrictors, or primeval forests, or stars.","zh":"然后我就永远不再和那个人谈论蟒蛇、原始森林或者星星了。","t":[138,6188]},{"en":"I would bring myself down to his level.","zh":"我会降低自己的标准。","t":[6188,8800]},{"en":"I would talk to him about bridge, and golf, and politics, and neckties.","zh":"我会和他谈论桥牌、高尔夫、政治和领带。","t":[8800,13750]},{"en":"And the grown-up would be greatly pleased to have met such a sensible man.","zh":"而这个大人会很高兴遇到这样一个明智的人。","t":[13750,17624]}]}]},{"id":"ch02","title_en":"Chapter II","title_zh":"第 2 章","paras":[{"id":"ch02p00","audio":true,"sents":[{"en":"So I lived my life alone, without anyone that I could really talk to, until I had an accident with my plane in the Desert of Sahara, six years ago.","zh":"所以我在没有真正可以交谈的人的孤独中生活，直到六年前我在撒哈拉沙漠的飞机事故。","t":[138,8812]},{"en":"Something was broken in my engine.","zh":"我的引擎出了问题。","t":[8812,11175]},{"en":"And as I had with me neither a mechanic nor any passengers, I set myself to attempt the difficult repairs all alone.","zh":"因为我既没有机械师也没有乘客，我就独自尝试进行困难的修理。","t":[11175,18238]},{"en":"It was a question of life or death for me: I had scarcely enough drinking water to last a week.","zh":"对我来说，这是生与死的考验：我几乎没有足够的饮用水维持一周。","t":[18238,23888]},{"en":"The first night, then, I went to sleep on the sand, a thousand miles from any human habitation.","zh":"于是，第一个夜晚，我在离任何人类居住地一千英里的沙地上睡觉。","t":[23888,30138]},{"en":"I was more isolated than a shipwrecked sailor on a raft in the middle of the ocean.","zh":"我比在海洋中央的木筏上的遇险水手还要孤独。","t":[30138,35088]},{"en":"Thus you can imagine my amazement, at sunrise, when I was awakened by an odd little voice.","zh":"因此，你可以想象我在黎明时分被一个奇怪的小声音唤醒时的惊讶。","t":[35088,40950]},{"en":"It said:","zh":"它说：","t":[40950,41626]}]},{"id":"ch02p01","audio":true,"sents":[{"en":"\"If you please-- draw me a sheep!\"","zh":"“如果你愿意——给我画一只羊！”","t":[112,1800]}]},{"id":"ch02p02","audio":true,"sents":[{"en":"\"What!\"","zh":"“什么！”","t":[112,500]}]},{"id":"ch02p03","audio":true,"sents":[{"en":"\"Draw me a sheep!\"","zh":"“给我画一只羊！”","t":[112,1100]}]},{"id":"ch02p04","audio":true,"sents":[{"en":"I jumped to my feet, completely thunderstruck.","zh":"我跳了起来，完全震惊了。","t":[138,3462]},{"en":"I blinked my eyes hard.","zh":"我用力地眨了眨眼睛。","t":[3462,5400]},{"en":"I looked carefully all around me.","zh":"我仔细地环顾四周。","t":[5400,7738]},{"en":"And I saw a most extraordinary small person, who stood there examining me with great seriousness.","zh":"我看到一个非常奇特的小人，他站在那里，非常认真地打量着我。","t":[7738,13662]},{"en":"Here you may see the best portrait that, later, I was able to make of him.","zh":"这里你可以看到我后来能画出的他最好的画像。","t":[13662,18312]},{"en":"But my drawing is certainly very much less charming than its model.","zh":"但我的画当然远不如它的原型迷人。","t":[18312,22050]}]},{"id":"ch02p05","audio":true,"sents":[{"en":"That, however, is not my fault.","zh":"然而，这并不是我的错。","t":[138,3025]},{"en":"The grown-ups discouraged me in my painter's career when I was six years old, and I never learned to draw anything, except boas from the outside and boas from the inside.","zh":"在我六岁的时候，大人就阻止我从事画家的生涯，我从未学会画任何东西，除了从外面看和从里面看的蛇。","t":[3025,12125]}]},{"id":"ch02p06","audio":true,"sents":[{"en":"Now I stared at this sudden apparition with my eyes fairly starting out of my head in astonishment.","zh":"现在，我惊讶地盯着这个突如其来的身影，几乎要惊得眼睛都瞪出来了。","t":[112,5938]},{"en":"Remember, I had crashed in the desert a thousand miles from any inhabited region.","zh":"记住，我在离任何有人居住的地方一千英里的沙漠中坠毁了。","t":[5938,11150]},{"en":"And yet my little man seemed neither to be straying uncertainly among the sands, nor to be fainting from fatigue or hunger or thirst or fear.","zh":"然而，我的小家伙似乎既没有在沙子里迷失方向，也没有因为疲劳、饥饿、口渴或恐惧而昏倒。","t":[11150,19350]},{"en":"Nothing about him gave any suggestion of a child lost in the middle of the desert, a thousand miles from any human habitation.","zh":"他身上没有任何迹象表明他是个在沙漠中间迷失的孩子，离任何人类居住地都有千里之遥。","t":[19350,26862]},{"en":"When at last I was able to speak, I said to him:","zh":"当我终于能够说话时，我对他说：","t":[26862,29863]}]},{"id":"ch02p07","audio":true,"sents":[{"en":"\"But-- what are you doing here?\"","zh":"“但——你在这里做什么？”","t":[100,1574]}]},{"id":"ch02p08","audio":true,"sents":[{"en":"And in answer he repeated, very slowly, as if he were speaking of a matter of great consequence:","zh":"作为回答，他非常缓慢地重复，仿佛在谈论一件非常重要的事情：","t":[138,5788]}]},{"id":"ch02p09","audio":true,"sents":[{"en":"\"If you please-- draw me a sheep...\"","zh":"如果您愿意——给我画一只羊...","t":[112,1887]}]},{"id":"ch02p10","audio":true,"sents":[{"en":"When a mystery is too overpowering, one dare not disobey.","zh":"当谜团太过强烈时，人们不敢违抗。","t":[138,4225]},{"en":"Absurd as it might seem to me, a thousand miles from any human habitation and in danger of death, I took out of my pocket a sheet of paper and my fountain pen.","zh":"虽然在我看来这很荒谬，远离任何人类居住地，面临死亡的危险，我还是从口袋里掏出了一张纸和我的钢笔。","t":[4225,13550]},{"en":"But then I remembered how my studies had been concentrated on geography, history, arithmetic, and grammar, and I told the little chap (a little crossly, too) that I did not know how to draw.","zh":"但随后我想起了我的研究主要集中在地理、历史、算术和语法上，于是我对这个小家伙（有点生气地）说，我不知道怎么画。","t":[13550,24838]},{"en":"He answered me:","zh":"他回答我：","t":[24838,25800]}]},{"id":"ch02p11","audio":true,"sents":[{"en":"\"That doesn't matter.","zh":"“那没关系。","t":[138,1688]},{"en":"Draw me a sheep...\"","zh":"给我画一只羊...","t":[1688,2787]}]},{"id":"ch02p12","audio":true,"sents":[{"en":"But I had never drawn a sheep.","zh":"但我从未画过羊。","t":[100,2288]},{"en":"So I drew for him one of the two pictures I had drawn so often.","zh":"所以我画给他的是我经常画的两幅画之一。","t":[2288,6375]},{"en":"It was that of the boa constrictor from the outside.","zh":"那是外面的大蟒蛇。","t":[6375,9738]},{"en":"And I was astounded to hear the little fellow greet it with,","zh":"我惊讶地听到这个小家伙问候它说，","t":[9738,12887]}]},{"id":"ch02p13","audio":true,"sents":[{"en":"\"No, no, no!","zh":"不，不，不！","t":[112,1988]},{"en":"I do not want an elephant inside a boa constrictor.","zh":"我不想在一条蟒蛇里面有一只大象。","t":[1988,5488]},{"en":"A boa constrictor is a very dangerous creature, and an elephant is very cumbersome.","zh":"蟒蛇是一种非常危险的生物，而大象非常笨重。","t":[5488,10800]},{"en":"Where I live, everything is very small.","zh":"在我住的地方，一切都是非常小的。","t":[10800,13738]},{"en":"What I need is a sheep.","zh":"我需要的是一只绵羊。","t":[13738,15500]},{"en":"Draw me a sheep.\"","zh":"给我画一只绵羊。","t":[15500,16550]}]},{"id":"ch02p14","audio":true,"sents":[{"en":"So then I made a drawing.","zh":"于是我画了一幅画。","t":[125,1563]}]},{"id":"ch02p15","audio":true,"sents":[{"en":"He looked at it carefully, then he said:","zh":"他仔细地看了看，然后说：","t":[138,2438]}]},{"id":"ch02p16","audio":true,"sents":[{"en":"\"No.","zh":"不。","t":[100,1000]},{"en":"This sheep is already very sickly.","zh":"这只羊已经病得很重了。","t":[1000,3450]},{"en":"Make me another.\"","zh":"再给我画一个。","t":[3450,4475]}]},{"id":"ch02p17","audio":true,"sents":[{"en":"So I made another drawing.","zh":"所以我再画了一张。","t":[112,1700]}]},{"id":"ch02p18","audio":true,"sents":[{"en":"My friend smiled gently and indulgently.","zh":"我的朋友温和而宽容地笑了笑。","t":[125,2888]}]},{"id":"ch02p19","audio":true,"sents":[{"en":"\"You see yourself,\" he said, \"that this is not a sheep.","zh":"你看，你自己也明白，这不是一只羊。","t":[138,3750]},{"en":"This is a ram.","zh":"这是一只公羊。","t":[3750,5100]},{"en":"It has horns.\"","zh":"它有角。","t":[5100,6050]}]},{"id":"ch02p20","audio":true,"sents":[{"en":"So then I did my drawing over once more.","zh":"所以我再次重新画了我的画。","t":[125,2525]}]},{"id":"ch02p21","audio":true,"sents":[{"en":"But it was rejected too, just like the others.","zh":"但它也被拒绝了，就像其他的画一样。","t":[100,2937]}]},{"id":"ch02p22","audio":true,"sents":[{"en":"\"This one is too old.","zh":"这个太老了。","t":[138,1912]},{"en":"I want a sheep that will live a long time.\"","zh":"我想要一只能活很久的羊。","t":[1912,4088]}]},{"id":"ch02p23","audio":true,"sents":[{"en":"By this time my patience was exhausted, because I was in a hurry to start taking my engine apart.","zh":"这时我的耐心已经耗尽，因为我急于开始拆解我的引擎。","t":[100,5775]}]},{"id":"ch02p24","audio":true,"sents":[{"en":"So I tossed off this drawing.","zh":"所以我随手画了这张画。","t":[112,2225]},{"en":"And I threw out an explanation with it.","zh":"我还附上了相应的解释。","t":[2225,4475]}]},{"id":"ch02p25","audio":true,"sents":[{"en":"\"This is only his box.","zh":"这只是他的箱子。","t":[138,1975]},{"en":"The sheep you asked for is inside.\"","zh":"你要的羊就在里面。","t":[1975,4088]}]},{"id":"ch02p26","audio":true,"sents":[{"en":"I was very surprised to see a light break over the face of my young judge:","zh":"看到我的年轻法官脸上露出的光芒，我非常惊讶：","t":[138,4263]}]},{"id":"ch02p27","audio":true,"sents":[{"en":"\"That is exactly the way I wanted it!","zh":"这正是我想要的样子！","t":[138,2688]},{"en":"Do you think that this sheep will have to have a great deal of grass?\"","zh":"你认为这只羊需要很多草吗？","t":[2688,6025]}]},{"id":"ch02p28","audio":true,"sents":[{"en":"\"Why?\"","zh":"为什么？","t":[125,625]}]},{"id":"ch02p29","audio":true,"sents":[{"en":"\"Because where I live everything is very small...\"","zh":"因为在我住的地方，一切都很小...","t":[138,2763]}]},{"id":"ch02p30","audio":true,"sents":[{"en":"\"There will surely be enough grass for him,\" I said.","zh":"我告诉他，‘他那里肯定有足够的草。’","t":[138,3262]},{"en":"\"It is a very small sheep that I have given you.\"","zh":"我给你的是一只非常小的羊。","t":[3262,5862]}]},{"id":"ch02p31","audio":true,"sents":[{"en":"He bent his head over the drawing:","zh":"他低头看着这幅画：","t":[138,2000]}]},{"id":"ch02p32","audio":true,"sents":[{"en":"\"Not so small that-- Look!","zh":"不是那么小，看！","t":[112,2000]},{"en":"He has gone to sleep...\"","zh":"他已经睡着了...","t":[2000,3275]}]},{"id":"ch02p33","audio":true,"sents":[{"en":"And that is how I made the acquaintance of the little prince.","zh":"就这样，我认识了小王子。","t":[112,3200]}]}]},{"id":"ch03","title_en":"Chapter III","title_zh":"第 3 章","paras":[{"id":"ch03p00","audio":true,"sents":[{"en":"It took me a long time to learn where he came from.","zh":"我花了很长时间才弄清楚他来自哪里。","t":[138,3225]},{"en":"The little prince, who asked me so many questions, never seemed to hear the ones I asked him.","zh":"小王子问了我那么多问题，却似乎从未听到过我问他的问题。","t":[3225,8888]},{"en":"It was from words dropped by chance that, little by little, everything was revealed to me.","zh":"正是通过偶然掉落的话语，一点一滴，一切逐渐向我揭露。","t":[8888,14037]}]},{"id":"ch03p01","audio":true,"sents":[{"en":"The first time he saw my airplane, for instance (I shall not draw my airplane; that would be much too complicated for me), he asked me:","zh":"他第一次看到我的飞机时，例如（我不会画我的飞机；那对我来说太复杂了），他问我：","t":[138,7738]}]},{"id":"ch03p02","audio":true,"sents":[{"en":"\"What is that object?\"","zh":"那是什么东西？","t":[100,1526]}]},{"id":"ch03p03","audio":true,"sents":[{"en":"\"That is not an object.","zh":"那不是东西。","t":[138,1938]},{"en":"It flies.","zh":"它会飞。","t":[1938,3125]},{"en":"It is an airplane.","zh":"那是一架飞机。","t":[3125,4675]},{"en":"It is my airplane.\"","zh":"那是我飞机。","t":[4675,5962]}]},{"id":"ch03p04","audio":true,"sents":[{"en":"And I was proud to have him learn that I could fly.","zh":"我很自豪他了解到我会飞。","t":[138,2838]}]},{"id":"ch03p05","audio":true,"sents":[{"en":"He cried out, then:","zh":"然后他喊道：","t":[112,1587]}]},{"id":"ch03p06","audio":true,"sents":[{"en":"\"What!","zh":"什么！","t":[112,875]},{"en":"You dropped down from the sky?\"","zh":"你是从天上掉下来的？","t":[875,2613]}]},{"id":"ch03p07","audio":true,"sents":[{"en":"\"Yes,\" I answered, modestly.","zh":"是的，我谦虚地回答。","t":[125,2475]}]},{"id":"ch03p08","audio":true,"sents":[{"en":"\"Oh!","zh":"哦！","t":[100,762]},{"en":"That is funny!\"","zh":"这很有趣！","t":[762,1675]}]},{"id":"ch03p09","audio":true,"sents":[{"en":"And the little prince broke into a lovely peal of laughter, which irritated me very much.","zh":"小王子突然发出一阵可爱的笑声，这让我非常恼火。","t":[138,5450]},{"en":"I like my misfortunes to be taken seriously.","zh":"我喜欢我的不幸被认真对待。","t":[5450,8288]}]},{"id":"ch03p10","audio":true,"sents":[{"en":"Then he added:","zh":"然后他又说：","t":[138,1137]}]},{"id":"ch03p11","audio":true,"sents":[{"en":"\"So you, too, come from the sky!","zh":"那么，你也来自天空！","t":[112,2838]},{"en":"Which is your planet?\"","zh":"你的星球是哪个？","t":[2838,4100]}]},{"id":"ch03p12","audio":true,"sents":[{"en":"At that moment I caught a gleam of light in the impenetrable mystery of his presence; and I demanded, abruptly:","zh":"那一刻，我在他不可穿透的存在之谜中捕捉到了一丝光芒；我突然问道：","t":[138,6474]}]},{"id":"ch03p13","audio":true,"sents":[{"en":"\"Do you come from another planet?\"","zh":"你是从另一个星球来的吗？","t":[100,1950]}]},{"id":"ch03p14","audio":true,"sents":[{"en":"But he did not reply.","zh":"但他没有回答。","t":[100,1938]},{"en":"He tossed his head gently, without taking his eyes from my plane:","zh":"他轻轻摇了摇头，目光始终没有离开我的飞机：","t":[1938,5687]}]},{"id":"ch03p15","audio":true,"sents":[{"en":"\"It is true that on that you can't have come from very far away...\"","zh":"“确实，从那里你不可能来自很远的距离……”","t":[138,3600]}]},{"id":"ch03p16","audio":true,"sents":[{"en":"And he sank into a reverie, which lasted a long time.","zh":"然后，他陷入了沉思，这沉思持续了很长时间。","t":[138,3762]},{"en":"Then, taking my sheep out of his pocket, he buried himself in the contemplation of his treasure.","zh":"接着，他从口袋里拿出我的羊，一头扎进了对这笔财富的沉思中。","t":[3762,9250]}]},{"id":"ch03p17","audio":true,"sents":[{"en":"You can imagine how my curiosity was aroused by this half-confidence about the \"other planets.\" I made a great effort, therefore, to find out more on this subject.","zh":"你可以想象，我对‘其他星球’的这种半信半疑感到多么好奇。因此，我努力想了解更多关于这个话题。","t":[112,9900]}]},{"id":"ch03p18","audio":true,"sents":[{"en":"\"My little man, where do you come from?","zh":"“我的小家伙，你从哪里来？","t":[112,2775]},{"en":"What is this 'where I live,' of which you speak?","zh":"你说的‘我住在哪里’是什么意思？","t":[2775,5825]},{"en":"Where do you want to take your sheep?\"","zh":"你打算把你的羊带到哪里去？","t":[5825,7488]}]},{"id":"ch03p19","audio":true,"sents":[{"en":"After a reflective silence he answered:","zh":"经过一段沉思的沉默后，他回答道：","t":[112,2513]}]},{"id":"ch03p20","audio":true,"sents":[{"en":"\"The thing that is so good about the box you have given me is that at night he can use it as his house.\"","zh":"你给我的这个盒子这么好的地方就是，晚上他可以用它作为自己的房子。","t":[138,5388]}]},{"id":"ch03p21","audio":true,"sents":[{"en":"\"That is so.","zh":"那当然。","t":[125,1362]},{"en":"And if you are good I will give you a string, too, so that you can tie him during the day, and a post to tie him to.\"","zh":"如果你表现好，我也会给你一条绳子，这样你可以在白天把他拴起来，还有一个柱子来拴他。","t":[1362,7575]}]},{"id":"ch03p22","audio":true,"sents":[{"en":"But the little prince seemed shocked by this offer:","zh":"但小王子对这个提议似乎感到震惊：","t":[100,2750]}]},{"id":"ch03p23","audio":true,"sents":[{"en":"\"Tie him!","zh":"把他拴起来！","t":[112,1062]},{"en":"What a queer idea!\"","zh":"多么奇怪的想法！","t":[1062,2274]}]},{"id":"ch03p24","audio":true,"sents":[{"en":"\"But if you don't tie him,\" I said, \"he will wander off somewhere, and get lost.\"","zh":"但我告诉你，如果你不把他拴起来，他会跑到某个地方去，然后迷路的。","t":[100,4663]}]},{"id":"ch03p25","audio":true,"sents":[{"en":"My friend broke into another peal of laughter:","zh":"我的朋友又大笑起来：","t":[112,2787]}]},{"id":"ch03p26","audio":true,"sents":[{"en":"\"But where do you think he would go?\"","zh":"但你想他会去哪里？","t":[100,1863]}]},{"id":"ch03p27","audio":true,"sents":[{"en":"\"Anywhere.","zh":"任何地方。","t":[112,1112]},{"en":"Straight ahead of him.\"","zh":"正前方。","t":[1112,2412]}]},{"id":"ch03p28","audio":true,"sents":[{"en":"Then the little prince said, earnestly:","zh":"然后小王子认真地说道：","t":[138,2462]}]},{"id":"ch03p29","audio":true,"sents":[{"en":"\"That doesn't matter.","zh":"那不重要。","t":[138,1700]},{"en":"Where I live, everything is so small!\"","zh":"在我生活的星球上，一切都是那么小！","t":[1700,4074]}]},{"id":"ch03p30","audio":true,"sents":[{"en":"And, with perhaps a hint of sadness, he added:","zh":"他带着一丝悲伤，又补充道：","t":[138,3263]}]},{"id":"ch03p31","audio":true,"sents":[{"en":"\"Straight ahead of him, nobody can go very far...\"","zh":"正前方，没有人能走得很远……","t":[125,3188]}]}]},{"id":"ch04","title_en":"Chapter IV","title_zh":"第 4 章","paras":[{"id":"ch04p00","audio":true,"sents":[{"en":"I had thus learned a second fact of great importance: this was that the planet the little prince came from was scarcely any larger than a house!","zh":"因此，我又了解了一个非常重要的事实：小王子来自的那个星球几乎和一座房子一样大！","t":[138,7825]}]},{"id":"ch04p01","audio":true,"sents":[{"en":"But that did not really surprise me much.","zh":"但这并没有让我感到特别惊讶。","t":[100,2838]},{"en":"I knew very well that in addition to the great planets-- such as the Earth, Jupiter, Mars, Venus-- to which we have given names, there are also hundreds of others, some of which are so small that one has a hard time seeing them through the telescope.","zh":"我非常清楚，除了我们给起名字的大行星——比如地球、木星、火星、金星——之外，还有数百个其他星球，其中一些非常小，以至于通过望远镜也很难看到。","t":[2838,15925]},{"en":"When an astronomer discovers one of these he does not give it a name, but only a number.","zh":"当一个天文学家发现这些星球中的一个时，他不会给它起名字，而只是给它一个数字。","t":[15925,21100]},{"en":"He might call it, for example, \"Asteroid 325.\"","zh":"他可能会称它为，比如说，‘小行星325号’。","t":[21100,24913]}]},{"id":"ch04p02","audio":true,"sents":[{"en":"I have serious reason to believe that the planet from which the little prince came is the asteroid known as B-612.","zh":"我有充分的理由相信，小王子来自的那个星球就是那个被称为B-612的小行星。","t":[138,6700]}]},{"id":"ch04p03","audio":true,"sents":[{"en":"This asteroid has only once been seen through the telescope.","zh":"这个小行星只有一次被望远镜看到过。","t":[125,4025]},{"en":"That was by a Turkish astronomer, in 1909.","zh":"那是在1909年，是一位土耳其天文学家看到的。","t":[4025,7313]}]},{"id":"ch04p04","audio":true,"sents":[{"en":"On making his discovery, the astronomer had presented it to the International Astronomical Congress, in a great demonstration.","zh":"在发现这个星球后，天文学家曾向国际天文学大会展示了他的发现。","t":[138,7750]},{"en":"But he was in Turkish costume, and so nobody would believe what he said.","zh":"但他穿着土耳其服装，所以没有人相信他的话。","t":[7750,11813]}]},{"id":"ch04p05","audio":true,"sents":[{"en":"Grown-ups are like that...","zh":"大人就是这样...","t":[100,1575]}]},{"id":"ch04p06","audio":true,"sents":[{"en":"Fortunately, however, for the reputation of Asteroid B-612, a Turkish dictator made a law that his subjects, under pain of death, should change to European costume.","zh":"然而，幸运的是，为了B-612小行星的名誉，一位土耳其独裁者制定了一项法律，规定他的臣民必须改穿欧洲服装，否则将面临死刑。","t":[125,10700]},{"en":"So in 1920 the astronomer gave his demonstration all over again, dressed with impressive style and elegance.","zh":"所以，在1920年，天文学家再次进行了他的展示，这次他穿着令人印象深刻的风格和优雅。","t":[10700,17888]},{"en":"And this time everybody accepted his report.","zh":"这一次，每个人都接受了他的报告。","t":[17888,20725]}]},{"id":"ch04p07","audio":true,"sents":[{"en":"If I have told you these details about the asteroid, and made a note of its number for you, it is on account of the grown-ups and their ways.","zh":"如果我向你讲述了关于这颗小行星的细节，并为你记下了它的编号，那是因为成年人和他们的方式。","t":[138,7812]},{"en":"When you tell them that you have made a new friend, they never ask you any questions about essential matters.","zh":"当你告诉他们你交了一个新朋友时，他们永远不会问你关于重要的事情。","t":[7812,13712]},{"en":"They never say to you, \"What does his voice sound like?","zh":"他们永远不会问你，‘他的声音听起来像什么？’","t":[13712,17088]},{"en":"What games does he love best?","zh":"他最喜欢玩什么游戏？","t":[17088,19275]},{"en":"Does he collect butterflies?\" Instead, they demand: \"How old is he?","zh":"他收集蝴蝶吗？’相反，他们会要求：‘他多大了？’","t":[19275,24600]},{"en":"How many brothers has he?","zh":"他有多少个兄弟？","t":[24600,26562]},{"en":"How much does he weigh?","zh":"他有多重？","t":[26562,28275]},{"en":"How much money does his father make?\" Only from these figures do they think they have learned anything about him.","zh":"他父亲赚多少钱？’只有从这些数字中，他们才认为自己了解了他。","t":[28275,34362]}]},{"id":"ch04p08","audio":true,"sents":[{"en":"If you were to say to the grown-ups: \"I saw a beautiful house made of rosy brick, with geraniums in the windows and doves on the roof,\" they would not be able to get any idea of that house at all.","zh":"如果你对成年人说：‘我看到了一栋由玫瑰色砖块建造的美丽房子，窗户里有天竺葵，屋顶上有鸽子，’他们根本无法想象那所房子。","t":[138,10750]},{"en":"You would have to say to them: \"I saw a house that cost $20,000.\" Then they would exclaim: \"Oh, what a pretty house that is!\"","zh":"你不得不对他们说：‘我看到了一栋价值两万美元的房子。’然后他们会惊呼：‘哦，那真是一栋漂亮的房子！’","t":[10750,18713]}]},{"id":"ch04p09","audio":true,"sents":[{"en":"Just so, you might say to them: \"The proof that the little prince existed is that he was charming, that he laughed, and that he was looking for a sheep.","zh":"正因为如此，你们可以对它们说：‘小王子存在的证据是他很迷人，他会笑，他在寻找一只绵羊。’那么告诉他们这些有什么用呢？","t":[100,8188]},{"en":"If anybody wants a sheep, that is a proof that he exists.\" And what good would it do to tell them that?","zh":"如果有人想要一只绵羊，这证明他存在。”那么告诉他们这些有什么用呢？","t":[8188,14725]},{"en":"They would shrug their shoulders, and treat you like a child.","zh":"他们会耸耸肩，把你当作孩子对待。","t":[14725,18212]},{"en":"But if you said to them: \"The planet he came from is Asteroid B-612,\" then they would be convinced, and leave you in peace from their questions.","zh":"但如果你对他们说：‘他来自的星球是B-612号小行星’，他们就会相信，并且不再打扰你。","t":[18212,26100]}]},{"id":"ch04p10","audio":true,"sents":[{"en":"They are like that.","zh":"他们就是这样。","t":[138,1612]},{"en":"One must not hold it against them.","zh":"我们不应该对他们有偏见。","t":[1612,3875]},{"en":"Children should always show great forbearance toward grown-up people.","zh":"孩子们应该总是对大人有极大的耐心。","t":[3875,7662]}]},{"id":"ch04p11","audio":true,"sents":[{"en":"But certainly, for us who understand life, figures are a matter of indifference.","zh":"但当然，对于我们这些理解生活的人来说，数字是无关紧要的。","t":[100,5425]},{"en":"I should have liked to begin this story in the fashion of the fairy-tales.","zh":"我本想以童话故事的方式开始这个故事。","t":[5425,9562]},{"en":"I should have like to say: \"Once upon a time there was a little prince who lived on a planet that was scarcely any bigger than himself, and who had need of a sheep...\"","zh":"我本想这样说：‘从前，有一个小王子，他住在一个几乎和他一样大的星球上，他需要一只绵羊……'","t":[9562,17862]}]},{"id":"ch04p12","audio":true,"sents":[{"en":"To those who understand life, that would have given a much greater air of truth to my story.","zh":"对于那些理解生活的人来说，这会给我的故事增添更多的真实性。","t":[100,5212]}]},{"id":"ch04p13","audio":true,"sents":[{"en":"For I do not want any one to read my book carelessly.","zh":"因为我并不希望有人粗心大意地阅读我的书。","t":[125,3625]},{"en":"I have suffered too much grief in setting down these memories.","zh":"在记录这些回忆的过程中，我承受了太多的悲伤。","t":[3625,7412]},{"en":"Six years have already passed since my friend went away from me, with his sheep.","zh":"自从我的朋友带着他的羊离开我，已经过去了六年。","t":[7412,12325]},{"en":"If I try to describe him here, it is to make sure that I shall not forget him.","zh":"如果我在这里尝试描述他，是为了确保我不会忘记他。","t":[12325,16988]},{"en":"To forget a friend is sad.","zh":"忘记一个朋友是件悲伤的事情。","t":[16988,19038]},{"en":"Not every one has had a friend.","zh":"并不是每个人都曾有过朋友。","t":[19038,21275]},{"en":"And if I forget him, I may become like the grown-ups who are no longer interested in anything but figures...","zh":"如果我把他也忘记了，我可能会变得像那些对任何事物都不再感兴趣的成年人一样...","t":[21275,26874]}]},{"id":"ch04p14","audio":true,"sents":[{"en":"It is for that purpose, again, that I have bought a box of paints and some pencils.","zh":"正是为了这个目的，我又买了一盒颜料和一些铅笔。","t":[138,5288]},{"en":"It is hard to take up drawing again at my age, when I have never made any pictures except those of the boa constrictor from the outside and the boa constrictor from the inside, since I was six.","zh":"在我这个年纪重新拿起画笔是很难的，自从我六岁以来，我除了画过外面和里面的蟒蛇之外，再也没有画过任何图画。","t":[5288,15875]},{"en":"I shall certainly try to make my portraits as true to life as possible.","zh":"我一定会尽力使我的肖像尽可能逼真。","t":[15875,20288]},{"en":"But I am not at all sure of success.","zh":"但我完全不能保证成功。","t":[20288,22912]},{"en":"One drawing goes along all right, and another has no resemblance to its subject.","zh":"一幅画进展顺利，而另一幅则与它的主题毫无相似之处。","t":[22912,27975]},{"en":"I make some errors, too, in the little prince's height: in one place he is too tall and in another too short.","zh":"我在小王子的身高上也犯了一些错误：在一个地方他太高，在另一个地方他又太矮。","t":[27975,34712]},{"en":"And I feel some doubts about the colours of his costume.","zh":"而且我对他的服装颜色也有些疑虑。","t":[34712,38038]},{"en":"So I fumble along as best I can, now good, now bad, and I hope generally fair-to-middling.","zh":"所以我尽我所能摸索前行，时好时坏，希望总体上还算过得去。","t":[38038,43825]}]},{"id":"ch04p15","audio":true,"sents":[{"en":"In certain more important details I shall make mistakes, also.","zh":"在某些更重要的细节上，我也会犯错。","t":[138,4575]},{"en":"But that is something that will not be my fault.","zh":"但那将不是我的过错。","t":[4575,7538]},{"en":"My friend never explained anything to me.","zh":"我的朋友从未向我解释任何事情。","t":[7538,10438]},{"en":"He thought, perhaps, that I was like himself.","zh":"他或许认为我和他一样。","t":[10438,13850]},{"en":"But I, alas, do not know how to see sheep through the walls of boxes.","zh":"但我，唉，我不知道如何透过箱子墙壁看到绵羊。","t":[13850,18475]},{"en":"Perhaps I am a little like the grown-ups.","zh":"也许我有点像大人。","t":[18475,21125]},{"en":"I have had to grow old.","zh":"我不得不变老。","t":[21125,22575]}]}]},{"id":"ch05","title_en":"Chapter V","title_zh":"第 5 章","paras":[{"id":"ch05p00","audio":true,"sents":[{"en":"As each day passed I would learn, in our talk, something about the little prince's planet, his departure from it, his journey.","zh":"随着每一天的过去，在我们的谈话中，我会了解到关于小王子的星球、他离开星球、他的旅行的点点滴滴。","t":[138,7700]},{"en":"The information would come very slowly, as it might chance to fall from his thoughts.","zh":"信息会非常缓慢地传来，就像它可能偶然从他的思绪中飘落一样。","t":[7700,12675]},{"en":"It was in this way that I heard, on the third day, about the catastrophe of the baobabs.","zh":"就是这样，在第三天，我听说了猴面包树灾难的事。","t":[12675,17687]}]},{"id":"ch05p01","audio":true,"sents":[{"en":"This time, once more, I had the sheep to thank for it.","zh":"这一次，我又得感谢那些绵羊。","t":[125,4012]},{"en":"For the little prince asked me abruptly-- as if seized by a grave doubt-- \"It is true, isn't it, that sheep eat little bushes?\"","zh":"小王子突然问我——仿佛被一个严重的怀疑所困扰——‘真的，不是吗，绵羊会吃小灌木？’","t":[4012,10862]}]},{"id":"ch05p02","audio":true,"sents":[{"en":"\"Yes, that is true.\"","zh":"‘是的，这是真的。’","t":[112,1663]}]},{"id":"ch05p03","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,850]},{"en":"I am glad!\"","zh":"我很高兴！","t":[850,1675]}]},{"id":"ch05p04","audio":true,"sents":[{"en":"I did not understand why it was so important that sheep should eat little bushes.","zh":"我不明白为什么绵羊吃小灌木这么重要。","t":[138,4850]},{"en":"But the little prince added:","zh":"但小王子补充说：","t":[4850,6525]}]},{"id":"ch05p05","audio":true,"sents":[{"en":"\"Then it follows that they also eat baobabs?\"","zh":"那么它们也会吃猴面包树吗？","t":[125,2787]}]},{"id":"ch05p06","audio":true,"sents":[{"en":"I pointed out to the little prince that baobabs were not little bushes, but, on the contrary, trees as big as castles; and that even if he took a whole herd of elephants away with him, the herd would not eat up one single baobab.","zh":"我向小王子指出，猴面包树不是小灌木，相反，它们是像城堡一样大的树；即使他带着一整群大象，这群大象也吃不完一棵猴面包树。","t":[138,12250]}]},{"id":"ch05p07","audio":true,"sents":[{"en":"The idea of the herd of elephants made the little prince laugh.","zh":"大象群的想法让小王子笑了。","t":[138,3726]}]},{"id":"ch05p08","audio":true,"sents":[{"en":"\"We would have to put them one on top of the other,\" he said.","zh":"他说，'我们得把它们一个挨一个地堆起来。","t":[138,3187]}]},{"id":"ch05p09","audio":true,"sents":[{"en":"But he made a wise comment:","zh":"但他提出了一个明智的评论：","t":[112,1738]}]},{"id":"ch05p10","audio":true,"sents":[{"en":"\"Before they grow so big, the baobabs start out by being little.\"","zh":"在它们长得如此之大之前，猴面包树最初是小小的。","t":[112,3962]}]},{"id":"ch05p11","audio":true,"sents":[{"en":"\"That is strictly correct,\" I said.","zh":"这完全正确，我说。","t":[138,2712]},{"en":"\"But why do you want the sheep to eat the little baobabs?\"","zh":"但为什么你要让羊吃掉那些小猴面包树呢？","t":[2712,5725]}]},{"id":"ch05p12","audio":true,"sents":[{"en":"He answered me at once, \"Oh, come, come!\", as if he were speaking of something that was self-evident.","zh":"他立刻回答我，'哦，来吧，来吧！'，好像他在谈论一件显而易见的事情。","t":[138,6412]},{"en":"And I was obliged to make a great mental effort to solve this problem, without any assistance.","zh":"我不得不付出极大的精神努力来解决这个难题，没有任何帮助。","t":[6412,11812]}]},{"id":"ch05p13","audio":true,"sents":[{"en":"Indeed, as I learned, there were on the planet where the little prince lived-- as on all planets-- good plants and bad plants.","zh":"实际上，正如我所了解的，在小王子居住的星球上——就像所有星球一样——有好的植物和坏的植物。","t":[138,7112]},{"en":"In consequence, there were good seeds from good plants, and bad seeds from bad plants.","zh":"因此，有来自好植物的良种，也有来自坏植物的劣种。","t":[7112,12550]},{"en":"But seeds are invisible.","zh":"但是种子是看不见的。","t":[12550,14562]},{"en":"They sleep deep in the heart of the earth's darkness, until some one among them is seized with the desire to awaken.","zh":"它们在地球黑暗的深处沉睡，直到其中的一颗被唤醒的欲望所抓住。","t":[14562,21062]},{"en":"Then this little seed will stretch itself and begin-- timidly at first-- to push a charming little sprig inoffensively upward toward the sun.","zh":"然后这颗小小的种子会伸展自己，并开始——最初是胆怯地——向太阳推出一个可爱的小嫩芽。","t":[21062,28850]},{"en":"If it is only a sprout of radish or the sprig of a rose-bush, one would let it grow wherever it might wish.","zh":"如果它只是一根萝卜苗或玫瑰丛的嫩枝，人们就会让它随意生长。","t":[28850,35075]},{"en":"But when it is a bad plant, one must destroy it as soon as possible, the very first instant that one recognizes it.","zh":"但是当它是一株坏植物时，人们必须尽快摧毁它，一旦认出它就是如此。","t":[35075,41913]}]},{"id":"ch05p14","audio":true,"sents":[{"en":"Now there were some terrible seeds on the planet that was the home of the little prince; and these were the seeds of the baobab.","zh":"现在，在那个小王子的星球上，有一些可怕的种子；这些就是猴面包树的种子。","t":[125,6638]},{"en":"The soil of that planet was infested with them.","zh":"那个星球的土壤被它们侵占了。","t":[6638,9638]},{"en":"A baobab is something you will never, never be able to get rid of if you attend to it too late.","zh":"如果你太晚注意到了猴面包树，你就永远、永远无法摆脱它们。","t":[9638,15200]},{"en":"It spreads over the entire planet.","zh":"它遍布整个星球。","t":[15200,17662]},{"en":"It bores clear through it with its roots.","zh":"它的根会彻底穿透星球。","t":[17662,20375]},{"en":"And if the planet is too small, and the baobabs are too many, they split it in pieces...","zh":"如果星球太小，猴面包树太多，它们就会把星球分裂成碎片...","t":[20375,25337]}]},{"id":"ch05p15","audio":true,"sents":[{"en":"\"It is a question of discipline,\" the little prince said to me later on.","zh":"‘这是一个纪律问题，’小王子后来对我说。","t":[138,4225]},{"en":"\"When you've finished your own toilet in the morning, then it is time to attend to the toilet of your planet, just so, with the greatest care.","zh":"‘当你早上完成自己的卫生后，那么就是时候以最大的谨慎去照顾你星球的卫生了。","t":[4225,11962]},{"en":"You must see to it that you pull up regularly all the baobabs, at the very first moment when they can be distinguished from the rosebushes which they resemble so closely in their earliest youth.","zh":"你必须确保在它们最初与玫瑰丛如此相似的时候，就定期拔除所有的猴面包树。","t":[11962,22138]},{"en":"It is very tedious work,\" the little prince added, \"but very easy.\"","zh":"这是一件非常乏味的工作，但也很容易。","t":[22138,26274]}]},{"id":"ch05p16","audio":true,"sents":[{"en":"And one day he said to me: \"You ought to make a beautiful drawing, so that the children where you live can see exactly how all this is.","zh":"有一天他对我说：‘你应当画一幅漂亮的画，这样你所在地的孩子们就能确切地看到这一切。’","t":[138,7425]},{"en":"That would be very useful to them if they were to travel some day.","zh":"如果他们有一天要旅行的话，这将会对他们非常有用。","t":[7425,11238]},{"en":"Sometimes,\" he added, \"there is no harm in putting off a piece of work until another day.","zh":"有时候，他补充道，推迟一项工作到另一天也无妨。","t":[11238,16650]},{"en":"But when it is a matter of baobabs, that always means a catastrophe.","zh":"但是，当涉及到猴面包树时，这总是意味着一场灾难。","t":[16650,20962]},{"en":"I knew a planet that was inhabited by a lazy man.","zh":"我认识一个住着懒汉的星球。","t":[20962,24488]},{"en":"He neglected three little bushes...\"","zh":"他忽视了三棵小灌木……","t":[24488,26600]}]},{"id":"ch05p17","audio":true,"sents":[{"en":"So, as the little prince described it to me, I have made a drawing of that planet.","zh":"所以，正如小王子向我描述的那样，我画出了那个星球的画。","t":[125,5338]},{"en":"I do not much like to take the tone of a moralist.","zh":"我不太喜欢摆出一副道德家的样子。","t":[5338,8525]},{"en":"But the danger of the baobabs is so little understood, and such considerable risks would be run by anyone who might get lost on an asteroid, that for once I am breaking through my reserve.","zh":"但是，人们对猴面包树的危险了解得太少，而且任何可能在小行星上迷路的人都会面临巨大的风险，所以这一次我打破了我的沉默。","t":[8525,18775]},{"en":"\"Children,\" I say plainly, \"watch out for the baobabs!\"","zh":"孩子们，我直截了当地说，小心猴面包树！","t":[18775,22063]}]},{"id":"ch05p18","audio":true,"sents":[{"en":"My friends, like myself, have been skirting this danger for a long time, without ever knowing it; and so it is for them that I have worked so hard over this drawing.","zh":"我的朋友们，就像我自己一样，长期以来一直在规避这个危险，却从未意识到；因此，我为了这幅画付出了如此多的努力。","t":[125,9612]},{"en":"The lesson which I pass on by this means is worth all the trouble it has cost me.","zh":"我通过这种方式传授的教训，值得我付出的所有麻烦。","t":[9612,13988]}]},{"id":"ch05p19","audio":true,"sents":[{"en":"Perhaps you will ask me, \"Why are there no other drawing in this book as magnificent and impressive as this drawing of the baobabs?\"","zh":"或许你会问我，‘为什么这本书里没有其他像这幅猴面包树画一样宏伟和令人印象深刻的画？’","t":[100,6887]}]},{"id":"ch05p20","audio":true,"sents":[{"en":"The reply is simple.","zh":"答案很简单。","t":[138,1875]},{"en":"I have tried.","zh":"我尝试过。","t":[1875,3212]},{"en":"But with the others I have not been successful.","zh":"但是，对于其他人，我没有成功。","t":[3212,6288]},{"en":"When I made the drawing of the baobabs I was carried beyond myself by the inspiring force of urgent necessity.","zh":"当我画猴面包树的画时，我被紧急需要的激励力量所驱使，超出了自己的控制。","t":[6288,12463]}]}]},{"id":"ch06","title_en":"Chapter VI","title_zh":"第 6 章","paras":[{"id":"ch06p00","audio":true,"sents":[{"en":"Oh, little prince!","zh":"哦，小王子！","t":[125,1925]},{"en":"Bit by bit I came to understand the secrets of your sad little life...","zh":"一点一点地，我开始理解你那悲伤的小生活的秘密...","t":[1925,6362]},{"en":"For a long time you had found your only entertainment in the quiet pleasure of looking at the sunset.","zh":"长期以来，你唯一的娱乐就是静静地欣赏日落的美景。","t":[6362,12112]},{"en":"I learned that new detail on the morning of the fourth day, when you said to me:","zh":"我在第四天的早晨得知了这个新细节，当时你对我说：","t":[12112,16338]}]},{"id":"ch06p01","audio":true,"sents":[{"en":"\"I am very fond of sunsets.","zh":"我非常喜欢日落。","t":[138,2350]},{"en":"Come, let us go look at a sunset now.\"","zh":"来吧，我们现在去看看日落。","t":[2350,4850]}]},{"id":"ch06p02","audio":true,"sents":[{"en":"\"But we must wait,\" I said.","zh":"但是我们必须等待，我说。","t":[100,1975]}]},{"id":"ch06p03","audio":true,"sents":[{"en":"\"Wait?","zh":"等？","t":[125,1012]},{"en":"For what?\"","zh":"等什么？","t":[1012,1788]}]},{"id":"ch06p04","audio":true,"sents":[{"en":"\"For the sunset.","zh":"等日落。","t":[112,1600]},{"en":"We must wait until it is time.\"","zh":"我们必须等到时间到了。","t":[1600,3538]}]},{"id":"ch06p05","audio":true,"sents":[{"en":"At first you seemed to be very much surprised.","zh":"起初你似乎非常惊讶。","t":[138,3225]},{"en":"And then you laughed to yourself.","zh":"然后你自嘲地笑了。","t":[3225,5262]},{"en":"You said to me:","zh":"你对我说：","t":[5262,6200]}]},{"id":"ch06p06","audio":true,"sents":[{"en":"\"I am always thinking that I am at home!\"","zh":"我总是觉得我是在家里！","t":[138,2388]}]},{"id":"ch06p07","audio":true,"sents":[{"en":"Just so.","zh":"正是如此。","t":[100,1300]},{"en":"Everybody knows that when it is noon in the United States the sun is setting over France.","zh":"每个人都知道，当美国是中午的时候，太阳正在法国落下。","t":[1300,6250]}]},{"id":"ch06p08","audio":true,"sents":[{"en":"If you could fly to France in one minute, you could go straight into the sunset, right from noon.","zh":"如果你能在一分钟内飞到法国，你就可以从中午直接飞向日落。","t":[138,5812]},{"en":"Unfortunately, France is too far away for that.","zh":"不幸的是，对于那个来说，法国太远了。","t":[5812,9262]},{"en":"But on your tiny planet, my little prince, all you need do is move your chair a few steps.","zh":"但在我那小小的星球上，我的小王子，你只需要移动你的椅子几步。","t":[9262,15025]},{"en":"You can see the day end and the twilight falling whenever you like...","zh":"你可以随时看到白天结束，暮色降临...","t":[15025,18700]}]},{"id":"ch06p09","audio":true,"sents":[{"en":"\"One day,\" you said to me, \"I saw the sunset forty-four times!\"","zh":"有一天，你对我说，我看到了四十四次日落！","t":[125,4188]}]},{"id":"ch06p10","audio":true,"sents":[{"en":"And a little later you added:","zh":"然后你稍后补充说：","t":[112,1800]}]},{"id":"ch06p11","audio":true,"sents":[{"en":"\"You know-- one loves the sunset, when one is so sad...\"","zh":"你知道——当一个人非常悲伤时，就会爱上日落……","t":[125,3300]}]},{"id":"ch06p12","audio":true,"sents":[{"en":"\"Were you so sad, then?\" I asked, \"on the day of the forty-four sunsets?\"","zh":"“那么，你那天真的很伤心吗？”我问，“在第四十四个日落的时候？”","t":[112,5226]}]},{"id":"ch06p13","audio":true,"sents":[{"en":"But the little prince made no reply.","zh":"但小王子没有回答。","t":[100,2312]}]}]},{"id":"ch07","title_en":"Chapter VII","title_zh":"第 7 章","paras":[{"id":"ch07p00","audio":true,"sents":[{"en":"On the fifth day-- again, as always, it was thanks to the sheep-- the secret of the little prince's life was revealed to me.","zh":"第五天——就像往常一样，是那只绵羊让我揭开了小王子生活的秘密。","t":[138,6912]},{"en":"Abruptly, without anything to lead up to it, and as if the question had been born of long and silent meditation on his problem, he demanded:","zh":"突然间，没有任何前兆，仿佛这个问题是他长时间沉默沉思自己问题的产物，他问道：","t":[6912,14913]}]},{"id":"ch07p01","audio":true,"sents":[{"en":"\"A sheep-- if it eats little bushes, does it eat flowers, too?\"","zh":"一只羊——如果它吃小灌木，它也吃花吗？","t":[112,3974]}]},{"id":"ch07p02","audio":true,"sents":[{"en":"\"A sheep,\" I answered, \"eats anything it finds in its reach.\"","zh":"“一只羊，”我回答道，“吃它够得着的一切。”","t":[138,3800]}]},{"id":"ch07p03","audio":true,"sents":[{"en":"\"Even flowers that have thorns?\"","zh":"连有刺的花朵呢？","t":[112,1974]}]},{"id":"ch07p04","audio":true,"sents":[{"en":"\"Yes, even flowers that have thorns.\"","zh":"是的，甚至有刺的花朵。","t":[138,2537]}]},{"id":"ch07p05","audio":true,"sents":[{"en":"\"Then the thorns-- what use are they?\"","zh":"“那么，荆棘有什么用呢？”","t":[125,1937]}]},{"id":"ch07p06","audio":true,"sents":[{"en":"I did not know.","zh":"我不知道。","t":[112,1562]},{"en":"At that moment I was very busy trying to unscrew a bolt that had got stuck in my engine.","zh":"那时我正忙着试图拧下一颗卡在我发动机里的螺栓。","t":[1562,6800]},{"en":"I was very much worried, for it was becoming clear to me that the breakdown of my plane was extremely serious.","zh":"我非常担心，因为我的飞机故障变得越来越严重，这一点对我来说已经很明确了。","t":[6800,13175]},{"en":"And I had so little drinking water left that I had to fear for the worst.","zh":"而且我剩下的饮用水如此之少，以至于我不得不担心最坏的情况。","t":[13175,17126]}]},{"id":"ch07p07","audio":true,"sents":[{"en":"\"The thorns-- what use are they?\"","zh":"‘荆棘——它们有什么用？’","t":[138,1724]}]},{"id":"ch07p08","audio":true,"sents":[{"en":"The little prince never let go of a question, once he had asked it.","zh":"小王子一旦提出一个问题，就绝不会放弃。","t":[138,4275]},{"en":"As for me, I was upset over that bolt.","zh":"至于我，我为那个螺栓感到沮丧。","t":[4275,7425]},{"en":"And I answered with the first thing that came into my head:","zh":"我随口回答了第一个出现在脑海中的想法：","t":[7425,10424]}]},{"id":"ch07p09","audio":true,"sents":[{"en":"\"The thorns are of no use at all.","zh":"‘荆棘一点用都没有。","t":[138,2450]},{"en":"Flowers have thorns just for spite!\"","zh":"花长荆棘只是为了发泄！'","t":[2450,4576]}]},{"id":"ch07p10","audio":true,"sents":[{"en":"\"Oh!\"","zh":"哦！","t":[100,412]}]},{"id":"ch07p11","audio":true,"sents":[{"en":"There was a moment of complete silence.","zh":"那一刻，四周一片寂静。","t":[138,2800]},{"en":"Then the little prince flashed back at me, with a kind of resentfulness:","zh":"然后，小王子带着一丝怨恨地回想起我：","t":[2800,6750]}]},{"id":"ch07p12","audio":true,"sents":[{"en":"\"I don't believe you!","zh":"我不相信你！","t":[138,1600]},{"en":"Flowers are weak creatures.","zh":"花儿是脆弱的生物。","t":[1600,3812]},{"en":"They are naive.","zh":"她们天真无邪。","t":[3812,5138]},{"en":"They reassure themselves as best they can.","zh":"她们尽可能地安慰自己。","t":[5138,8075]},{"en":"They believe that their thorns are terrible weapons...\"","zh":"她们相信自己的刺是可怕的武器……","t":[8075,10938]}]},{"id":"ch07p13","audio":true,"sents":[{"en":"I did not answer.","zh":"我没有回答。","t":[138,1688]},{"en":"At that instant I was saying to myself: \"If this bolt still won't turn, I am going to knock it out with the hammer.\" Again the little prince disturbed my thoughts.","zh":"那一刻，我在心里对自己说：'如果这个螺栓还是拧不开，我就用锤子敲开它。' 再次，小王子打断了我在想的事情。","t":[1688,10750]}]},{"id":"ch07p14","audio":true,"sents":[{"en":"\"And you actually believe that the flowers--\"","zh":"“你竟然相信那些花朵——”","t":[112,2350]}]},{"id":"ch07p15","audio":true,"sents":[{"en":"\"Oh, no!\" I cried.","zh":"“哦，不！”我喊道。","t":[112,2525]},{"en":"\"No, no no!","zh":"不，不，不！","t":[2525,4025]},{"en":"I don't believe anything.","zh":"我不相信任何事。","t":[4025,5838]},{"en":"I answered you with the first thing that came into my head.","zh":"我随口就回答了你。","t":[5838,9250]},{"en":"Don't you see-- I am very busy with matters of consequence!\"","zh":"您难道没看见——我正忙于处理一些重要的事情！","t":[9250,12600]}]},{"id":"ch07p16","audio":true,"sents":[{"en":"He stared at me, thunderstruck.","zh":"他瞪大了眼睛，震惊不已。","t":[138,2213]}]},{"id":"ch07p17","audio":true,"sents":[{"en":"\"Matters of consequence!\"","zh":"事关重大！","t":[125,1650]}]},{"id":"ch07p18","audio":true,"sents":[{"en":"He looked at me there, with my hammer in my hand, my fingers black with engine-grease, bending down over an object, which seemed to him extremely ugly...","zh":"他那时在那里看着我，我手里拿着锤子，手指被机油染黑，弯腰俯视着一个在他看来极其丑陋的东西……","t":[138,8575]}]},{"id":"ch07p19","audio":true,"sents":[{"en":"\"You talk just like the grown-ups!\"","zh":"你说话就像大人一样！","t":[138,1975]}]},{"id":"ch07p20","audio":true,"sents":[{"en":"That made me a little ashamed.","zh":"这让我感到有些羞愧。","t":[138,2275]},{"en":"But he went on, relentlessly:","zh":"但他继续说，毫不留情：","t":[2275,4412]}]},{"id":"ch07p21","audio":true,"sents":[{"en":"\"You mix everything up together...","zh":"你把所有的事情都混在一起……","t":[138,2288]},{"en":"You confuse everything...\"","zh":"你把所有的事情都搞混淆了……","t":[2288,3788]}]},{"id":"ch07p22","audio":true,"sents":[{"en":"He was really very angry.","zh":"他真的很生气。","t":[138,2112]},{"en":"He tossed his golden curls in the breeze.","zh":"他在风中摇动着金色的卷发。","t":[2112,4500]}]},{"id":"ch07p23","audio":true,"sents":[{"en":"\"I know a planet where there is a certain red-faced gentleman.","zh":"我知道一个有位红脸绅士的星球。","t":[138,3838]},{"en":"He has never smelled a flower.","zh":"他从未闻过一朵花。","t":[3838,5988]},{"en":"He has never looked at a star.","zh":"他从未看过一颗星星。","t":[5988,8000]},{"en":"He has never loved any one.","zh":"他从未爱过任何人。","t":[8000,10000]},{"en":"He has never done anything in his life but add up figures.","zh":"他一生中从未做过任何事情，只是加减数字。","t":[10000,13600]},{"en":"And all day he says over and over, just like you: 'I am busy with matters of consequence!' And that makes him swell up with pride.","zh":"他整天反复说着，就像你一样：‘我正忙于重要的事情！’这让他非常自豪。","t":[13600,21675]},{"en":"But he is not a man-- he is a mushroom!\"","zh":"但他不是人——他是一朵蘑菇！","t":[21675,23875]}]},{"id":"ch07p24","audio":true,"sents":[{"en":"\"A what?\"","zh":"什么？","t":[112,813]}]},{"id":"ch07p25","audio":true,"sents":[{"en":"\"A mushroom!\"","zh":"一朵蘑菇！","t":[100,912]}]},{"id":"ch07p26","audio":true,"sents":[{"en":"The little prince was now white with rage.","zh":"小王子现在气得脸色苍白。","t":[138,2512]}]},{"id":"ch07p27","audio":true,"sents":[{"en":"\"The flowers have been growing thorns for millions of years.","zh":"花已经长出了刺，已经有几百万年了。","t":[138,3662]},{"en":"For millions of years the sheep have been eating them just the same.","zh":"几百万年来，羊一直这样吃它们。","t":[3662,7538]},{"en":"And is it not a matter of consequence to try to understand why the flowers go to so much trouble to grow thorns, which are never of any use to them?","zh":"试图理解为什么花要费这么大的力气长出永远不会对它们有用的刺，这不是一件重要的事情吗？","t":[7538,15575]},{"en":"Is the warfare between the sheep and the flowers not important?","zh":"羊和花之间的战争难道不重要吗？","t":[15575,19475]},{"en":"Is this not of more consequence than a fat red-faced gentleman's sums?","zh":"这难道不是比一个红脸胖子算的账更重要吗？","t":[19475,23862]},{"en":"And if I know-- I, myself-- one flower which is unique in the world, which grows nowhere but on my planet, but which one little sheep can destroy in a single bite some morning, without even noticing what he is doing-- Oh!","zh":"如果我知道——我自己——世界上有一朵独一无二的花，它只生长在我的星球上，但一只小羊可以在某个早晨一口吃掉它，甚至没有注意到自己在做什么——哦！","t":[23862,35900]},{"en":"You think that is not important!\"","zh":"你以为这不重要！","t":[35900,37737]}]},{"id":"ch07p28","audio":true,"sents":[{"en":"His face turned from white to red as he continued:","zh":"他脸色从苍白变为通红，继续说道：","t":[138,3100]}]},{"id":"ch07p29","audio":true,"sents":[{"en":"\"If some one loves a flower, of which just one single blossom grows in all the millions and millions of stars, it is enough to make him happy just to look at the stars.","zh":"如果有人爱上一朵花，而这朵花在亿万个星星中只生长在一颗星星上，那么仅仅看着星星就足以让他快乐。","t":[138,9250]},{"en":"He can say to himself, 'Somewhere, my flower is there...' But if the sheep eats the flower, in one moment all his stars will be darkened...","zh":"他可以对自己说，‘我的花在那里……’但如果羊吃掉了这朵花，那么一瞬间，他所有的星星都会变得黯淡……","t":[9250,18075]},{"en":"And you think that is not important!\" He could not say anything more.","zh":"你以为这不重要！”他再也无法说更多的话。","t":[18075,22538]},{"en":"His words were choked by sobbing.","zh":"他的话被啜泣声所淹没。","t":[22538,24512]}]},{"id":"ch07p30","audio":true,"sents":[{"en":"The night had fallen.","zh":"夜幕降临。","t":[138,1750]},{"en":"I had let my tools drop from my hands.","zh":"我让我的工具从手中滑落。","t":[1750,4550]},{"en":"Of what moment now was my hammer, my bolt, or thirst, or death?","zh":"我的锤子、螺栓、口渴或死亡现在又有什么意义呢？","t":[4550,9362]},{"en":"On one star, one planet, my planet, the Earth, there was a little prince to be comforted.","zh":"在一颗星星上，一个星球上，我的星球，地球上，有一个小王子需要安慰。","t":[9362,15425]},{"en":"I took him in my arms, and rocked him.","zh":"我把他抱在怀里，摇晃着他。","t":[15425,18050]},{"en":"I said to him:","zh":"我对他说：","t":[18050,19050]}]},{"id":"ch07p31","audio":true,"sents":[{"en":"\"The flower that you love is not in danger.","zh":"你爱的那朵花并没有危险。","t":[138,2950]},{"en":"I will draw you a muzzle for your sheep.","zh":"我会给你画一个嘴套，给你的羊用。","t":[2950,5488]},{"en":"I will draw you a railing to put around your flower.","zh":"我会给你画一个栏杆，围住你的花。","t":[5488,8612]},{"en":"I will--\"","zh":"我会——","t":[8612,9250]}]},{"id":"ch07p32","audio":true,"sents":[{"en":"I did not know what to say to him.","zh":"我不知道该对他说什么。","t":[138,2338]},{"en":"I felt awkward and blundering.","zh":"我觉得自己很尴尬，笨拙不堪。","t":[2338,4550]},{"en":"I did not know how I could reach him, where I could overtake him and go on hand in hand with him once more.","zh":"我不知道该如何找到他，在哪里能追上他，再次与他手牵手同行。","t":[4550,9950]}]},{"id":"ch07p33","audio":true,"sents":[{"en":"It is such a secret place, the land of tears.","zh":"泪之国是一个如此神秘的地方。","t":[138,3025]}]}]},{"id":"ch08","title_en":"Chapter VIII","title_zh":"第 8 章","paras":[{"id":"ch08p00","audio":true,"sents":[{"en":"I soon learned to know this flower better.","zh":"我很快就更好地认识了这朵花。","t":[138,2825]},{"en":"On the little prince's planet the flowers had always been very simple.","zh":"在小王子的星球上，花儿一直都很简单。","t":[2825,7150]},{"en":"They had only one ring of petals; they took up no room at all; they were a trouble to nobody.","zh":"它们只有一圈花瓣；它们一点也不占地方；它们从不麻烦任何人。","t":[7150,12688]},{"en":"One morning they would appear in the grass, and by night they would have faded peacefully away.","zh":"早晨它们会在草丛中出现，到了晚上就会静静地凋谢。","t":[12688,17875]},{"en":"But one day, from a seed blown from no one knew where, a new flower had come up; and the little prince had watched very closely over this small sprout which was not like any other small sprouts on his planet.","zh":"但是有一天，从一颗不知从何而来的种子中，长出了一朵新花；小王子非常仔细地观察着这株小苗，它与他星球上的其他小苗都不一样。","t":[17875,29100]},{"en":"It might, you see, have been a new kind of baobab.","zh":"你知道，它可能是一种新的猴面包树。","t":[29100,32413]}]},{"id":"ch08p01","audio":true,"sents":[{"en":"The shrub soon stopped growing, and began to get ready to produce a flower.","zh":"这株灌木很快就停止了生长，开始准备开花。","t":[138,4700]},{"en":"The little prince, who was present at the first appearance of a huge bud, felt at once that some sort of miraculous apparition must emerge from it.","zh":"小王子在巨大的花苞第一次出现时就在场，他立刻感到某种奇迹般的东西必将从中出现。","t":[4700,13125]},{"en":"But the flower was not satisfied to complete the preparations for her beauty in the shelter of her green chamber.","zh":"但是，那朵花并不满足于在她的绿色小屋中完成她美丽的准备工作。","t":[13125,19550]},{"en":"She chose her colours with the greatest care.","zh":"她非常小心地挑选她的颜色。","t":[19550,22412]},{"en":"She adjusted her petals one by one.","zh":"她一瓣一瓣地调整她的花瓣。","t":[22412,25150]},{"en":"She did not wish to go out into the world all rumpled, like the field poppies.","zh":"她不想出去见世面时还是皱巴巴的，像田野里的罂粟花。","t":[25150,29988]},{"en":"It was only in the full radiance of her beauty that she wished to appear.","zh":"只有在她美丽的光辉中，她才愿意出现。","t":[29988,34125]},{"en":"Oh, yes!","zh":"哦，是的！","t":[34125,35475]},{"en":"She was a coquettish creature!","zh":"她是个爱卖弄风情的小东西！","t":[35475,37475]},{"en":"And her mysterious adornment lasted for days and days.","zh":"而她那神秘的装饰持续了好几天。","t":[37475,40800]}]},{"id":"ch08p02","audio":true,"sents":[{"en":"Then one morning, exactly at sunrise, she suddenly showed herself.","zh":"然后，在一个清晨，正好在日出时分，她突然出现了。","t":[125,4376]}]},{"id":"ch08p03","audio":true,"sents":[{"en":"And, after working with all this painstaking precision, she yawned and said:","zh":"在用这种精细的劳动完成工作后，她打了个哈欠，说：","t":[138,4750]}]},{"id":"ch08p04","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,838]},{"en":"I am scarcely awake.","zh":"我几乎还没醒。","t":[838,2638]},{"en":"I beg that you will excuse me.","zh":"请原谅我。","t":[2638,4838]},{"en":"My petals are still all disarranged...\"","zh":"我的花瓣依然凌乱不堪……","t":[4838,7212]}]},{"id":"ch08p05","audio":true,"sents":[{"en":"But the little prince could not restrain his admiration:","zh":"但小王子无法抑制他的钦佩之情：","t":[100,3275]}]},{"id":"ch08p06","audio":true,"sents":[{"en":"\"Oh!","zh":"哦！","t":[100,800]},{"en":"How beautiful you are!\"","zh":"你真美啊！","t":[800,2050]}]},{"id":"ch08p07","audio":true,"sents":[{"en":"\"Am I not?\" the flower responded, sweetly.","zh":"“难道不是吗？”花朵甜声回应。","t":[125,3562]},{"en":"\"And I was born at the same moment as the sun...\"","zh":"“我和太阳同时诞生……”","t":[3562,6187]}]},{"id":"ch08p08","audio":true,"sents":[{"en":"The little prince could guess easily enough that she was not any too modest-- but how moving-- and exciting-- she was!","zh":"小王子很容易地猜到她并不十分谦虚——但她多么动人——多么令人兴奋啊！","t":[112,6025]}]},{"id":"ch08p09","audio":true,"sents":[{"en":"\"I think it is time for breakfast,\" she added an instant later.","zh":"我想是时候吃早餐了，”她立刻补充道。","t":[138,4162]},{"en":"\"If you would have the kindness to think of my needs--\"","zh":"如果您能体谅我的需求——","t":[4162,6788]}]},{"id":"ch08p10","audio":true,"sents":[{"en":"And the little prince, completely abashed, went to look for a sprinkling-can of fresh water.","zh":"小王子感到非常尴尬，于是去找一罐新鲜水。","t":[138,5788]},{"en":"So, he tended the flower.","zh":"于是，他照料了那朵花。","t":[5788,7687]}]},{"id":"ch08p11","audio":true,"sents":[{"en":"So, too, she began very quickly to torment him with her vanity-- which was, if the truth be known, a little difficult to deal with.","zh":"同样，她也很快开始用她的虚荣心折磨他——如果真相大白，这有点难以应对。","t":[125,8100]},{"en":"One day, for instance, when she was speaking of her four thorns, she said to the little prince:","zh":"有一天，比如当她提到她的四根刺时，她对小王子说：","t":[8100,13537]}]},{"id":"ch08p12","audio":true,"sents":[{"en":"\"Let the tigers come with their claws!\"","zh":"让老虎带着它们的爪子来吧！","t":[112,2175]}]},{"id":"ch08p13","audio":true,"sents":[{"en":"\"There are no tigers on my planet,\" the little prince objected.","zh":"我的星球上没有老虎，”小王子反驳道。","t":[138,4138]},{"en":"\"And, anyway, tigers do not eat weeds.\"","zh":"而且，老虎不吃杂草。","t":[4138,6962]}]},{"id":"ch08p14","audio":true,"sents":[{"en":"\"I am not a weed,\" the flower replied, sweetly.","zh":"我不是杂草，”花朵温柔地回答。","t":[138,3263]}]},{"id":"ch08p15","audio":true,"sents":[{"en":"\"Please excuse me...\"","zh":"请见谅...","t":[112,1312]}]},{"id":"ch08p16","audio":true,"sents":[{"en":"\"I am not at all afraid of tigers,\" she went on, \"but I have a horror of drafts.","zh":"“我一点也不怕老虎，”她继续说，“但我非常讨厌穿堂风。”","t":[138,5225]},{"en":"I suppose you wouldn't have a screen for me?\"","zh":"我想您不会为我准备屏幕吧？","t":[5225,7437]}]},{"id":"ch08p17","audio":true,"sents":[{"en":"\"A horror of drafts-- that is bad luck, for a plant,\" remarked the little prince, and added to himself, \"This flower is a very complex creature...\"","zh":"“对通风的恐惧——这对植物来说是不幸的，”小王子说，然后自言自语道，“这朵花是个非常复杂的生物……”","t":[125,8362]}]},{"id":"ch08p18","audio":true,"sents":[{"en":"\"At night I want you to put me under a glass globe.","zh":"在夜晚，我希望你把我放在玻璃球里。","t":[138,3325]},{"en":"It is very cold where you live.","zh":"你住的地方非常寒冷。","t":[3325,5575]},{"en":"In the place I came from--\"","zh":"在我来自的地方——","t":[5575,7025]}]},{"id":"ch08p19","audio":true,"sents":[{"en":"But she interrupted herself at that point.","zh":"但她在那个时刻打断了自己。","t":[100,2875]},{"en":"She had come in the form of a seed.","zh":"她以一颗种子的形式到来。","t":[2875,5212]},{"en":"She could not have known anything of any other worlds.","zh":"她不可能知道任何其他世界的事情。","t":[5212,8500]},{"en":"Embarrassed over having let herself be caught on the verge of such a naïve untruth, she coughed two or three times, in order to put the little prince in the wrong.","zh":"因为让自己陷入这种天真无知的谎言之中而感到尴尬，她咳嗽了两三声，以便让小王子感到愧疚。","t":[8500,16875]}]},{"id":"ch08p20","audio":true,"sents":[{"en":"\"The screen?\"","zh":"屏幕？","t":[138,862]}]},{"id":"ch08p21","audio":true,"sents":[{"en":"\"I was just going to look for it when you spoke to me...\"","zh":"我正要去找它的时候，你跟我说话了...","t":[138,2737]}]},{"id":"ch08p22","audio":true,"sents":[{"en":"Then she forced her cough a little more so that he should suffer from remorse just the same.","zh":"然后她故意咳嗽得更厉害一些，以便让他也感到悔恨。","t":[138,4688]}]},{"id":"ch08p23","audio":true,"sents":[{"en":"So the little prince, in spite of all the good will that was inseparable from his love, had soon come to doubt her.","zh":"尽管小王子对他的爱充满了善意，但他很快就对她产生了怀疑。","t":[125,6712]},{"en":"He had taken seriously words, which were without importance, and it made him very unhappy.","zh":"他认真地对待了一些无关紧要的话，这让他非常不快乐。","t":[6712,12037]}]},{"id":"ch08p24","audio":true,"sents":[{"en":"\"I ought not to have listened to her,\" he confided to me one day.","zh":"有一天他对我透露说：“我不应该听她的。”","t":[138,4175]},{"en":"\"One never ought to listen to the flowers.","zh":"人们永远都不应该听花说话。","t":[4175,6825]},{"en":"One should simply look at them and breathe their fragrance.","zh":"人们应该只是看看它们，呼吸它们的芬芳。","t":[6825,10250]},{"en":"Mine perfumed all my planet.","zh":"我的玫瑰让我的整个星球都充满了香气。","t":[10250,12588]},{"en":"But I did not know how to take pleasure in all her grace.","zh":"但我不知道如何享受她所有的优雅。","t":[12588,16162]},{"en":"This tale of claws, which disturbed me so much, should only have filled my heart with tenderness and pity.\"","zh":"这个故事关于爪子，它如此困扰我，本应只让我心中充满温柔和同情。","t":[16162,22088]}]},{"id":"ch08p25","audio":true,"sents":[{"en":"And he continued his confidences:","zh":"他继续他的倾诉：","t":[112,2338]}]},{"id":"ch08p26","audio":true,"sents":[{"en":"\"The fact is that I did not know how to understand anything!","zh":"事实上，我不知道如何理解任何东西！","t":[138,3725]},{"en":"I ought to have judged by deeds and not by words.","zh":"我应该通过行动而非言语来判断。","t":[3725,7000]},{"en":"She cast her fragrance and her radiance over me.","zh":"她将她的芬芳和光辉洒在我身上。","t":[7000,10262]},{"en":"I ought never to have run away from her...","zh":"我本不该逃离她...","t":[10262,12875]},{"en":"I ought to have guessed all the affection that lay behind her poor little stratagems.","zh":"我应该猜到她那可怜的小诡计背后所有的深情。","t":[12875,17700]},{"en":"Flowers are so inconsistent!","zh":"花朵是多么的不一致！","t":[17700,20075]},{"en":"But I was too young to know how to love her...\"","zh":"但我太年轻了，不知道如何去爱她...","t":[20075,22500]}]}]},{"id":"ch09","title_en":"Chapter IX","title_zh":"第 9 章","paras":[{"id":"ch09p00","audio":true,"sents":[{"en":"I believe that for his escape he took advantage of the migration of a flock of wild birds.","zh":"我相信，为了逃离，他利用了一群野鸟的迁徙。","t":[138,5812]},{"en":"On the morning of his departure he put his planet in perfect order.","zh":"在他离开的那天早上，他把他的星球整理得井井有条。","t":[5812,9875]},{"en":"He carefully cleaned out his active volcanoes.","zh":"他仔细清理了他的活火山。","t":[9875,13138]},{"en":"He possessed two active volcanoes; and they were very convenient for heating his breakfast in the morning.","zh":"他拥有两个活火山；这对他在早上加热早餐非常方便。","t":[13138,19062]},{"en":"He also had one volcano that was extinct.","zh":"他还有一个已经熄灭的火山。","t":[19062,22262]},{"en":"But, as he said, \"One never knows!\" So he cleaned out the extinct volcano, too.","zh":"但是，正如他说的那样，‘谁也说不准！’所以他也清理了那个熄灭的火山。","t":[22262,28525]},{"en":"If they are well cleaned out, volcanoes burn slowly and steadily, without any eruptions.","zh":"如果清理得当，火山会缓慢而稳定地燃烧，不会发生喷发。","t":[28525,34338]},{"en":"Volcanic eruptions are like fires in a chimney.","zh":"火山喷发就像烟囱里的火。","t":[34338,37263]}]},{"id":"ch09p01","audio":true,"sents":[{"en":"On our earth we are obviously much too small to clean out our volcanoes.","zh":"在我们的地球上，我们显然太小了，无法清理我们的火山。","t":[138,4688]},{"en":"That is why they bring no end of trouble upon us.","zh":"这就是为什么它们给我们带来了无尽的麻烦。","t":[4688,7500]}]},{"id":"ch09p02","audio":true,"sents":[{"en":"The little prince also pulled up, with a certain sense of dejection, the last little shoots of the baobabs.","zh":"小王子也带着一种沮丧的情绪，拔起了最后几株猴面包树的幼苗。","t":[138,6588]},{"en":"He believed that he would never want to return.","zh":"他相信自己永远不会想再回来了。","t":[6588,9475]},{"en":"But on this last morning all these familiar tasks seemed very precious to him.","zh":"但在这个最后的早晨，所有这些熟悉的任务在他看来都变得非常珍贵。","t":[9475,14300]},{"en":"And when he watered the flower for the last time, and prepared to place her under the shelter of her glass globe, he realised that he was very close to tears.","zh":"当他最后一次给花儿浇水，准备把她放在玻璃球罩下保护起来时，他意识到自己快要流泪了。","t":[14300,22413]}]},{"id":"ch09p03","audio":true,"sents":[{"en":"\"Goodbye,\" he said to the flower.","zh":"“再见，”他对花儿说。","t":[100,2137]}]},{"id":"ch09p04","audio":true,"sents":[{"en":"But she made no answer.","zh":"但她没有回答。","t":[100,1562]}]},{"id":"ch09p05","audio":true,"sents":[{"en":"\"Goodbye,\" he said again.","zh":"“再见，”他又说。","t":[112,1750]}]},{"id":"ch09p06","audio":true,"sents":[{"en":"The flower coughed.","zh":"花儿咳嗽了。","t":[112,1612]},{"en":"But it was not because she had a cold.","zh":"但这并不是因为她感冒了。","t":[1612,3687]}]},{"id":"ch09p07","audio":true,"sents":[{"en":"\"I have been silly,\" she said to him, at last.","zh":"“我太傻了，”她终于对他说。","t":[138,3388]},{"en":"\"I ask your forgiveness.","zh":"我请求你的原谅。","t":[3388,5175]},{"en":"Try to be happy...\"","zh":"尽量快乐吧...","t":[5175,6337]}]},{"id":"ch09p08","audio":true,"sents":[{"en":"He was surprised by this absence of reproaches.","zh":"他对这种没有责备感到惊讶。","t":[138,3375]},{"en":"He stood there all bewildered, the glass globe held arrested in mid-air.","zh":"他站在那里，完全困惑，手中的玻璃球悬停在半空中。","t":[3375,7788]},{"en":"He did not understand this quiet sweetness.","zh":"他不懂这种平静的甜蜜。","t":[7788,10424]}]},{"id":"ch09p09","audio":true,"sents":[{"en":"\"Of course I love you,\" the flower said to him.","zh":"当然我爱你，”花朵对他说。","t":[112,3125]},{"en":"\"It is my fault that you have not known it all the while.","zh":"这是我的错，你一直都不知道。","t":[3125,6312]},{"en":"That is of no importance.","zh":"那不重要。","t":[6312,8350]},{"en":"But you-- you have been just as foolish as I.","zh":"但你——你和我一样愚蠢。","t":[8350,10525]},{"en":"Try to be happy...","zh":"尽量快乐吧...","t":[10525,11912]},{"en":"let the glass globe be.","zh":"让这个玻璃球待着吧。","t":[11912,13550]},{"en":"I don't want it any more.\"","zh":"我再也不想要它了。","t":[13550,14987]}]},{"id":"ch09p10","audio":true,"sents":[{"en":"\"But the wind--\"","zh":"但是风——","t":[100,975]}]},{"id":"ch09p11","audio":true,"sents":[{"en":"\"My cold is not so bad as all that...","zh":"我的感冒并没有那么严重……","t":[138,2512]},{"en":"the cool night air will do me good.","zh":"凉爽的夜风会对我有好处的。","t":[2512,4562]},{"en":"I am a flower.\"","zh":"我是一朵花。","t":[4562,5612]}]},{"id":"ch09p12","audio":true,"sents":[{"en":"\"But the animals--\"","zh":"但是动物们——","t":[112,1162]}]},{"id":"ch09p13","audio":true,"sents":[{"en":"\"Well, I must endure the presence of two or three caterpillars if I wish to become acquainted with the butterflies.","zh":"嗯，如果我想认识蝴蝶，就必须忍受两三个毛毛虫的存在。","t":[138,6625]},{"en":"It seems that they are very beautiful.","zh":"它们似乎非常美丽。","t":[6625,9112]},{"en":"And if not the butterflies-- and the caterpillars-- who will call upon me?","zh":"如果不是蝴蝶——还有毛毛虫——那还有谁会来拜访我？","t":[9112,13138]},{"en":"You will be far away...","zh":"你将会离得很远...","t":[13138,14662]},{"en":"as for the large animals-- I am not at all afraid of any of them.","zh":"至于大动物——我一点也不害怕它们中的任何一个。","t":[14662,18300]},{"en":"I have my claws.\"","zh":"我有我的爪子。","t":[18300,19487]}]},{"id":"ch09p14","audio":true,"sents":[{"en":"And, naïvely, she showed her four thorns.","zh":"然后，天真地，她展示了她的四根刺。","t":[138,3438]},{"en":"Then she added:","zh":"然后她又补充道：","t":[3438,4526]}]},{"id":"ch09p15","audio":true,"sents":[{"en":"\"Don't linger like this.","zh":"不要这样逗留。","t":[112,1850]},{"en":"You have decided to go away.","zh":"你已经决定离开。","t":[1850,4000]},{"en":"Now go!\"","zh":"现在走吧！","t":[4000,4662]}]},{"id":"ch09p16","audio":true,"sents":[{"en":"For she did not want him to see her crying.","zh":"因为她不想让他看到她在哭。","t":[125,2738]},{"en":"She was such a proud flower...","zh":"她是一个如此骄傲的花朵...","t":[2738,4575]}]}]},{"id":"ch10","title_en":"Chapter X","title_zh":"第 10 章","paras":[{"id":"ch10p00","audio":true,"sents":[{"en":"He found himself in the neighbourhood of the asteroids 325, 326, 327, 328, 329, and 330.","zh":"他发现自己身处325号、326号、327号、328号、329号和330号小行星附近。","t":[125,11112]},{"en":"He began, therefore, by visiting them, in order to add to his knowledge.","zh":"因此，他开始逐一拜访它们，以便增加自己的知识。","t":[11112,17138]}]},{"id":"ch10p01","audio":true,"sents":[{"en":"The first of them was inhabited by a king.","zh":"其中第一个被一位国王居住。","t":[138,3012]},{"en":"Clad in royal purple and ermine, he was seated upon a throne which was at the same time both simple and majestic.","zh":"他身着皇家紫袍和貂皮，坐在一个既简单又庄严的王座上。","t":[3012,9475]}]},{"id":"ch10p02","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,850]},{"en":"Here is a subject,\" exclaimed the king, when he saw the little prince coming.","zh":"这里有一个臣民，”当国王看到小王子走来时，他大声说道。","t":[850,5163]}]},{"id":"ch10p03","audio":true,"sents":[{"en":"And the little prince asked himself:","zh":"小王子自言自语道：","t":[138,2262]}]},{"id":"ch10p04","audio":true,"sents":[{"en":"\"How could he recognize me when he had never seen me before?\"","zh":"他从未见过我，他怎么能认出我呢？","t":[125,3338]}]},{"id":"ch10p05","audio":true,"sents":[{"en":"He did not know how the world is simplified for kings.","zh":"他不知道世界在国王眼中是如何简化的。","t":[125,3488]},{"en":"To them, all men are subjects.","zh":"对他们来说，所有人都是臣民。","t":[3488,5600]}]},{"id":"ch10p06","audio":true,"sents":[{"en":"\"Approach, so that I may see you better,\" said the king, who felt consumingly proud of being at last a king over somebody.","zh":"靠近一点，这样我才能更好地看到你，”国王说着，他因为终于统治着某个人而感到极度自豪。","t":[138,6963]}]},{"id":"ch10p07","audio":true,"sents":[{"en":"The little prince looked everywhere to find a place to sit down; but the entire planet was crammed and obstructed by the king's magnificent ermine robe.","zh":"小王子四处寻找一个可以坐下地方；但整个星球都被国王那华丽的貂皮长袍塞满和挡住了。","t":[138,8612]},{"en":"So he remained standing upright, and, since he was tired, he yawned.","zh":"所以他一直站着，因为他累了，他打了个哈欠。","t":[8612,13225]}]},{"id":"ch10p08","audio":true,"sents":[{"en":"\"It is contrary to etiquette to yawn in the presence of a king,\" the monarch said to him.","zh":"在国王面前打哈欠是违反礼仪的，”君主对他说。","t":[138,5162]},{"en":"\"I forbid you to do so.\"","zh":"我禁止你这样做。","t":[5162,6688]}]},{"id":"ch10p09","audio":true,"sents":[{"en":"\"I can't help it.","zh":"我无法控制自己。","t":[138,1662]},{"en":"I can't stop myself,\" replied the little prince, thoroughly embarrassed.","zh":"我无法阻止自己，”小王子回答说，他感到非常尴尬。","t":[1662,6312]},{"en":"\"I have come on a long journey, and I have had no sleep...\"","zh":"我长途跋涉而来，我一点都没睡...","t":[6312,9526]}]},{"id":"ch10p10","audio":true,"sents":[{"en":"\"Ah, then,\" the king said.","zh":"啊，那么，","t":[138,2475]},{"en":"\"I order you to yawn.","zh":"我命令你打哈欠。","t":[2475,4175]},{"en":"It is years since I have seen anyone yawning.","zh":"我已经好多年没见过有人打哈欠了。","t":[4175,7175]},{"en":"Yawns, to me, are objects of curiosity.","zh":"打哈欠对我来说是好奇的对象。","t":[7175,10700]},{"en":"Come, now!","zh":"来吧，现在！","t":[10700,11900]},{"en":"Yawn again!","zh":"又打了个哈欠！","t":[11900,12962]},{"en":"It is an order.\"","zh":"这是一条命令。","t":[12962,13962]}]},{"id":"ch10p11","audio":true,"sents":[{"en":"\"That frightens me...","zh":"那让我害怕...","t":[112,1725]},{"en":"I cannot, any more...\" murmured the little prince, now completely abashed.","zh":"我无法……\"小王子现在完全羞愧地低声说道。","t":[1725,6837]}]},{"id":"ch10p12","audio":true,"sents":[{"en":"\"Hum!","zh":"哼！","t":[125,888]},{"en":"Hum!\" replied the king.","zh":"哼！国王回答道。","t":[888,2775]},{"en":"\"Then I-- I order you sometimes to yawn and sometimes to--\"","zh":"然后我——我有时命令你打哈欠，有时又命令你——","t":[2775,6100]}]},{"id":"ch10p13","audio":true,"sents":[{"en":"He sputtered a little, and seemed vexed.","zh":"他咕哝了几句，似乎有些恼火。","t":[138,2587]}]},{"id":"ch10p14","audio":true,"sents":[{"en":"For what the king fundamentally insisted upon was that his authority should be respected.","zh":"国王本质上坚持的是他的权威应该受到尊重。","t":[125,5650]},{"en":"He tolerated no disobedience.","zh":"他不容忍任何违抗。","t":[5650,8350]},{"en":"He was an absolute monarch.","zh":"他是一个绝对君主。","t":[8350,10425]},{"en":"But, because he was a very good man, he made his orders reasonable.","zh":"但他是个非常好的人，所以他的命令是合理的。","t":[10425,14475]}]},{"id":"ch10p15","audio":true,"sents":[{"en":"\"If I ordered a general,\" he would say, by way of example, \"if I ordered a general to change himself into a sea bird, and if the general did not obey me, that would not be the fault of the general.","zh":"如果我命令一个将军，他会举例说：“如果我命令一个将军变成一只海鸟，而将军不服从我，那不是将军的错。”","t":[138,10762]},{"en":"It would be my fault.\"","zh":"是我的错。","t":[10762,12074]}]},{"id":"ch10p16","audio":true,"sents":[{"en":"\"May I sit down?\" came now a timid inquiry from the little prince.","zh":"“我可以坐下吗？”小王子胆怯地问道。","t":[125,4187]}]},{"id":"ch10p17","audio":true,"sents":[{"en":"\"I order you to do so,\" the king answered him, and majestically gathered in a fold of his ermine mantle.","zh":"“我命令你这么做，”国王回答道，然后庄严地卷起他的貂皮斗篷。","t":[138,5950]}]},{"id":"ch10p18","audio":true,"sents":[{"en":"But the little prince was wondering...","zh":"但小王子在沉思……","t":[100,2438]},{"en":"The planet was tiny.","zh":"那颗星球很小。","t":[2438,4175]},{"en":"Over what could this king really rule?","zh":"这位国王究竟统治着什么？","t":[4175,6188]}]},{"id":"ch10p19","audio":true,"sents":[{"en":"\"Sire,\" he said to him, \"I beg that you will excuse my asking you a question--\"","zh":"陛下，他对他说，“请您原谅我向您提一个问题——”","t":[125,4612]}]},{"id":"ch10p20","audio":true,"sents":[{"en":"\"I order you to ask me a question,\" the king hastened to assure him.","zh":"“我命令你问我一个问题，”国王急忙向他保证。","t":[138,3900]}]},{"id":"ch10p21","audio":true,"sents":[{"en":"\"Sire-- over what do you rule?\"","zh":"陛下，您统治着什么？","t":[125,1975]}]},{"id":"ch10p22","audio":true,"sents":[{"en":"\"Over everything,\" said the king, with magnificent simplicity.","zh":"“对于一切，”国王以宏伟的简单性说道。","t":[112,4012]}]},{"id":"ch10p23","audio":true,"sents":[{"en":"\"Over everything?\"","zh":"覆盖一切？","t":[125,1176]}]},{"id":"ch10p24","audio":true,"sents":[{"en":"The king made a gesture, which took in his planet, the other planets, and all the stars.","zh":"国王做了一个手势，包括了整个他的星球、其他星球以及所有的星星。","t":[138,5212]}]},{"id":"ch10p25","audio":true,"sents":[{"en":"\"Over all that?\" asked the little prince.","zh":"“所有这些？”小王子问道。","t":[125,2674]}]},{"id":"ch10p26","audio":true,"sents":[{"en":"\"Over all that,\" the king answered.","zh":"关于这一切，”国王回答道。","t":[112,2200]}]},{"id":"ch10p27","audio":true,"sents":[{"en":"For his rule was not only absolute: it was also universal.","zh":"他的统治不仅绝对，而且普遍。","t":[125,4112]}]},{"id":"ch10p28","audio":true,"sents":[{"en":"\"And the stars obey you?\"","zh":"星星们会服从你吗？","t":[112,1588]}]},{"id":"ch10p29","audio":true,"sents":[{"en":"\"Certainly they do,\" the king said.","zh":"当然会，”国王说。","t":[125,2688]},{"en":"\"They obey instantly.","zh":"它们会立刻服从。","t":[2688,4512]},{"en":"I do not permit insubordination.\"","zh":"我不允许不服从。","t":[4512,6650]}]},{"id":"ch10p30","audio":true,"sents":[{"en":"Such power was a thing for the little prince to marvel at.","zh":"这样的权力是让小王子感到惊奇的事情。","t":[125,3862]},{"en":"If he had been master of such complete authority, he would have been able to watch the sunset, not forty-four times in one day, but seventy-two, or even a hundred, or even two hundred times, without ever having to move his chair.","zh":"如果他拥有这样完全的权威，他就能看到日落，不是一天中四十次，而是七十二次，甚至一百次，甚至两百次，而不用移动他的椅子。","t":[3862,16975]},{"en":"And because he felt a bit sad as he remembered his little planet, which he had forsaken, he plucked up his courage to ask the king a favour:","zh":"因为他想起了他遗弃的小星球，这让他感到有点悲伤，所以他鼓起勇气向国王提出一个请求：","t":[16975,24288]}]},{"id":"ch10p31","audio":true,"sents":[{"en":"\"I should like to see a sunset...","zh":"我想看看日落...","t":[138,2100]},{"en":"do me that kindness...","zh":"做这个好事...","t":[2100,3750]},{"en":"Order the sun to set...\"","zh":"命令太阳落山……","t":[3750,5163]}]},{"id":"ch10p32","audio":true,"sents":[{"en":"\"If I ordered a general to fly from one flower to another like a butterfly, or to write a tragic drama, or to change himself into a sea bird, and if the general did not carry out the order that he had received, which one of us would be in the wrong?\" the king demanded.","zh":"“如果我要一位将军像蝴蝶一样从一朵花飞到另一朵花，或者写一部悲剧剧作，或者变成一只海鸟，而这位将军没有执行他收到的命令，那么我们俩中谁才是错的？”国王质问道。","t":[138,14238]},{"en":"\"The general, or myself?\"","zh":"将军还是我自己？","t":[14238,15937]}]},{"id":"ch10p33","audio":true,"sents":[{"en":"\"You,\" said the little prince firmly.","zh":"“你，”小王子坚定地说。","t":[138,2350]}]},{"id":"ch10p34","audio":true,"sents":[{"en":"\"Exactly.","zh":"“一点没错。”","t":[100,1350]},{"en":"One much require from each one the duty which each one can perform,\" the king went on.","zh":"“每个人都要尽其所能履行自己的职责，”国王继续说道。","t":[1350,6612]},{"en":"\"Accepted authority rests first of all on reason.","zh":"权威的接受首先建立在理性之上。","t":[6612,10125]},{"en":"If you ordered your people to go and throw themselves into the sea, they would rise up in revolution.","zh":"如果你命令你的子民跳海自尽，他们就会起义反抗。","t":[10125,15688]},{"en":"I have the right to require obedience because my orders are reasonable.\"","zh":"我有权要求服从，因为我的命令是合理的。","t":[15688,19650]}]},{"id":"ch10p35","audio":true,"sents":[{"en":"\"Then my sunset?\" the little prince reminded him: for he never forgot a question once he had asked it.","zh":"“那么，我的黄昏？”小王子提醒他，因为他一旦问过一个问题就永远不会忘记。","t":[138,5900]}]},{"id":"ch10p36","audio":true,"sents":[{"en":"\"You shall have your sunset.","zh":"你们将拥有你们的日落。","t":[138,2100]},{"en":"I shall command it.","zh":"我将统治它。","t":[2100,3762]},{"en":"But, according to my science of government, I shall wait until conditions are favourable.\"","zh":"但是，根据我的治国之学，我会等到条件有利时再行动。","t":[3762,8813]}]},{"id":"ch10p37","audio":true,"sents":[{"en":"\"When will that be?\" inquired the little prince.","zh":"小王子问道：“那会是什么时候？”","t":[138,3000]}]},{"id":"ch10p38","audio":true,"sents":[{"en":"\"Hum!","zh":"哼！","t":[125,875]},{"en":"Hum!\" replied the king; and before saying anything else he consulted a bulky almanac.","zh":"“哼！”国王回答道；在说任何其他话之前，他查阅了一本厚重的年鉴。","t":[875,6412]},{"en":"\"Hum!","zh":"哼！","t":[6412,7150]},{"en":"Hum!","zh":"哼！","t":[7150,7900]},{"en":"That will be about-- about-- that will be this evening about twenty minutes to eight.","zh":"大约——大约——今晚八点差二十分左右。","t":[7900,12475]},{"en":"And you will see how well I am obeyed.\"","zh":"你会看到我是多么被听从。","t":[12475,14588]}]},{"id":"ch10p39","audio":true,"sents":[{"en":"The little prince yawned.","zh":"小王子打了个哈欠。","t":[138,1950]},{"en":"He was regretting his lost sunset.","zh":"他后悔错过了那场日落。","t":[1950,4575]},{"en":"And then, too, he was already beginning to be a little bored.","zh":"而且，他已经开始有点无聊了。","t":[4575,8137]}]},{"id":"ch10p40","audio":true,"sents":[{"en":"\"I have nothing more to do here,\" he said to the king.","zh":"他对国王说：“我在这里已经没有别的事情可做了。”","t":[138,3262]},{"en":"\"So I shall set out on my way again.\"","zh":"“所以我将再次踏上旅程。”","t":[3262,5487]}]},{"id":"ch10p41","audio":true,"sents":[{"en":"\"Do not go,\" said the king, who was very proud of having a subject.","zh":"“别走，”国王说，他为自己的子民感到非常自豪。","t":[100,4512]},{"en":"\"Do not go.","zh":"“别走。","t":[4512,5800]},{"en":"I will make you a Minister!\"","zh":"我会让你当我的部长！”","t":[5800,7300]}]},{"id":"ch10p42","audio":true,"sents":[{"en":"\"Minister of what?\"","zh":"“部长什么？”","t":[125,1388]}]},{"id":"ch10p43","audio":true,"sents":[{"en":"\"Minster of-- of Justice!\"","zh":"“司法部长！”","t":[112,1674]}]},{"id":"ch10p44","audio":true,"sents":[{"en":"\"But there is nobody here to judge!\"","zh":"但是这里没有人来评判！","t":[100,1987]}]},{"id":"ch10p45","audio":true,"sents":[{"en":"\"We do not know that,\" the king said to him.","zh":"我们不知道这一点，”国王对他说。","t":[138,3012]},{"en":"\"I have not yet made a complete tour of my kingdom.","zh":"我还没有完成对我的王国的全面巡视。","t":[3012,6188]},{"en":"I am very old.","zh":"我非常老。","t":[6188,7750]},{"en":"There is no room here for a carriage.","zh":"这里没有地方停放马车。","t":[7750,10112]},{"en":"And it tires me to walk.\"","zh":"而且走路让我感到疲惫。","t":[10112,11637]}]},{"id":"ch10p46","audio":true,"sents":[{"en":"\"Oh, but I have looked already!\" said the little prince, turning around to give one more glance to the other side of the planet.","zh":"哦，但是我已经看过了！”小王子说着，转身又朝星球的另一边看了一眼。","t":[112,7125]},{"en":"On that side, as on this, there was nobody at all...","zh":"在那一边，就像这一边一样，根本没有人...","t":[7125,10487]}]},{"id":"ch10p47","audio":true,"sents":[{"en":"\"Then you shall judge yourself,\" the king answered.","zh":"那么你就自己评判吧，”国王回答。","t":[112,3212]},{"en":"\"that is the most difficult thing of all.","zh":"这是最困难的事情。","t":[3212,5738]},{"en":"It is much more difficult to judge oneself than to judge others.","zh":"判断自己比判断他人要难得多。","t":[5738,9612]},{"en":"If you succeed in judging yourself rightly, then you are indeed a man of true wisdom.\"","zh":"如果你能正确地评价自己，那么你确实是一个真正有智慧的人。","t":[9612,14350]}]},{"id":"ch10p48","audio":true,"sents":[{"en":"\"Yes,\" said the little prince, \"but I can judge myself anywhere.","zh":"“是的，”小王子说，“但我在任何地方都能评判自己。”","t":[138,4312]},{"en":"I do not need to live on this planet.","zh":"我不需要生活在这个星球上。","t":[4312,6387]}]},{"id":"ch10p49","audio":true,"sents":[{"en":"\"Hum!","zh":"哼！","t":[125,888]},{"en":"Hum!\" said the king.","zh":"哼！国王说。","t":[888,2575]},{"en":"\"I have good reason to believe that somewhere on my planet there is an old rat.","zh":"我有充分的理由相信在我的星球上某个地方有一只老老鼠。","t":[2575,7050]},{"en":"I hear him at night.","zh":"我夜里能听到他。","t":[7050,8738]},{"en":"You can judge this old rat.","zh":"你可以评判这只老耗子。","t":[8738,10812]},{"en":"From time to time you will condemn him to death.","zh":"你时不时地会将他判处死刑。","t":[10812,13838]},{"en":"Thus his life will depend on your justice.","zh":"因此，他的生命将取决于你的公正。","t":[13838,16700]},{"en":"But you will pardon him on each occasion; for he must be treated thriftily.","zh":"但你会每次都原谅他；因为他必须被节俭地对待。","t":[16700,21162]},{"en":"He is the only one we have.\"","zh":"他是我们唯一拥有的。","t":[21162,22887]}]},{"id":"ch10p50","audio":true,"sents":[{"en":"\"I,\" replied the little prince, \"do not like to condemn anyone to death.","zh":"'我，'小王子回答道，'不喜欢判处任何人死刑。","t":[138,4888]},{"en":"And now I think I will go on my way.\"","zh":"现在我想我该继续我的旅程了。","t":[4888,7000]}]},{"id":"ch10p51","audio":true,"sents":[{"en":"\"No,\" said the king.","zh":"'不，'国王说。","t":[125,1562]}]},{"id":"ch10p52","audio":true,"sents":[{"en":"But the little prince, having now completed his preparations for departure, had no wish to grieve the old monarch.","zh":"但小王子已经完成了出发的准备，不想让这位年迈的君主伤心。","t":[100,6387]}]},{"id":"ch10p53","audio":true,"sents":[{"en":"\"If Your Majesty wishes to be promptly obeyed,\" he said, \"he should be able to give me a reasonable order.","zh":"'如果陛下希望被立即服从，'他说，'他应该能够给我一个合理的命令。","t":[138,6275]},{"en":"He should be able, for example, to order me to be gone by the end of one minute.","zh":"例如，他应该能够命令我在一分钟内离开。","t":[6275,11450]},{"en":"It seems to me that conditions are favourable...\"","zh":"在我看来，条件是有利的...","t":[11450,14100]}]},{"id":"ch10p54","audio":true,"sents":[{"en":"As the king made no answer, the little prince hesitated a moment.","zh":"国王没有回答，小王子犹豫了一下。","t":[138,4488]},{"en":"Then, with a sigh, he took his leave.","zh":"然后，他叹了口气，告辞了。","t":[4488,6950]}]},{"id":"ch10p55","audio":true,"sents":[{"en":"\"I made you my Ambassador,\" the king called out, hastily.","zh":"“我任命你为我的大使，”国王急忙喊道。","t":[138,3625]}]},{"id":"ch10p56","audio":true,"sents":[{"en":"He had a magnificent air of authority.","zh":"他有着威严的气派。","t":[125,2500]}]},{"id":"ch10p57","audio":true,"sents":[{"en":"\"The grown-ups are very strange,\" the little prince said to himself, as he continued on his journey.","zh":"小王子一边继续他的旅程，一边自言自语道：“大人真是奇怪。”","t":[138,5487]}]}]},{"id":"ch11","title_en":"Chapter XI","title_zh":"第 11 章","paras":[{"id":"ch11p00","audio":true,"sents":[{"en":"The second planet was inhabited by a conceited man.","zh":"第二个星球住着一个自负的人。","t":[138,3476]}]},{"id":"ch11p01","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,825]},{"en":"Ah!","zh":"啊！","t":[825,1538]},{"en":"I am about to receive a visit from an admirer!\" he exclaimed from afar, when he first saw the little prince coming.","zh":"我即将接待一位仰慕者来访！”他远远地喊道，当他第一次看到小王子走来。","t":[1538,7800]}]},{"id":"ch11p02","audio":true,"sents":[{"en":"For, to conceited men, all other men are admirers.","zh":"因为，对于自负的人来说，所有其他人都是仰慕者。","t":[125,3650]}]},{"id":"ch11p03","audio":true,"sents":[{"en":"\"Good morning,\" said the little prince.","zh":"早上好，”小王子说。","t":[112,2712]},{"en":"\"That is a queer hat you are wearing.\"","zh":"你戴的帽子真奇怪。","t":[2712,4600]}]},{"id":"ch11p04","audio":true,"sents":[{"en":"\"It is a hat for salutes,\" the conceited man replied.","zh":"这是一顶敬礼帽。","t":[138,3750]},{"en":"\"It is to raise in salute when people acclaim me.","zh":"当人们向我欢呼时，我就举起它敬礼。","t":[3750,6762]},{"en":"Unfortunately, nobody at all ever passes this way.\"","zh":"不幸的是，根本没有人经过这里。","t":[6762,10087]}]},{"id":"ch11p05","audio":true,"sents":[{"en":"\"Yes?\" said the little prince, who did not understand what the conceited man was talking about.","zh":"是吗？”小王子说，他不懂自负的人说的是什么。","t":[138,5600]}]},{"id":"ch11p06","audio":true,"sents":[{"en":"\"Clap your hands, one against the other,\" the conceited man now directed him.","zh":"拍拍你的手，一只手打另一只手，”自负的人现在指示他。","t":[112,4737]}]},{"id":"ch11p07","audio":true,"sents":[{"en":"The little prince clapped his hands.","zh":"小王子拍起了手。","t":[138,2525]},{"en":"The conceited man raised his hat in a modest salute.","zh":"自负的人举起帽子，做了一个谦虚的敬礼。","t":[2525,5800]}]},{"id":"ch11p08","audio":true,"sents":[{"en":"\"This is more entertaining than the visit to the king,\" the little prince said to himself.","zh":"这比拜访国王更有趣，”小王子自言自语道。","t":[138,5100]},{"en":"And he began again to clap his hands, one against the other.","zh":"他又开始拍起手来，一只手拍在另一只手上。","t":[5100,8900]},{"en":"The conceited man against raised his hat in salute.","zh":"那个自负的人举起帽子致敬。","t":[8900,12025]}]},{"id":"ch11p09","audio":true,"sents":[{"en":"After five minutes of this exercise the little prince grew tired of the game's monotony.","zh":"经过五分钟的这种练习，小王子对游戏的单调感到厌倦。","t":[138,4812]}]},{"id":"ch11p10","audio":true,"sents":[{"en":"\"And what should one do to make the hat come down?\" he asked.","zh":"“那么，怎样才能让帽子掉下来呢？”他问道。","t":[125,3512]}]},{"id":"ch11p11","audio":true,"sents":[{"en":"But the conceited man did not hear him.","zh":"但是自负的人没有听到他。","t":[100,2738]},{"en":"Conceited people never hear anything but praise.","zh":"自负的人从来不听别人的话，只听赞美。","t":[2738,5763]}]},{"id":"ch11p12","audio":true,"sents":[{"en":"\"Do you really admire me very much?\" he demanded of the little prince.","zh":"“你真的非常崇拜我吗？”他向小王子要求。","t":[100,4163]}]},{"id":"ch11p13","audio":true,"sents":[{"en":"\"What does that mean-- 'admire'?\"","zh":"“‘崇拜’是什么意思？","t":[112,1675]}]},{"id":"ch11p14","audio":true,"sents":[{"en":"\"To admire mean that you regard me as the handsomest, the best-dressed, the richest, and the most intelligent man on this planet.\"","zh":"‘崇拜’的意思是，你认为我是这个星球上最英俊、最会穿衣打扮、最富有、最聪明的人。","t":[100,7512]}]},{"id":"ch11p15","audio":true,"sents":[{"en":"\"But you are the only man on your planet!\"","zh":"“但你可是你星球上唯一的人啊！”","t":[100,2325]}]},{"id":"ch11p16","audio":true,"sents":[{"en":"\"Do me this kindness.","zh":"请帮帮我这个忙。","t":[112,1862]},{"en":"Admire me just the same.\"","zh":"就像以前一样崇拜我。","t":[1862,3450]}]},{"id":"ch11p17","audio":true,"sents":[{"en":"\"I admire you,\" said the little prince, shrugging his shoulders slightly, \"but what is there in that to interest you so much?\"","zh":"‘我崇拜你，’小王子一边耸了耸肩，一边说，‘但那有什么能让你如此感兴趣呢？’","t":[138,6838]}]},{"id":"ch11p18","audio":true,"sents":[{"en":"And the little prince went away.","zh":"然后小王子就走了。","t":[138,1888]}]},{"id":"ch11p19","audio":true,"sents":[{"en":"\"The grown-ups are certainly very odd,\" he said to himself, as he continued on his journey.","zh":"‘大人真是奇怪，’他一边继续他的旅程，一边自言自语。","t":[138,5150]}]}]},{"id":"ch12","title_en":"Chapter XII","title_zh":"第 12 章","paras":[{"id":"ch12p00","audio":true,"sents":[{"en":"The next planet was inhabited by a tippler.","zh":"下一个星球住着一个酒鬼。","t":[112,3275]},{"en":"This was a very short visit, but it plunged the little prince into deep dejection.","zh":"这是一次很短的访问，但它让小王子陷入了深深的沮丧。","t":[3275,8100]}]},{"id":"ch12p01","audio":true,"sents":[{"en":"\"What are you doing there?\" he said to the tippler, whom he found settled down in silence before a collection of empty bottles and also a collection of full bottles.","zh":"‘你在那里做什么？’他对酒鬼说，他发现酒鬼正安静地坐在一堆空瓶子和一些满瓶子的前面。","t":[138,8525]}]},{"id":"ch12p02","audio":true,"sents":[{"en":"\"I am drinking,\" replied the tippler, with a lugubrious air.","zh":"‘我在喝酒，’酒鬼带着一种忧郁的语气回答。","t":[138,3787]}]},{"id":"ch12p03","audio":true,"sents":[{"en":"\"Why are you drinking?\" demanded the little prince.","zh":"‘你为什么喝酒？’小王子质问道。","t":[138,3000]}]},{"id":"ch12p04","audio":true,"sents":[{"en":"\"So that I may forget,\" replied the tippler.","zh":"所以我才能忘记，”酒鬼回答说。","t":[125,2800]}]},{"id":"ch12p05","audio":true,"sents":[{"en":"\"Forget what?\" inquired the little prince, who already was sorry for him.","zh":"忘记什么？”小王子问道，他已经为他感到难过。","t":[125,4450]}]},{"id":"ch12p06","audio":true,"sents":[{"en":"\"Forget that I am ashamed,\" the tippler confessed, hanging his head.","zh":"忘记我感到羞耻，”酒鬼承认道，低下了头。","t":[125,4163]}]},{"id":"ch12p07","audio":true,"sents":[{"en":"\"Ashamed of what?\" insisted the little prince, who wanted to help him.","zh":"羞耻什么？”小王子坚持问，他想要帮助他。","t":[125,4313]}]},{"id":"ch12p08","audio":true,"sents":[{"en":"\"Ashamed of drinking!\" The tippler brought his speech to an end, and shut himself up in an impregnable silence.","zh":"羞耻喝酒！”酒鬼结束了他的话，把自己关在了坚不可摧的沉默中。","t":[125,6676]}]},{"id":"ch12p09","audio":true,"sents":[{"en":"And the little prince went away, puzzled.","zh":"小王子困惑地离开了。","t":[138,2650]}]},{"id":"ch12p10","audio":true,"sents":[{"en":"\"The grown-ups are certainly very, very odd,\" he said to himself, as he continued on his journey.","zh":"大人们确实非常、非常奇怪，”他一边继续他的旅程，一边自言自语。","t":[138,5750]}]}]},{"id":"ch13","title_en":"Chapter XIII","title_zh":"第 13 章","paras":[{"id":"ch13p00","audio":true,"sents":[{"en":"The fourth planet belonged to a businessman.","zh":"第四颗星球属于一个商人。","t":[138,2975]},{"en":"This man was so much occupied that he did not even raise his head at the little prince's arrival.","zh":"这个人如此忙碌，以至于在小王子到来时甚至没有抬头。","t":[2975,8162]}]},{"id":"ch13p01","audio":true,"sents":[{"en":"\"Good morning,\" the little prince said to him.","zh":"早上好，”小王子对他说。","t":[100,2925]},{"en":"\"Your cigarette has gone out.\"","zh":"你的香烟熄灭了。","t":[2925,4550]}]},{"id":"ch13p02","audio":true,"sents":[{"en":"\"Three and two make five.","zh":"三加二等于五。","t":[112,2125]},{"en":"Five and seven make twelve.","zh":"五加七等于十二。","t":[2125,4262]},{"en":"Twelve and three make fifteen.","zh":"十二加三等于十五。","t":[4262,6488]},{"en":"Good morning.","zh":"早上好。","t":[6488,7675]},{"en":"Fifteen and seven make twenty-two.","zh":"十五加七等于二十二。","t":[7675,10425]},{"en":"Twenty-two and six make twenty-eight.","zh":"二十二加六等于二十八。","t":[10425,13350]},{"en":"I haven't time to light it again.","zh":"我没有时间再点一次了。","t":[13350,15612]},{"en":"Twenty-six and five make thirty-one.","zh":"二十六加五等于三十一。","t":[15612,18475]},{"en":"Phew!","zh":"呼！","t":[18475,19262]},{"en":"Then that makes five-hundred-and-one-million, six-hundred-twenty-two-thousand, seven-hundred-thirty-one.\"","zh":"那么就是一亿零一百六十万二千七百三十一。","t":[19262,25075]}]},{"id":"ch13p03","audio":true,"sents":[{"en":"\"Five hundred million what?\" asked the little prince.","zh":"“五亿什么？”小王子问道。","t":[125,3412]}]},{"id":"ch13p04","audio":true,"sents":[{"en":"\"Eh?","zh":"咦？","t":[138,888]},{"en":"Are you still there?","zh":"你还在吗？","t":[888,2288]},{"en":"Five-hundred-and-one million-- I can't stop...","zh":"五亿零一——我无法停下...","t":[2288,5238]},{"en":"I have so much to do!","zh":"我有很多事情要做！","t":[5238,7000]},{"en":"I am concerned with matters of consequence.","zh":"我关心的是重要的事情。","t":[7000,10062]},{"en":"I don't amuse myself with balderdash.","zh":"我不以胡言乱语自娱。","t":[10062,12750]},{"en":"Two and five make seven...\"","zh":"二加五等于七……","t":[12750,14488]}]},{"id":"ch13p05","audio":true,"sents":[{"en":"\"Five-hundred-and-one million what?\" repeated the little prince, who never in his life had let go of a question once he had asked it.","zh":"“五亿零一百万什么？”小王子重复道，他一旦提问就绝不会放弃。","t":[125,7162]}]},{"id":"ch13p06","audio":true,"sents":[{"en":"The businessman raised his head.","zh":"商人抬起了头。","t":[138,1950]}]},{"id":"ch13p07","audio":true,"sents":[{"en":"\"During the fifty-four years that I have inhabited this planet, I have been disturbed only three times.","zh":"在这颗星球上居住的五十四年里，我只被打扰过三次。","t":[138,6162]},{"en":"The first time was twenty-two years ago, when some giddy goose fell from goodness knows where.","zh":"第一次是在二十二年前，当时有一只疯狂的天鹅从天而降，谁也不知道它从哪里来。","t":[6162,11475]},{"en":"He made the most frightful noise that resounded all over the place, and I made four mistakes in my addition.","zh":"它发出了一阵可怕的噪音，整个地方都回荡着，我在加法上犯了四个错误。","t":[11475,17588]},{"en":"The second time, eleven years ago, I was disturbed by an attack of rheumatism.","zh":"第二次是在十一年前，我被风湿病袭击了。","t":[17588,22738]},{"en":"I don't get enough exercise.","zh":"我得不到足够的锻炼。","t":[22738,24850]},{"en":"I have no time for loafing.","zh":"我没有时间懒散。","t":[24850,26975]},{"en":"The third time-- well, this is it!","zh":"第三次——嗯，就是现在！","t":[26975,29388]},{"en":"I was saying, then, five-hundred-and-one millions--\"","zh":"我当时说的是，五千零一百万——","t":[29388,32675]}]},{"id":"ch13p08","audio":true,"sents":[{"en":"\"Millions of what?\"","zh":"成千上万的是什么？","t":[125,1375]}]},{"id":"ch13p09","audio":true,"sents":[{"en":"The businessman suddenly realized that there was no hope of being left in peace until he answered this question.","zh":"商人突然意识到，除非他回答了这个问题，否则永远无法安宁。","t":[138,5775]}]},{"id":"ch13p10","audio":true,"sents":[{"en":"\"Millions of those little objects,\" he said, \"which one sometimes sees in the sky.\"","zh":"数以百万计的这些小东西，\"他说，\"有时我们在天空中能看到。","t":[125,4988]}]},{"id":"ch13p11","audio":true,"sents":[{"en":"\"Flies?\"","zh":"苍蝇？","t":[100,788]}]},{"id":"ch13p12","audio":true,"sents":[{"en":"\"Oh, no.","zh":"哦，不。","t":[112,1488]},{"en":"Little glittering objects.\"","zh":"小小的闪亮物体。","t":[1488,3200]}]},{"id":"ch13p13","audio":true,"sents":[{"en":"\"Bees?\"","zh":"蜜蜂？","t":[100,675]}]},{"id":"ch13p14","audio":true,"sents":[{"en":"\"Oh, no.","zh":"哦，不。","t":[112,1488]},{"en":"Little golden objects that set lazy men to idle dreaming.","zh":"那些让懒人沉溺于悠闲梦想的金色小物件。","t":[1488,5538]},{"en":"As for me, I am concerned with matters of consequence.","zh":"至于我，我关心的是重要的事情。","t":[5538,9475]},{"en":"There is no time for idle dreaming in my life.\"","zh":"我的生活中没有时间空想。","t":[9475,12250]}]},{"id":"ch13p15","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,850]},{"en":"You mean the stars?\"","zh":"你是说星星？","t":[850,2050]}]},{"id":"ch13p16","audio":true,"sents":[{"en":"\"Yes, that's it.","zh":"是的，就是它们。","t":[112,1862]},{"en":"The stars.\"","zh":"星星。","t":[1862,2662]}]},{"id":"ch13p17","audio":true,"sents":[{"en":"\"And what do you do with five-hundred millions of stars?\"","zh":"那你用这五亿颗星星做什么？","t":[112,3100]}]},{"id":"ch13p18","audio":true,"sents":[{"en":"\"Five-hundred-and-one million, six-hundred-twenty-two thousand, seven-hundred-thirty-one.","zh":"五亿零一百六十二万七千三百三十一。","t":[125,5738]},{"en":"I am concerned with matters of consequence: I am accurate.\"","zh":"我关心的是重要的事情：我要求精确。","t":[5738,9400]}]},{"id":"ch13p19","audio":true,"sents":[{"en":"\"And what do you do with these stars?\"","zh":"那你用这些星星做什么？","t":[112,2000]}]},{"id":"ch13p20","audio":true,"sents":[{"en":"\"What do I do with them?\"","zh":"我用它们做什么？","t":[112,1412]}]},{"id":"ch13p21","audio":true,"sents":[{"en":"\"Yes.\"","zh":"是的。","t":[100,600]}]},{"id":"ch13p22","audio":true,"sents":[{"en":"\"Nothing.","zh":"什么也没有。","t":[112,1138]},{"en":"I own them.\"","zh":"我拥有它们。","t":[1138,1888]}]},{"id":"ch13p23","audio":true,"sents":[{"en":"\"You own the stars?\"","zh":"你拥有星星吗？","t":[138,1300]}]},{"id":"ch13p24","audio":true,"sents":[{"en":"\"Yes.\"","zh":"是的。","t":[100,600]}]},{"id":"ch13p25","audio":true,"sents":[{"en":"\"But I have already seen a king who--\"","zh":"但是我已经见过一个国王，他——","t":[100,2087]}]},{"id":"ch13p26","audio":true,"sents":[{"en":"\"Kings do not own, they reign over.","zh":"国王并不拥有，他们统治。","t":[100,2788]},{"en":"It is a very different matter.\"","zh":"这是一件完全不同的事情。","t":[2788,4487]}]},{"id":"ch13p27","audio":true,"sents":[{"en":"\"And what good does it do you to own the stars?\"","zh":"拥有星星对你有什么好处？","t":[112,2500]}]},{"id":"ch13p28","audio":true,"sents":[{"en":"\"It does me the good of making me rich.\"","zh":"它让我变得富有。","t":[138,2276]}]},{"id":"ch13p29","audio":true,"sents":[{"en":"\"And what good does it do you to be rich?\"","zh":"那么，富有对你有什么好处？","t":[138,2300]}]},{"id":"ch13p30","audio":true,"sents":[{"en":"\"It makes it possible for me to buy more stars, if any are ever discovered.\"","zh":"这使得我能够购买更多的星星，如果将来有星星被发现的话。","t":[138,4487]}]},{"id":"ch13p31","audio":true,"sents":[{"en":"\"This man,\" the little prince said to himself, \"reasons a little like my poor tippler...\"","zh":"这个人，”小王子自言自语道，“他的推理方式有点像我那可怜的酒鬼...","t":[125,4962]}]},{"id":"ch13p32","audio":true,"sents":[{"en":"Nevertheless, he still had some more questions.","zh":"然而，他还有一些问题。","t":[125,2988]}]},{"id":"ch13p33","audio":true,"sents":[{"en":"\"How is it possible for one to own the stars?\"","zh":"一个人怎么可能拥有星星呢？","t":[125,2674]}]},{"id":"ch13p34","audio":true,"sents":[{"en":"\"To whom do they belong?\" the businessman retorted, peevishly.","zh":"它们属于谁？”商人反问道，带着一丝烦躁。","t":[112,3937]}]},{"id":"ch13p35","audio":true,"sents":[{"en":"\"I don't know.","zh":"我不知道。","t":[125,1350]},{"en":"To nobody.\"","zh":"不属于任何人。","t":[1350,2176]}]},{"id":"ch13p36","audio":true,"sents":[{"en":"\"Then they belong to me, because I was the first person to think of it.\"","zh":"那么它们就属于我，因为我第一个想到了这一点。","t":[138,3876]}]},{"id":"ch13p37","audio":true,"sents":[{"en":"\"Is that all that is necessary?\"","zh":"这就足够了吗？","t":[112,1938]}]},{"id":"ch13p38","audio":true,"sents":[{"en":"\"Certainly.","zh":"当然。","t":[112,1275]},{"en":"When you find a diamond that belongs to nobody, it is yours.","zh":"当你找到一颗不属于任何人的钻石时，它就是你的。","t":[1275,5238]},{"en":"When you discover an island that belongs to nobody, it is yours.","zh":"当你发现一个不属于任何人的岛屿时，它就是你的。","t":[5238,9425]},{"en":"When you get an idea before any one else, you take out a patent on it: it is yours.","zh":"当你比任何人都先得到一个想法时，你就可以申请专利：它就是你的。","t":[9425,14925]},{"en":"So with me: I own the stars, because nobody else before me ever thought of owning them.\"","zh":"至于我：我拥有星星，因为在我之前没有人想过要拥有它们。","t":[14925,20062]}]},{"id":"ch13p39","audio":true,"sents":[{"en":"\"Yes, that is true,\" said the little prince.","zh":"是的，这是真的，”小王子说。","t":[138,3400]},{"en":"\"And what do you do with them?\"","zh":"那你对它们做什么呢？","t":[3400,4812]}]},{"id":"ch13p40","audio":true,"sents":[{"en":"\"I administer them,\" replied the businessman.","zh":"我管理它们，”商人回答。","t":[138,3112]},{"en":"\"I count them and recount them.","zh":"我数它们，再重新数一遍。","t":[3112,5225]},{"en":"It is difficult.","zh":"这很困难。","t":[5225,6688]},{"en":"But I am a man who is naturally interested in matters of consequence.\"","zh":"但我是一个天生对重要事情感兴趣的人。","t":[6688,10638]}]},{"id":"ch13p41","audio":true,"sents":[{"en":"The little prince was still not satisfied.","zh":"小王子仍然不满意。","t":[138,2600]}]},{"id":"ch13p42","audio":true,"sents":[{"en":"\"If I owned a silk scarf,\" he said, \"I could put it around my neck and take it away with me.","zh":"\"如果我有一条丝巾，\"他说，\"我可以把它围在脖子上，然后带走它。\"","t":[138,5475]},{"en":"If I owned a flower, I could pluck that flower and take it away with me.","zh":"如果我有一朵花，我可以摘下那朵花然后带走它。","t":[5475,9762]},{"en":"But you cannot pluck the stars from heaven...\"","zh":"但是你无法摘下天上的星星...","t":[9762,12138]}]},{"id":"ch13p43","audio":true,"sents":[{"en":"\"No.","zh":"\"不。\"","t":[100,962]},{"en":"But I can put them in the bank.\"","zh":"但是我可以把它们存入银行。\"","t":[962,2637]}]},{"id":"ch13p44","audio":true,"sents":[{"en":"\"Whatever does that mean?\"","zh":"\"那是什么意思？\"","t":[138,1512]}]},{"id":"ch13p45","audio":true,"sents":[{"en":"\"That means that I write the number of my stars on a little paper.","zh":"\"那就是我把我的星星的数量写在小纸片上。\"","t":[138,4075]},{"en":"And then I put this paper in a drawer and lock it with a key.\"","zh":"然后我把这张纸放进抽屉里，用一把钥匙锁上。","t":[4075,7363]}]},{"id":"ch13p46","audio":true,"sents":[{"en":"\"And that is all?\"","zh":"\"就这样吗？\"","t":[138,1050]}]},{"id":"ch13p47","audio":true,"sents":[{"en":"\"That is enough,\" said the businessman.","zh":"那已经足够了，”商人说。","t":[125,2350]}]},{"id":"ch13p48","audio":true,"sents":[{"en":"\"It is entertaining,\" thought the little prince.","zh":"这很有趣，”小王子想。","t":[138,3150]},{"en":"\"It is rather poetic.","zh":"这相当有诗意。","t":[3150,5025]},{"en":"But it is of no great consequence.\"","zh":"但并没有什么大不了的。","t":[5025,7200]}]},{"id":"ch13p49","audio":true,"sents":[{"en":"On matters of consequence, the little prince had ideas which were very different from those of the grown-ups.","zh":"在重要的事情上，小王子有着与成人截然不同的想法。","t":[138,5888]}]},{"id":"ch13p50","audio":true,"sents":[{"en":"\"I myself own a flower,\" he continued his conversation with the businessman, \"which I water every day.","zh":"我自己有一朵花，”他继续与商人交谈，“我每天都给它浇水。","t":[138,6388]},{"en":"I own three volcanoes, which I clean out every week (for I also clean out the one that is extinct; one never knows).","zh":"我有三座火山，我每周都要清理它们（因为我也清理那座已经熄灭的火山；你永远不知道）。","t":[6388,13612]},{"en":"It is of some use to my volcanoes, and it is of some use to my flower, that I own them.","zh":"拥有火山对我自己的火山和我的花都有一些用处。","t":[13612,18962]},{"en":"But you are of no use to the stars...\"","zh":"但你对于星星来说没有任何用处...","t":[18962,21175]}]},{"id":"ch13p51","audio":true,"sents":[{"en":"The businessman opened his mouth, but he found nothing to say in answer.","zh":"商人张了张嘴，但找不到什么话来回答。","t":[138,4588]},{"en":"And the little prince went away.","zh":"小王子离开了。","t":[4588,6388]}]},{"id":"ch13p52","audio":true,"sents":[{"en":"\"The grown-ups are certainly altogether extraordinary,\" he said simply, talking to himself as he continued on his journey.","zh":"“大人确实非常特别，”他简单地说，一边说着一边继续他的旅程。","t":[138,6900]}]}]},{"id":"ch14","title_en":"Chapter XIV","title_zh":"第 14 章","paras":[{"id":"ch14p00","audio":true,"sents":[{"en":"The fifth planet was very strange.","zh":"第五颗星球非常奇特。","t":[138,2638]},{"en":"It was the smallest of all.","zh":"它是所有星球中最小的一个。","t":[2638,4662]},{"en":"There was just enough room on it for a street lamp and a lamplighter.","zh":"上面刚好有足够的空间放置一盏路灯和一个提灯人。","t":[4662,8550]},{"en":"The little prince was not able to reach any explanation of the use of a street lamp and a lamplighter, somewhere in the heavens, on a planet, which had no people, and not one house.","zh":"小王子无法解释在某个无人的星球上，天空中为何会有路灯和点灯人的用途。","t":[8550,18750]},{"en":"But he said to himself, nevertheless:","zh":"然而，他自言自语道：","t":[18750,21213]}]},{"id":"ch14p01","audio":true,"sents":[{"en":"\"It may well be that this man is absurd.","zh":"这个人很可能是荒谬的。","t":[138,2900]},{"en":"But he is not so absurd as the king, the conceited man, the businessman, and the tippler.","zh":"但他并不像国王、自负的人、商人、酒鬼那样荒谬。","t":[2900,8600]},{"en":"For at least his work has some meaning.","zh":"至少他的工作还有点意义。","t":[8600,11150]},{"en":"When he lights his street lamp, it is as if he brought one more star to life, or one flower.","zh":"当他点亮街灯时，仿佛又唤醒了一颗星星，或者一朵花。","t":[11150,16662]},{"en":"When he puts out his lamp, he sends the flower, or the star, to sleep.","zh":"当他熄灭了他的灯，他就让花朵或星星入睡了。","t":[16662,21475]},{"en":"That is a beautiful occupation.","zh":"这是一份美好的职业。","t":[21475,23788]},{"en":"And since it is beautiful, it is truly useful.\"","zh":"既然它美丽，它就真正有用。","t":[23788,26726]}]},{"id":"ch14p02","audio":true,"sents":[{"en":"When he arrived on the planet he respectfully saluted the lamplighter.","zh":"他抵达星球后，恭敬地向点灯人致敬。","t":[138,4012]}]},{"id":"ch14p03","audio":true,"sents":[{"en":"\"Good morning.","zh":"早上好。","t":[112,1288]},{"en":"Why have you just put out your lamp?\"","zh":"你为什么刚刚吹灭了你的灯？","t":[1288,3162]}]},{"id":"ch14p04","audio":true,"sents":[{"en":"\"Those are the orders,\" replied the lamplighter.","zh":"“这是命令，”点灯人回答道。","t":[125,3150]},{"en":"\"Good morning.\"","zh":"早上好。","t":[3150,3962]}]},{"id":"ch14p05","audio":true,"sents":[{"en":"\"What are the orders?\"","zh":"“有什么命令？”","t":[125,1300]}]},{"id":"ch14p06","audio":true,"sents":[{"en":"\"The orders are that I put out my lamp.","zh":"命令是让我熄灭我的灯。","t":[138,2825]},{"en":"Good evening.\"","zh":"晚上好。","t":[2825,3650]}]},{"id":"ch14p07","audio":true,"sents":[{"en":"And he lighted his lamp again.","zh":"他又点亮了灯。","t":[138,1800]}]},{"id":"ch14p08","audio":true,"sents":[{"en":"\"But why have you just lighted it again?\"","zh":"“可你为什么又把灯点上了？”","t":[100,2200]}]},{"id":"ch14p09","audio":true,"sents":[{"en":"\"Those are the orders,\" replied the lamplighter.","zh":"“这是命令，”点灯人回答道。","t":[125,2787]}]},{"id":"ch14p10","audio":true,"sents":[{"en":"\"I do not understand,\" said the little prince.","zh":"我不懂，小王子说。","t":[138,2863]}]},{"id":"ch14p11","audio":true,"sents":[{"en":"\"There is nothing to understand,\" said the lamplighter.","zh":"“没有什么需要理解的，”点灯人说。","t":[125,3488]},{"en":"\"Orders are orders.","zh":"命令就是命令。","t":[3488,5100]},{"en":"Good morning.\"","zh":"早上好。","t":[5100,5912]}]},{"id":"ch14p12","audio":true,"sents":[{"en":"And he put out his lamp.","zh":"他熄灭了灯。","t":[138,1538]}]},{"id":"ch14p13","audio":true,"sents":[{"en":"Then he mopped his forehead with a handkerchief decorated with red squares.","zh":"然后他用一块印有红方格的手帕擦了擦额头。","t":[138,4288]}]},{"id":"ch14p14","audio":true,"sents":[{"en":"\"I follow a terrible profession.","zh":"我从事的是一份糟糕的职业。","t":[138,2538]},{"en":"In the old days it was reasonable.","zh":"在以前，这样做是合理的。","t":[2538,5000]},{"en":"I put the lamp out in the morning, and in the evening I lighted it again.","zh":"我早上熄灭灯光，晚上又重新点亮。","t":[5000,9325]},{"en":"I had the rest of the day for relaxation and the rest of the night for sleep.\"","zh":"我有一整天的时间可以放松，还有一整晚的时间可以睡觉。","t":[9325,13412]}]},{"id":"ch14p15","audio":true,"sents":[{"en":"\"And the orders have been changed since that time?\"","zh":"自从那时起，命令有没有改变？","t":[125,2725]}]},{"id":"ch14p16","audio":true,"sents":[{"en":"\"The orders have not been changed,\" said the lamplighter.","zh":"命令没有改变，”点灯人说。","t":[138,3562]},{"en":"\"That is the tragedy!","zh":"这是悲剧！","t":[3562,5188]},{"en":"From year to year the planet has turned more rapidly and the orders have not been changed!\"","zh":"一年又一年，星球转得越来越快，但命令却没有改变！","t":[5188,10000]}]},{"id":"ch14p17","audio":true,"sents":[{"en":"\"Then what?\" asked the little prince.","zh":"那么接下来呢？”小王子问道。","t":[138,2512]}]},{"id":"ch14p18","audio":true,"sents":[{"en":"\"Then-- the planet now makes a complete turn every minute, and I no longer have a single second for repose.","zh":"然后——这个星球现在每分钟转一圈，我再也没有一秒钟的闲暇了。","t":[138,6425]},{"en":"Once every minute I have to light my lamp and put it out!\"","zh":"每分钟我都要点亮我的灯，然后熄灭它！","t":[6425,9625]}]},{"id":"ch14p19","audio":true,"sents":[{"en":"\"That is very funny!","zh":"这非常有趣！","t":[125,1600]},{"en":"A day lasts only one minute, here where you live!\"","zh":"一天在这里只持续一分钟！","t":[1600,4526]}]},{"id":"ch14p20","audio":true,"sents":[{"en":"\"It is not funny at all!\" said the lamplighter.","zh":"“这根本不好笑！”点灯人说道。","t":[112,3088]},{"en":"\"While we have been talking together a month has gone by.\"","zh":"我们在一起谈话的这段时间，已经过去了一个月。","t":[3088,5987]}]},{"id":"ch14p21","audio":true,"sents":[{"en":"\"A month?\"","zh":"一个月？","t":[112,800]}]},{"id":"ch14p22","audio":true,"sents":[{"en":"\"Yes, a month.","zh":"是的，一个月。","t":[138,1762]},{"en":"Thirty minutes.","zh":"三十分钟。","t":[1762,3212]},{"en":"Thirty days.","zh":"三十天。","t":[3212,4600]},{"en":"Good evening.\"","zh":"晚上好。","t":[4600,5450]}]},{"id":"ch14p23","audio":true,"sents":[{"en":"And he lighted his lamp again.","zh":"他又点亮了他的灯笼。","t":[138,1800]}]},{"id":"ch14p24","audio":true,"sents":[{"en":"As the little prince watched him, he felt that he loved this lamplighter who was so faithful to his orders.","zh":"当小王子看着他时，他感到自己爱上了这个如此忠于自己命令的点灯人。","t":[138,6062]},{"en":"He remembered the sunsets, which he himself had gone to seek, in other days, merely by pulling up his chair; and he wanted to help his friend.","zh":"他想起了那些日子，他只是通过拉起椅子就能看到的日落；他想帮助他的朋友。","t":[6062,13938]}]},{"id":"ch14p25","audio":true,"sents":[{"en":"\"You know,\" he said, \"I can tell you a way you can rest whenever you want to...\"","zh":"“你知道，”他说，“我可以告诉你一个你可以随时休息的方法……","t":[112,4288]}]},{"id":"ch14p26","audio":true,"sents":[{"en":"\"I always want to rest,\" said the lamplighter.","zh":"“我总是想休息，”点灯人说。","t":[138,2813]}]},{"id":"ch14p27","audio":true,"sents":[{"en":"For it is possible for a man to be faithful and lazy at the same time.","zh":"因为一个人可以同时忠诚和懒惰。","t":[125,4588]},{"en":"The little prince went on with his explanation:","zh":"小王子继续他的解释：","t":[4588,7288]}]},{"id":"ch14p28","audio":true,"sents":[{"en":"\"Your planet is so small that three strides will take you all the way around it.","zh":"“你的星球如此之小，只需三步就能走完它的全程。","t":[138,4712]},{"en":"To be always in the sunshine, you need only walk along rather slowly.","zh":"要一直处于阳光下，你只需慢慢地走就可以了。","t":[4712,9075]},{"en":"When you want to rest, you will walk-- and the day will last as long as you like.\"","zh":"当你想休息时，你就散步——你愿意让一天持续多久就可以持续多久。","t":[9075,13200]}]},{"id":"ch14p29","audio":true,"sents":[{"en":"\"That doesn't do me much good,\" said the lamplighter.","zh":"这对我没什么好处，”点灯人说。","t":[125,3338]},{"en":"\"The one thing I love in life is to sleep.\"","zh":"我生活中唯一爱的事情就是睡觉。","t":[3338,5612]}]},{"id":"ch14p30","audio":true,"sents":[{"en":"\"Then you're unlucky,\" said the little prince.","zh":"那你真是不幸，”小王子说。","t":[125,2676]}]},{"id":"ch14p31","audio":true,"sents":[{"en":"\"I am unlucky,\" said the lamplighter.","zh":"我很不幸，”点灯人说。","t":[138,2762]},{"en":"\"Good morning.\" And he put out his lamp.","zh":"早上好。”然后他熄灭了灯。","t":[2762,5338]}]},{"id":"ch14p32","audio":true,"sents":[{"en":"\"That man,\" said the little prince to himself, as he continued farther on his journey, \"that man would be scorned by all the others: by the king, by the conceited man, by the tippler, by the businessman.","zh":"那个人，”小王子继续他的旅程时自言自语，“那个人会被所有人嘲笑：被国王、被自负的人、被酒鬼、被商人。","t":[125,11788]},{"en":"Nevertheless he is the only one of them all who does not seem to me ridiculous.","zh":"然而，在我看来，他是他们所有人中唯一一个不显得滑稽的人。","t":[11788,16562]},{"en":"Perhaps that is because he is thinking of something else besides himself.\"","zh":"也许这是因为他在想除了他自己以外的事情。","t":[16562,20526]}]},{"id":"ch14p33","audio":true,"sents":[{"en":"He breathed a sigh of regret, and said to himself, again:","zh":"他叹了口气，又对自己说：","t":[125,3663]}]},{"id":"ch14p34","audio":true,"sents":[{"en":"\"That man is the only one of them all whom I could have made my friend.","zh":"那是一个我唯一能成为朋友的人。","t":[138,4212]},{"en":"But his planet is indeed too small.","zh":"但他的星球确实太小了。","t":[4212,6875]},{"en":"There is no room on it for two people...\"","zh":"上面没有足够的空间容纳两个人...","t":[6875,8963]}]},{"id":"ch14p35","audio":true,"sents":[{"en":"What the little prince did not dare confess was that he was sorry most of all to leave this planet, because it was blest every day with 1440 sunsets!","zh":"小王子不敢承认的是，他最遗憾的是离开这个星球，因为它每天都会迎来1440次日落！","t":[100,9312]}]}]},{"id":"ch15","title_en":"Chapter XV","title_zh":"第 15 章","paras":[{"id":"ch15p00","audio":true,"sents":[{"en":"The sixth planet was ten times larger than the last one.","zh":"第六颗星球比最后一颗大十倍。","t":[138,3762]},{"en":"It was inhabited by an old gentleman who wrote voluminous books.","zh":"它住着一个写了很多书的老人。","t":[3762,7662]}]},{"id":"ch15p01","audio":true,"sents":[{"en":"\"Oh, look!","zh":"哦，看！","t":[100,1438]},{"en":"Here is an explorer!\" he exclaimed to himself when he saw the little prince coming.","zh":"当他看到小王子走来时，他自言自语道：“这里是一位探险家！”","t":[1438,5813]}]},{"id":"ch15p02","audio":true,"sents":[{"en":"The little prince sat down on the table and panted a little.","zh":"小王子坐在桌子上，喘着气。","t":[138,3725]},{"en":"He had already travelled so much and so far!","zh":"他已经走了这么远，这么久！","t":[3725,6338]}]},{"id":"ch15p03","audio":true,"sents":[{"en":"\"Where do you come from?\" the old gentleman said to him.","zh":"“你从哪里来？”老先生问他。","t":[125,3075]}]},{"id":"ch15p04","audio":true,"sents":[{"en":"\"What is that big book?\" said the little prince.","zh":"那本大书是什么？小王子问道。","t":[138,3225]},{"en":"\"What are you doing?\"","zh":"你在做什么？","t":[3225,4250]}]},{"id":"ch15p05","audio":true,"sents":[{"en":"\"I am a geographer,\" the old gentleman said to him.","zh":"“我是一个地理学家，”那位老先生对他说。","t":[138,3063]}]},{"id":"ch15p06","audio":true,"sents":[{"en":"\"What is a geographer?\" asked the little prince.","zh":"小王子问：“地理学家是做什么的？”","t":[125,2975]}]},{"id":"ch15p07","audio":true,"sents":[{"en":"\"A geographer is a scholar who knows the location of all the seas, rivers, towns, mountains, and deserts.\"","zh":"地理学家是一位知晓所有海洋、河流、城镇、山脉和沙漠位置的学者。","t":[138,7063]}]},{"id":"ch15p08","audio":true,"sents":[{"en":"\"That is very interesting,\" said the little prince.","zh":"“这非常有趣，”小王子说。","t":[125,3350]},{"en":"\"Here at last is a man who has a real profession!\" And he cast a look around him at the planet of the geographer.","zh":"这里终于有一个真正有职业的人了！他环顾四周，看着地理学家的星球。","t":[3350,10212]},{"en":"It was the most magnificent and stately planet that he had ever seen.","zh":"这是他见过的最壮丽、最庄严的星球。","t":[10212,14075]}]},{"id":"ch15p09","audio":true,"sents":[{"en":"\"Your planet is very beautiful,\" he said.","zh":"“你的星球非常美丽，”他说。","t":[138,3075]},{"en":"\"Has it any oceans?\"","zh":"它有什么海洋吗？","t":[3075,4463]}]},{"id":"ch15p10","audio":true,"sents":[{"en":"\"I couldn't tell you,\" said the geographer.","zh":"“我无法告诉你，”地理学家说。","t":[138,2376]}]},{"id":"ch15p11","audio":true,"sents":[{"en":"\"Ah!\" The little prince was disappointed.","zh":"“啊！”小王子感到失望。","t":[100,3300]},{"en":"\"Has it any mountains?\"","zh":"它有山吗？","t":[3300,4737]}]},{"id":"ch15p12","audio":true,"sents":[{"en":"\"I couldn't tell you,\" said the geographer.","zh":"“我无法告诉你，”地理学家说。","t":[138,2376]}]},{"id":"ch15p13","audio":true,"sents":[{"en":"\"And towns, and rivers, and deserts?\"","zh":"城镇、河流和沙漠？","t":[112,2812]}]},{"id":"ch15p14","audio":true,"sents":[{"en":"\"I couldn't tell you that, either.\"","zh":"我也无法告诉你。","t":[138,2100]}]},{"id":"ch15p15","audio":true,"sents":[{"en":"\"But you are a geographer!\"","zh":"但你是个地理学家啊！","t":[100,1588]}]},{"id":"ch15p16","audio":true,"sents":[{"en":"\"Exactly,\" the geographer said.","zh":"“正是如此，”地理学家说。","t":[112,2600]},{"en":"\"But I am not an explorer.","zh":"“但我不是探险家。”","t":[2600,4600]},{"en":"I haven't a single explorer on my planet.","zh":"在我的星球上，我连一个探险家都没有。","t":[4600,7638]},{"en":"It is not the geographer who goes out to count the towns, the rivers, the mountains, the seas, the oceans, and the deserts.","zh":"地理学家并不是出去数城镇、河流、山脉、海洋、沙漠的人。","t":[7638,15575]},{"en":"The geographer is much too important to go loafing about.","zh":"地理学家太重要了，不能到处闲逛。","t":[15575,19538]},{"en":"He does not leave his desk.","zh":"他从不离开他的办公桌。","t":[19538,21525]},{"en":"But he receives the explorers in his study.","zh":"但他会在他的书房里接待探险家。","t":[21525,24450]},{"en":"He asks them questions, and he notes down what they recall of their travels.","zh":"他会问他们问题，并记下他们回忆中的旅行。","t":[24450,29025]},{"en":"And if the recollections of any one among them seem interesting to him, the geographer orders an inquiry into that explorer's moral character.\"","zh":"如果其中任何一个人的回忆对他来说似乎很有趣，地理学家就会下令调查那个探险家的道德品质。","t":[29025,36612]}]},{"id":"ch15p17","audio":true,"sents":[{"en":"\"Why is that?\"","zh":"为什么是那个？","t":[112,1088]}]},{"id":"ch15p18","audio":true,"sents":[{"en":"\"Because an explorer who told lies would bring disaster on the books of the geographer.","zh":"因为一个说谎的探险家会给地理学家的书籍带来灾难。","t":[112,5162]},{"en":"So would an explorer who drank too much.\"","zh":"一个喝得太多的探险家也会如此。","t":[5162,7700]}]},{"id":"ch15p19","audio":true,"sents":[{"en":"\"Why is that?\" asked the little prince.","zh":"“那为什么？”小王子问道。","t":[138,2600]}]},{"id":"ch15p20","audio":true,"sents":[{"en":"\"Because intoxicated men see double.","zh":"因为醉汉看人看物都是两个。","t":[100,2938]},{"en":"Then the geographer would note down two mountains in a place where there was only one.\"","zh":"然后地理学家会在只有一座山的地方记下两座山。","t":[2938,7387]}]},{"id":"ch15p21","audio":true,"sents":[{"en":"\"I know some one,\" said the little prince, \"who would make a bad explorer.\"","zh":"“我知道有个人，”小王子说，“他根本不适合当探险家。”","t":[138,4100]}]},{"id":"ch15p22","audio":true,"sents":[{"en":"\"That is possible.","zh":"这是可能的。","t":[125,1650]},{"en":"Then, when the moral character of the explorer is shown to be good, an inquiry is ordered into his discovery.\"","zh":"然后，当探险者的道德品质被证明是良好时，对他的发现便进行了调查。","t":[1650,7975]}]},{"id":"ch15p23","audio":true,"sents":[{"en":"\"One goes to see it?\"","zh":"一个人去看它？","t":[125,1400]}]},{"id":"ch15p24","audio":true,"sents":[{"en":"\"No.","zh":"不。","t":[100,1000]},{"en":"That would be too complicated.","zh":"这会太复杂了。","t":[1000,3162]},{"en":"But one requires the explorer to furnish proofs.","zh":"但需要探险者提供证据。","t":[3162,6550]},{"en":"For example, if the discovery in question is that of a large mountain, one requires that large stones be brought back from it.\"","zh":"例如，如果所讨论的发现是一座大山，那么就需要从那里带回大石头。","t":[6550,13537]}]},{"id":"ch15p25","audio":true,"sents":[{"en":"The geographer was suddenly stirred to excitement.","zh":"地理学家突然激动起来。","t":[138,3075]}]},{"id":"ch15p26","audio":true,"sents":[{"en":"\"But you-- you come from far away!","zh":"但你——你来自远方！","t":[100,2338]},{"en":"You are an explorer!","zh":"你是一位探险家！","t":[2338,3825]},{"en":"You shall describe your planet to me!\"","zh":"你必须向我描述你的星球！","t":[3825,5800]}]},{"id":"ch15p27","audio":true,"sents":[{"en":"And, having opened his big register, the geographer sharpened his pencil.","zh":"地理学家打开了他的大账本，然后削尖了他的铅笔。","t":[138,5100]},{"en":"The recitals of explorers are put down first in pencil.","zh":"探险家的叙述最初是用铅笔记录的。","t":[5100,9038]},{"en":"One waits until the explorer has furnished proofs, before putting them down in ink.","zh":"人们等到探险家提供了证据，才把它们用墨水记录下来。","t":[9038,13876]}]},{"id":"ch15p28","audio":true,"sents":[{"en":"\"Well?\" said the geographer expectantly.","zh":"“嗯？”地理学家期待地问道。","t":[138,2900]}]},{"id":"ch15p29","audio":true,"sents":[{"en":"\"Oh, where I live,\" said the little prince, \"it is not very interesting.","zh":"哦，在我住的地方，小王子说，“并不怎么有趣。”","t":[125,4725]},{"en":"It is all so small.","zh":"这一切都如此渺小。","t":[4725,6475]},{"en":"I have three volcanoes.","zh":"我有三座火山。","t":[6475,8438]},{"en":"Two volcanoes are active and the other is extinct.","zh":"两座火山是活火山，另一座已经熄灭了。","t":[8438,11938]},{"en":"But one never knows.\"","zh":"但谁又能知道呢。","t":[11938,13262]}]},{"id":"ch15p30","audio":true,"sents":[{"en":"\"One never knows,\" said the geographer.","zh":"谁又能知道呢，”地理学家说。","t":[138,2438]}]},{"id":"ch15p31","audio":true,"sents":[{"en":"\"I have also a flower.\"","zh":"我还有一朵花。","t":[100,1637]}]},{"id":"ch15p32","audio":true,"sents":[{"en":"\"We do not record flowers,\" said the geographer.","zh":"我们不记录花朵，”地理学家说。","t":[138,2938]}]},{"id":"ch15p33","audio":true,"sents":[{"en":"\"Why is that?","zh":"为什么是那样呢？","t":[112,1462]},{"en":"The flower is the most beautiful thing on my planet!\"","zh":"这朵花是我星球上最美丽的东西！","t":[1462,4450]}]},{"id":"ch15p34","audio":true,"sents":[{"en":"\"We do not record them,\" said the geographer, \"because they are ephemeral.\"","zh":"我们不记录它们，”地理学家说，“因为它们是短暂的。","t":[138,4100]}]},{"id":"ch15p35","audio":true,"sents":[{"en":"\"What does that mean-- 'ephemeral'?\"","zh":"那“转瞬即逝”是什么意思？","t":[138,1663]}]},{"id":"ch15p36","audio":true,"sents":[{"en":"\"Geographies,\" said the geographer, \"are the books which, of all books, are most concerned with matters of consequence.","zh":"地理学，“地理学家说，“是所有书籍中最关注重大事务的。”","t":[100,7250]},{"en":"They never become old-fashioned.","zh":"它们永远不会过时。","t":[7250,9462]},{"en":"It is very rarely that a mountain changes its position.","zh":"山峰的位置很少改变。","t":[9462,13025]},{"en":"It is very rarely that an ocean empties itself of its waters.","zh":"海洋很少会完全干涸。","t":[13025,17150]},{"en":"We write of eternal things.\"","zh":"我们谈论永恒的事物。","t":[17150,18875]}]},{"id":"ch15p37","audio":true,"sents":[{"en":"\"But extinct volcanoes may come to life again,\" the little prince interrupted.","zh":"“但是死火山也许会再次苏醒，”小王子打断了他的话。","t":[100,5100]},{"en":"\"What does that mean-- 'ephemeral'?\"","zh":"那“转瞬即逝”是什么意思？","t":[5100,6662]}]},{"id":"ch15p38","audio":true,"sents":[{"en":"\"Whether volcanoes are extinct or alive, it comes to the same thing for us,\" said the geographer.","zh":"“火山是死是活，对我们来说都一样，”地理学家说。","t":[138,5938]},{"en":"\"The thing that matters to us is the mountain.","zh":"对我们来说，重要的是那座山。","t":[5938,8775]},{"en":"It does not change.\"","zh":"它不会改变。","t":[8775,10000]}]},{"id":"ch15p39","audio":true,"sents":[{"en":"\"But what does that mean-- 'ephemeral'?\" repeated the little prince, who never in his life had let go of a question, once he had asked it.","zh":"“但‘转瞬即逝’是什么意思？”小王子重复道，他一旦提出问题就绝不会放弃。","t":[100,7200]}]},{"id":"ch15p40","audio":true,"sents":[{"en":"\"It means, 'which is in danger of speedy disappearance.'\"","zh":"这意味着，“它意味着，有迅速消失的危险。”","t":[138,3650]}]},{"id":"ch15p41","audio":true,"sents":[{"en":"\"Is my flower in danger of speedy disappearance?\"","zh":"我的花朵是不是很快就要消失了？","t":[112,3300]}]},{"id":"ch15p42","audio":true,"sents":[{"en":"\"Certainly it is.\"","zh":"当然是这样。","t":[125,1350]}]},{"id":"ch15p43","audio":true,"sents":[{"en":"\"My flower is ephemeral,\" the little prince said to himself, \"and she has only four thorns to defend herself against the world.","zh":"我的花朵是短暂的，小王子自言自语道，她只有四根刺来保护自己免受世界的伤害。","t":[138,7388]},{"en":"And I have left her on my planet, all alone!\"","zh":"我让她留在了我的星球上，独自一人！","t":[7388,10087]}]},{"id":"ch15p44","audio":true,"sents":[{"en":"That was his first moment of regret.","zh":"这是他第一次感到后悔的时刻。","t":[138,2662]},{"en":"But he took courage once more.","zh":"但他又鼓起了勇气。","t":[2662,4425]}]},{"id":"ch15p45","audio":true,"sents":[{"en":"\"What place would you advise me to visit now?\" he asked.","zh":"他问道：“你现在会建议我参观哪个地方？”","t":[138,3412]}]},{"id":"ch15p46","audio":true,"sents":[{"en":"\"The planet Earth,\" replied the geographer.","zh":"地球，”地理学家回答道。","t":[138,3012]},{"en":"\"It has a good reputation.\"","zh":"它享有很好的声誉。","t":[3012,4625]}]},{"id":"ch15p47","audio":true,"sents":[{"en":"And the little prince went away, thinking of his flower.","zh":"小王子于是离开了，心里想着他的花朵。","t":[138,3250]}]}]},{"id":"ch16","title_en":"Chapter XVI","title_zh":"第 16 章","paras":[{"id":"ch16p00","audio":true,"sents":[{"en":"So then the seventh planet was the Earth.","zh":"那么第七颗行星就是地球。","t":[112,2425]}]},{"id":"ch16p01","audio":true,"sents":[{"en":"The Earth is not just an ordinary planet!","zh":"地球不仅仅是一颗普通的行星！","t":[125,2975]},{"en":"One can count; there are 111 kings (not forgetting, to be sure, the Negro kings among them), 7000 geographers, 900,000 businessmen, 7,500,000 tipplers, and 311,000,000 conceited men-- that is to say, about 2,000,000,000 grown-ups.","zh":"可以数一数；有111个国王（当然，别忘了黑人国王），7000个地理学家，900000个商人，75000000个酒鬼，以及311000000个自负的人——也就是说，大约有20亿个成人。","t":[2975,21150]}]},{"id":"ch16p02","audio":true,"sents":[{"en":"To give you an idea of the size of the Earth, I will tell you that before the invention of electricity it was necessary to maintain, over the whole of the six continents, a veritable army of 462,511 lamplighters for the street lamps.","zh":"为了给您一个关于地球大小的概念，我要告诉您，在电发明之前，在六大洲上，需要维持一支462511人的点灯人军队来维护街灯。","t":[100,14550]}]},{"id":"ch16p03","audio":true,"sents":[{"en":"Seen from a slight distance, that would make a splendid spectacle.","zh":"从稍远一点的地方看，那将是一场壮观的景象。","t":[112,4262]},{"en":"The movements of this army would be regulated like those of the ballet in the opera.","zh":"这支军队的行进将被调节得像歌剧院中芭蕾舞团的行进一样。","t":[4262,9012]},{"en":"First would come the turn of the lamplighters of New Zealand and Australia.","zh":"首先是新西兰和澳大利亚的点灯人的轮班时间。","t":[9012,13588]},{"en":"Having set their lamps alight, these would go off to sleep.","zh":"点亮了他们的灯，这些人就会去睡觉。","t":[13588,17275]},{"en":"Next, the lamplighters of China and Siberia would enter for their steps in the dance, and then they too would be waved back into the wings.","zh":"接着，中国和西伯利亚的提灯人将加入舞蹈，然后他们也会被挥手送回幕后。","t":[17275,25200]},{"en":"After that would come the turn of the lamplighters of Russia and the Indies; then those of Africa and Europe, then those of South America; then those of South America; then those of North America.","zh":"之后是俄罗斯和印度的提灯人；然后是非洲和欧洲的；然后是南美洲的；然后是北美洲的。","t":[25200,35938]},{"en":"And never would they make a mistake in the order of their entry upon the stage.","zh":"他们永远不会在登台顺序上出错。","t":[35938,40288]},{"en":"It would be magnificent.","zh":"这将是非常壮观的。","t":[40288,41788]}]},{"id":"ch16p04","audio":true,"sents":[{"en":"Only the man who was in charge of the single lamp at the North Pole, and his colleague who was responsible for the single lamp at the South Pole-- only these two would live free from toil and care: they would be busy twice a year.","zh":"只有负责北极那盏灯的人，以及负责南极那盏灯的同事——只有这两个人能摆脱劳苦和忧虑：他们一年要忙两次。","t":[100,11050]}]}]},{"id":"ch17","title_en":"Chapter XVII","title_zh":"第 17 章","paras":[{"id":"ch17p00","audio":true,"sents":[{"en":"When one wishes to play the wit, he sometimes wanders a little from the truth.","zh":"当一个人想要卖弄聪明时，他有时会稍微偏离真相。","t":[125,4950]},{"en":"I have not been altogether honest in what I have told you about the lamplighters.","zh":"我承认，我在告诉你关于提灯人的事情时并不完全诚实。","t":[4950,9612]},{"en":"And I realize that I run the risk of giving a false idea of our planet to those who do not know it.","zh":"我意识到，我可能给那些不了解我们星球的人留下了错误的印象。","t":[9612,15425]},{"en":"Men occupy a very small place upon the Earth.","zh":"人类在地球上占据的位置非常小。","t":[15425,18788]},{"en":"If the two billion inhabitants who people its surface were all to stand upright and somewhat crowded together, as they do for some big public assembly, they could easily be put into one public square twenty miles long and twenty miles wide.","zh":"如果居住在其表面的二十亿居民都站立起来，并且像在一些大型公众集会上那样稍微挤在一起，他们可以轻易地被安置在一个长二十英里、宽二十英里的公共广场上。","t":[18788,31650]},{"en":"All humanity could be piled up on a small Pacific islet.","zh":"整个人类都可以堆叠在一个小小的太平洋岛屿上。","t":[31650,35237]}]},{"id":"ch17p01","audio":true,"sents":[{"en":"The grown-ups, to be sure, will not believe you when you tell them that.","zh":"当然，当你告诉他们这一点时，他们不会相信你。","t":[138,4450]},{"en":"They imagine that they fill a great deal of space.","zh":"他们想象自己占据了很大的空间。","t":[4450,7512]},{"en":"They fancy themselves as important as the baobabs.","zh":"他们把自己想象得和猴面包树一样重要。","t":[7512,11075]},{"en":"You should advise them, then, to make their own calculations.","zh":"那么，你应该建议他们自己进行计算。","t":[11075,15125]},{"en":"They adore figures, and that will please them.","zh":"他们崇拜数字，这会让他们很高兴。","t":[15125,17962]},{"en":"But do not waste your time on this extra task.","zh":"但不要在这个额外任务上浪费时间。","t":[17962,21138]},{"en":"It is unnecessary.","zh":"这是不必要的。","t":[21138,22850]},{"en":"You have, I know, confidence in me.","zh":"我知道，你对我有信心。","t":[22850,25400]}]},{"id":"ch17p02","audio":true,"sents":[{"en":"When the little prince arrived on the Earth, he was very much surprised not to see any people.","zh":"当小王子到达地球时，他惊讶地发现这里没有人。","t":[138,5612]},{"en":"He was beginning to be afraid he had come to the wrong planet, when a coil of gold, the colour of the moonlight, flashed across the sand.","zh":"他开始害怕自己来到了错误的星球，就在这时，一道金色线圈，如同月光一般，在沙地上闪过。","t":[5612,12750]}]},{"id":"ch17p03","audio":true,"sents":[{"en":"\"Good evening,\" said the little prince courteously.","zh":"晚上好，”小王子有礼貌地说。","t":[112,2813]}]},{"id":"ch17p04","audio":true,"sents":[{"en":"\"Good evening,\" said the snake.","zh":"晚上好，”蛇说。","t":[100,1950]}]},{"id":"ch17p05","audio":true,"sents":[{"en":"\"What planet is this on which I have come down?\" asked the little prince.","zh":"“我降落在了哪个星球上？”小王子问道。","t":[138,4200]}]},{"id":"ch17p06","audio":true,"sents":[{"en":"\"This is the Earth; this is Africa,\" the snake answered.","zh":"这是地球；这是非洲，蛇回答道。","t":[100,3588]}]},{"id":"ch17p07","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,838]},{"en":"Then there are no people on the Earth?\"","zh":"那么地球上就没有人了吗？","t":[838,2738]}]},{"id":"ch17p08","audio":true,"sents":[{"en":"\"This is the desert.","zh":"这是沙漠。","t":[125,1725]},{"en":"There are no people in the desert.","zh":"沙漠里没有人类。","t":[1725,3875]},{"en":"The Earth is large,\" said the snake.","zh":"地球很大，“蛇说。”","t":[3875,6076]}]},{"id":"ch17p09","audio":true,"sents":[{"en":"The little prince sat down on a stone, and raised his eyes toward the sky.","zh":"小王子坐在一块石头上，抬起眼睛望向天空。","t":[138,4263]}]},{"id":"ch17p10","audio":true,"sents":[{"en":"\"I wonder,\" he said, \"whether the stars are set alight in heaven so that one day each one of us may find his own again...","zh":"他问道：“我想知道，天上的星星是否是为了有一天我们每个人都能再次找到自己的那颗而点亮……”","t":[138,7062]},{"en":"Look at my planet.","zh":"看我的星球。","t":[7062,8688]},{"en":"It is right there above us.","zh":"它就在我们上方。","t":[8688,10675]},{"en":"But how far away it is!\"","zh":"但它是多么遥远啊！","t":[10675,12238]}]},{"id":"ch17p11","audio":true,"sents":[{"en":"\"It is beautiful,\" the snake said.","zh":"“真美啊，”蛇说。","t":[112,2612]},{"en":"\"What has brought you here?\"","zh":"“是什么让你来到这里的？”","t":[2612,3963]}]},{"id":"ch17p12","audio":true,"sents":[{"en":"\"I have been having some trouble with a flower,\" said the little prince.","zh":"“我最近有点麻烦，是关于一朵花的。”小王子说。","t":[138,3726]}]},{"id":"ch17p13","audio":true,"sents":[{"en":"\"Ah!\" said the snake.","zh":"“啊！”蛇说。","t":[138,1513]}]},{"id":"ch17p14","audio":true,"sents":[{"en":"And they were both silent.","zh":"他们俩都沉默了。","t":[138,1588]}]},{"id":"ch17p15","audio":true,"sents":[{"en":"\"Where are the men?\" the little prince at last took up the conversation again.","zh":"‘人们在哪里？’小王子终于又开始了对话。","t":[138,4300]}]},{"id":"ch17p16","audio":true,"sents":[{"en":"\"It is a little lonely in the desert...\"","zh":"‘在沙漠里有点孤单……’","t":[138,2187]}]},{"id":"ch17p17","audio":true,"sents":[{"en":"\"It is also lonely among men,\" the snake said.","zh":"‘在人群中也很孤单，’蛇说。","t":[138,3013]}]},{"id":"ch17p18","audio":true,"sents":[{"en":"The little prince gazed at him for a long time.","zh":"小王子久久地凝视着他。","t":[138,2700]}]},{"id":"ch17p19","audio":true,"sents":[{"en":"\"You are a funny animal,\" he said at last.","zh":"‘你真是个有趣的动物，’他最后说。","t":[138,3025]},{"en":"\"You are no thicker than a finger...\"","zh":"‘你还没有手指粗呢……’","t":[3025,4750]}]},{"id":"ch17p20","audio":true,"sents":[{"en":"\"But I am more powerful than the finger of a king,\" said the snake.","zh":"‘但我比国王的手指更有力量，’蛇说。","t":[100,3650]}]},{"id":"ch17p21","audio":true,"sents":[{"en":"The little prince smiled.","zh":"小王子笑了。","t":[138,1625]}]},{"id":"ch17p22","audio":true,"sents":[{"en":"\"You are not very powerful.","zh":"‘你并不很有力量。’","t":[138,2112]},{"en":"You haven't even any feet.","zh":"你甚至没有脚。","t":[2112,4138]},{"en":"You cannot even travel...\"","zh":"你甚至无法旅行...","t":[4138,5638]}]},{"id":"ch17p23","audio":true,"sents":[{"en":"\"I can carry you farther than any ship could take you,\" said the snake.","zh":"我说，‘我可以带你走得更远，任何船只都无法比拟。’","t":[138,3937]}]},{"id":"ch17p24","audio":true,"sents":[{"en":"He twined himself around the little prince's ankle, like a golden bracelet.","zh":"他像一条金手镯一样缠绕在小王子的脚踝上。","t":[125,4600]}]},{"id":"ch17p25","audio":true,"sents":[{"en":"\"Whomever I touch, I send back to the earth from whence he came,\" the snake spoke again.","zh":"‘无论我触摸谁，我都会把他送回到他来的地方，’蛇再次说道。","t":[138,5562]},{"en":"\"But you are innocent and true, and you come from a star...\"","zh":"‘但你纯洁而真诚，你来自一颗星星...’","t":[5562,8837]}]},{"id":"ch17p26","audio":true,"sents":[{"en":"The little prince made no reply.","zh":"小王子没有回答。","t":[138,2163]}]},{"id":"ch17p27","audio":true,"sents":[{"en":"\"You move me to pity-- you are so weak on this Earth made of granite,\" the snake said.","zh":"‘你让我感到同情——你在这个由花岗岩构成的地球上如此脆弱，’蛇说。","t":[138,5175]},{"en":"\"I can help you, some day, if you grow too homesick for your own planet.","zh":"‘如果你有一天太想家了，我可以帮你。'","t":[5175,9825]},{"en":"I can--\"","zh":"我可以——","t":[9825,10475]}]},{"id":"ch17p28","audio":true,"sents":[{"en":"\"Oh!","zh":"哦！","t":[100,838]},{"en":"I understand you very well,\" said the little prince.","zh":"我非常了解你，“小王子说。","t":[838,4325]},{"en":"\"But why do you always speak in riddles?\"","zh":"但你为什么总是说谜语呢？","t":[4325,6550]}]},{"id":"ch17p29","audio":true,"sents":[{"en":"\"I solve them all,\" said the snake.","zh":"“我都能解决，”蛇说。","t":[138,2200]}]},{"id":"ch17p30","audio":true,"sents":[{"en":"And they were both silent.","zh":"他们俩都沉默了。","t":[138,1588]}]}]},{"id":"ch18","title_en":"Chapter XVIII","title_zh":"第 18 章","paras":[{"id":"ch18p00","audio":true,"sents":[{"en":"The little prince crossed the desert and met with only one flower.","zh":"小王子穿越了沙漠，只遇到了一朵花。","t":[138,4038]},{"en":"It was a flower with three petals, a flower of no account at all.","zh":"这是一朵有三片花瓣的花，一朵毫不起眼的花。","t":[4038,7937]}]},{"id":"ch18p01","audio":true,"sents":[{"en":"\"Good morning,\" said the little prince.","zh":"早上好，小王子说。","t":[112,2312]}]},{"id":"ch18p02","audio":true,"sents":[{"en":"\"Good morning,\" said the flower.","zh":"早上好，花儿说。","t":[100,1987]}]},{"id":"ch18p03","audio":true,"sents":[{"en":"\"Where are the men?\" the little prince asked, politely.","zh":"小王子有礼貌地问道：“人们在哪里？”","t":[138,3413]}]},{"id":"ch18p04","audio":true,"sents":[{"en":"The flower had once seen a caravan passing.","zh":"那朵花曾见过一支商队经过。","t":[138,2712]}]},{"id":"ch18p05","audio":true,"sents":[{"en":"\"Men?\" she echoed.","zh":"“男人？”她重复道。","t":[112,2012]},{"en":"\"I think there are six or seven of them in existence.","zh":"我想它们大概有六七个存在。","t":[2012,5225]},{"en":"I saw them, several years ago.","zh":"我几年前见过他们。","t":[5225,7650]},{"en":"But one never knows where to find them.","zh":"但人们永远不知道它们在哪里。","t":[7650,10062]},{"en":"The wind blows them away.","zh":"风把它们吹走了。","t":[10062,11988]},{"en":"They have no roots, and that makes their life very difficult.\"","zh":"它们没有根，这使它们的生活非常艰难。","t":[11988,15475]}]},{"id":"ch18p06","audio":true,"sents":[{"en":"\"Goodbye,\" said the little prince.","zh":"“再见，”小王子说。","t":[112,2175]}]},{"id":"ch18p07","audio":true,"sents":[{"en":"\"Goodbye,\" said the flower.","zh":"“再见，”花儿说。","t":[100,1874]}]}]},{"id":"ch19","title_en":"Chapter XIX","title_zh":"第 19 章","paras":[{"id":"ch19p00","audio":true,"sents":[{"en":"After that, the little prince climbed a high mountain.","zh":"之后，小王子爬上了一座高山。","t":[125,3588]},{"en":"The only mountains he had ever known were the three volcanoes, which came up to his knees.","zh":"他曾经知道的唯一山脉就是那三座火山，它们一直延伸到他的膝盖。","t":[3588,8762]},{"en":"And he used the extinct volcano as a footstool.","zh":"他还将那座熄灭的火山用作脚凳。","t":[8762,12100]},{"en":"\"From a mountain as high as this one,\" he said to himself, \"I shall be able to see the whole planet at one glance, and all the people...\"","zh":"“从这么高的山上，”他自言自语，“我一眼就能看到整个星球，还有所有人……","t":[12100,19337]}]},{"id":"ch19p01","audio":true,"sents":[{"en":"But he saw nothing, save peaks of rock that were sharpened like needles.","zh":"但他什么也没看到，除了像针尖一样尖锐的岩石峰。","t":[100,4212]}]},{"id":"ch19p02","audio":true,"sents":[{"en":"\"Good morning,\" he said courteously.","zh":"早上好，”他礼貌地说。","t":[100,2300]}]},{"id":"ch19p03","audio":true,"sents":[{"en":"\"Good morning--Good morning--Good morning,\" answered the echo.","zh":"早上好——早上好——早上好，”回声回答。","t":[100,3187]}]},{"id":"ch19p04","audio":true,"sents":[{"en":"\"Who are you?\" said the little prince.","zh":"你是谁？”小王子说。","t":[138,2326]}]},{"id":"ch19p05","audio":true,"sents":[{"en":"\"Who are you--Who are you--Who are you?\" answered the echo.","zh":"你是谁——你是谁——你是谁？”回声回答。","t":[138,3100]}]},{"id":"ch19p06","audio":true,"sents":[{"en":"\"Be my friends.","zh":"成为我的朋友吧。","t":[112,1538]},{"en":"I am all alone,\" he said.","zh":"我孤孤单单的，”他说。","t":[1538,3225]}]},{"id":"ch19p07","audio":true,"sents":[{"en":"\"I am all alone--all alone--all alone,\" answered the echo.","zh":"“我孤单一人——孤单一人——孤单一人，”回声回答道。","t":[138,3400]}]},{"id":"ch19p08","audio":true,"sents":[{"en":"\"What a queer planet!\" he thought.","zh":"多么奇怪的一个星球啊！他心想。","t":[100,2425]},{"en":"\"It is altogether dry, and altogether pointed, and altogether harsh and forbidding.","zh":"它完全干燥，完全尖锐，完全严酷而拒人于千里之外。","t":[2425,7638]},{"en":"And the people have no imagination.","zh":"人们没有想象力。","t":[7638,10088]},{"en":"They repeat whatever one says to them...","zh":"他们重复别人对她们说的话……","t":[10088,12662]},{"en":"On my planet I had a flower; she always was the first to speak...\"","zh":"在我的星球上，我有一朵花；她总是第一个开口说话……","t":[12662,16613]}]}]},{"id":"ch20","title_en":"Chapter XX","title_zh":"第 20 章","paras":[{"id":"ch20p00","audio":true,"sents":[{"en":"But it happened that after walking for a long time through sand, and rocks, and snow, the little prince at last came upon a road.","zh":"但小王子在走过漫长的沙地、岩石和雪地之后，终于来到了一条路上。","t":[100,7413]}]},{"id":"ch20p01","audio":true,"sents":[{"en":"And all roads lead to the abodes of men.","zh":"所有道路都通向人类的住所。","t":[138,2574]}]},{"id":"ch20p02","audio":true,"sents":[{"en":"\"Good morning,\" he said.","zh":"早上好，”他说。","t":[100,1638]}]},{"id":"ch20p03","audio":true,"sents":[{"en":"He was standing before a garden, all a-bloom with roses.","zh":"他站在一个盛开着玫瑰的花园前。","t":[125,3575]}]},{"id":"ch20p04","audio":true,"sents":[{"en":"\"Good morning,\" said the roses.","zh":"早上好，玫瑰花们说。","t":[100,2075]}]},{"id":"ch20p05","audio":true,"sents":[{"en":"The little prince gazed at them.","zh":"小王子凝视着它们。","t":[138,2250]},{"en":"They all looked like his flower.","zh":"它们都像他的花朵。","t":[2250,3838]}]},{"id":"ch20p06","audio":true,"sents":[{"en":"\"Who are you?\" he demanded, thunderstruck.","zh":"他惊讶地问道：“你是谁？”","t":[138,2987]}]},{"id":"ch20p07","audio":true,"sents":[{"en":"\"We are roses,\" the roses said.","zh":"“我们是玫瑰，”玫瑰们说。","t":[138,2325]}]},{"id":"ch20p08","audio":true,"sents":[{"en":"And he was overcome with sadness.","zh":"他感到非常悲伤。","t":[138,2475]},{"en":"His flower had told him that she was the only one of her kind in all the universe.","zh":"他的花朵曾告诉他，她是宇宙中唯一的一种。","t":[2475,7275]},{"en":"And here were five thousand of them, all alike, in one single garden!","zh":"这里竟然有五千朵，全都是一模一样，生长在同一个花园里！","t":[7275,11350]}]},{"id":"ch20p09","audio":true,"sents":[{"en":"\"She would be very much annoyed,\" he said to himself, \"if she should see that...","zh":"“如果她看到那样……她一定会非常生气，”他自言自语道。","t":[125,4238]},{"en":"she would cough most dreadfully, and she would pretend that she was dying, to avoid being laughed at.","zh":"她咳嗽得非常可怕，假装自己快要死了，以免被人嘲笑。","t":[4238,9588]},{"en":"And I should be obliged to pretend that I was nursing her back to life-- for if I did not do that, to humble myself also, she would really allow herself to die...\"","zh":"我应该假装自己在照顾她恢复生机——因为如果不这样做，为了让自己谦卑，她真的会让自己死去……","t":[9588,18075]}]},{"id":"ch20p10","audio":true,"sents":[{"en":"Then he went on with his reflections: \"I thought that I was rich, with a flower that was unique in all the world; and all I had was a common rose.","zh":"然后他继续他的沉思：“我以为自己很富有，因为我拥有一朵世界上独一无二的花；而我所拥有的却只是一朵普通的玫瑰。”","t":[138,8400]},{"en":"A common rose, and three volcanoes that come up to my knees-- and one of them perhaps extinct forever...","zh":"一株普通的玫瑰，和三座到我膝盖高的火山——其中一座可能永远熄灭了……","t":[8400,14275]},{"en":"that doesn't make me a very great prince...\"","zh":"这并不让我成为一个伟大的王子……","t":[14275,16388]}]},{"id":"ch20p11","audio":true,"sents":[{"en":"And he lay down in the grass and cried.","zh":"他躺在草地上哭了起来。","t":[138,2337]}]}]},{"id":"ch21","title_en":"Chapter XXI","title_zh":"第 21 章","paras":[{"id":"ch21p00","audio":true,"sents":[{"en":"It was then that the fox appeared.","zh":"那时，狐狸出现了。","t":[138,2012]}]},{"id":"ch21p01","audio":true,"sents":[{"en":"\"Good morning,\" said the fox.","zh":"早上好，狐狸说。","t":[100,1988]}]},{"id":"ch21p02","audio":true,"sents":[{"en":"\"Good morning,\" the little prince responded politely, although when he turned around he saw nothing.","zh":"“早上好，”小王子有礼貌地回应道，尽管当他转身时，他什么也没看到。","t":[138,5313]}]},{"id":"ch21p03","audio":true,"sents":[{"en":"\"I am right here,\" the voice said, \"under the apple tree.\"","zh":"“我就在这里，”那个声音说，“在苹果树下。”","t":[138,3350]}]},{"id":"ch21p04","audio":true,"sents":[{"en":"\"Who are you?\" asked the little prince, and added, \"You are very pretty to look at.\"","zh":"小王子问道：“你是谁？”又补充道，“你看起来很漂亮。”","t":[138,4837]}]},{"id":"ch21p05","audio":true,"sents":[{"en":"\"I am a fox,\" said the fox.","zh":"我是一只狐狸，”狐狸说。","t":[138,2163]}]},{"id":"ch21p06","audio":true,"sents":[{"en":"\"Come and play with me,\" proposed the little prince.","zh":"来和我一起玩吧，”小王子提议。","t":[100,3325]},{"en":"\"I am so unhappy.\"","zh":"我很不快乐。","t":[3325,4662]}]},{"id":"ch21p07","audio":true,"sents":[{"en":"\"I cannot play with you,\" the fox said.","zh":"我不能和你一起玩，”狐狸说。","t":[138,2812]},{"en":"\"I am not tamed.\"","zh":"我没有被驯服。","t":[2812,3912]}]},{"id":"ch21p08","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,800]},{"en":"Please excuse me,\" said the little prince.","zh":"请原谅我，”小王子说。","t":[800,3350]}]},{"id":"ch21p09","audio":true,"sents":[{"en":"But, after some thought, he added: \"What does that mean-- 'tame'?\"","zh":"但，经过一番思考，他又补充道：“‘驯服’是什么意思？","t":[100,4037]}]},{"id":"ch21p10","audio":true,"sents":[{"en":"\"You do not live here,\" said the fox.","zh":"你不住在这里，”狐狸说。","t":[112,2700]},{"en":"\"What is it that you are looking for?\"","zh":"你在寻找什么？","t":[2700,4500]}]},{"id":"ch21p11","audio":true,"sents":[{"en":"\"I am looking for men,\" said the little prince.","zh":"我在寻找男人，”小王子说。","t":[138,3125]},{"en":"\"What does that mean-- 'tame'?\"","zh":"那‘驯服’是什么意思？","t":[3125,4550]}]},{"id":"ch21p12","audio":true,"sents":[{"en":"\"Men,\" said the fox.","zh":"男人，”狐狸说。","t":[125,2138]},{"en":"\"They have guns, and they hunt.","zh":"他们有枪，他们会打猎。","t":[2138,4450]},{"en":"It is very disturbing.","zh":"这很令人不安。","t":[4450,6262]},{"en":"They also raise chickens.","zh":"他们还养鸡。","t":[6262,8300]},{"en":"These are their only interests.","zh":"这些就是他们的唯一兴趣。","t":[8300,10462]},{"en":"Are you looking for chickens?\"","zh":"你在找鸡吗？","t":[10462,11987]}]},{"id":"ch21p13","audio":true,"sents":[{"en":"\"No,\" said the little prince.","zh":"不，”小王子说。","t":[125,2450]},{"en":"\"I am looking for friends.","zh":"我在寻找朋友。","t":[2450,4288]},{"en":"What does that mean-- 'tame'?\"","zh":"那是什么意思——‘驯服’？","t":[4288,5675]}]},{"id":"ch21p14","audio":true,"sents":[{"en":"\"It is an act too often neglected,\" said the fox.","zh":"这是一项常常被忽视的行为，”狐狸说。","t":[138,3762]},{"en":"It means to establish ties.\"","zh":"那意味着建立联系。","t":[3762,5650]}]},{"id":"ch21p15","audio":true,"sents":[{"en":"\"'To establish ties'?\"","zh":"‘建立联系’？","t":[100,1500]}]},{"id":"ch21p16","audio":true,"sents":[{"en":"\"Just that,\" said the fox.","zh":"正是如此，”狐狸说。","t":[100,2388]},{"en":"\"To me, you are still nothing more than a little boy who is just like a hundred thousand other little boys.","zh":"对我来说，你仍然只是一个像成千上万个其他小男孩一样的小男孩。","t":[2388,8338]},{"en":"And I have no need of you.","zh":"而我并不需要你。","t":[8338,10162]},{"en":"And you, on your part, have no need of me.","zh":"而你，从你的角度来说，也不需要我。","t":[10162,13338]},{"en":"To you, I am nothing more than a fox like a hundred thousand other foxes.","zh":"对你来说，我不过是一只像成千上万个其他狐狸一样的狐狸。","t":[13338,18088]},{"en":"But if you tame me, then we shall need each other.","zh":"但如果你驯服了我，那么我们就需要彼此了。","t":[18088,21125]},{"en":"To me, you will be unique in all the world.","zh":"对我来说，你将是世界上独一无二的。","t":[21125,24075]},{"en":"To you, I shall be unique in all the world...\"","zh":"对你来说，我将是世界上独一无二的……","t":[24075,26775]}]},{"id":"ch21p17","audio":true,"sents":[{"en":"\"I am beginning to understand,\" said the little prince.","zh":"我开始明白了，”小王子说。","t":[138,3538]},{"en":"\"There is a flower...","zh":"有一朵花……","t":[3538,5075]},{"en":"I think that she has tamed me...\"","zh":"我想，她已经驯服了我……","t":[5075,6763]}]},{"id":"ch21p18","audio":true,"sents":[{"en":"\"It is possible,\" said the fox.","zh":"这是可能的，”狐狸说。","t":[100,2600]},{"en":"\"On the Earth one sees all sorts of things.\"","zh":"在地球上，人们可以看到各种各样的东西。","t":[2600,5050]}]},{"id":"ch21p19","audio":true,"sents":[{"en":"\"Oh, but this is not on the Earth!\" said the little prince.","zh":"哦，但这里不是在地球上！”小王子说。","t":[112,3475]}]},{"id":"ch21p20","audio":true,"sents":[{"en":"The fox seemed perplexed, and very curious.","zh":"狐狸看起来很困惑，也很好奇。","t":[138,3063]}]},{"id":"ch21p21","audio":true,"sents":[{"en":"\"On another planet?\"","zh":"在另一个星球上？","t":[138,1350]}]},{"id":"ch21p22","audio":true,"sents":[{"en":"\"Yes.\"","zh":"是的。","t":[100,600]}]},{"id":"ch21p23","audio":true,"sents":[{"en":"\"Are there hunters on this planet?\"","zh":"这个星球上有猎人吗？","t":[112,2038]}]},{"id":"ch21p24","audio":true,"sents":[{"en":"\"No.\"","zh":"没有。","t":[100,600]}]},{"id":"ch21p25","audio":true,"sents":[{"en":"\"Ah, that is interesting!","zh":"啊，这很有趣！","t":[138,2050]},{"en":"Are there chickens?\"","zh":"这里有鸡吗？","t":[2050,3137]}]},{"id":"ch21p26","audio":true,"sents":[{"en":"\"No.\"","zh":"没有。","t":[100,600]}]},{"id":"ch21p27","audio":true,"sents":[{"en":"\"Nothing is perfect,\" sighed the fox.","zh":"没有什么完美无缺的，”狐狸叹了口气。","t":[125,2550]}]},{"id":"ch21p28","audio":true,"sents":[{"en":"But he came back to his idea.","zh":"但他又回到了他的想法。","t":[100,1888]}]},{"id":"ch21p29","audio":true,"sents":[{"en":"\"My life is very monotonous,\" the fox said.","zh":"我的生活非常单调，”狐狸说。","t":[138,3325]},{"en":"\"I hunt chickens; men hunt me.","zh":"我猎杀鸡；人们猎杀我。","t":[3325,5888]},{"en":"All the chickens are just alike, and all the men are just alike.","zh":"所有的鸡都长得一样，所有的人也都长得一样。","t":[5888,9800]},{"en":"And, in consequence, I am a little bored.","zh":"因此，我有点无聊。","t":[9800,13088]},{"en":"But if you tame me, it will be as if the sun came to shine on my life.","zh":"但是，如果你驯服了我，那就像阳光照进了我的生命。","t":[13088,17550]},{"en":"I shall know the sound of a step that will be different from all the others.","zh":"我会知道一个与众不同的脚步声。","t":[17550,21650]},{"en":"Other steps send me hurrying back underneath the ground.","zh":"其他的脚步声会让我急忙回到地下。","t":[21650,25250]},{"en":"Yours will call me, like music, out of my burrow.","zh":"你的脚步声会像音乐一样，把我从洞穴里叫出来。","t":[25250,28800]},{"en":"And then look: you see the grain-fields down yonder?","zh":"然后你看：你看到那边那些麦田了吗？","t":[28800,32250]},{"en":"I do not eat bread.","zh":"我不吃面包。","t":[32250,33912]},{"en":"Wheat is of no use to me.","zh":"小麦对我没有用。","t":[33912,35812]},{"en":"The wheat fields have nothing to say to me.","zh":"麦田对我没有什么可说的。","t":[35812,38450]},{"en":"And that is sad.","zh":"这很悲哀。","t":[38450,39850]},{"en":"But you have hair that is the colour of gold.","zh":"但你头发的颜色是金色的。","t":[39850,42638]},{"en":"Think how wonderful that will be when you have tamed me!","zh":"当你驯服了我，那将是多么美妙啊！","t":[42638,45925]},{"en":"The grain, which is also golden, will bring me back the thought of you.","zh":"那金黄的麦粒，也会让我想起你。","t":[45925,50262]},{"en":"And I shall love to listen to the wind in the wheat...\"","zh":"我愿意倾听麦田里的风声……","t":[50262,52974]}]},{"id":"ch21p30","audio":true,"sents":[{"en":"The fox gazed at the little prince, for a long time.","zh":"狐狸久久地凝视着小王子。","t":[138,3263]}]},{"id":"ch21p31","audio":true,"sents":[{"en":"\"Please-- tame me!\" he said.","zh":"请——驯服我吧！他说。","t":[100,1674]}]},{"id":"ch21p32","audio":true,"sents":[{"en":"\"I want to, very much,\" the little prince replied.","zh":"“我非常想这么做，”小王子回答道。","t":[138,3762]},{"en":"\"But I have not much time.","zh":"但我没有太多时间。","t":[3762,5725]},{"en":"I have friends to discover, and a great many things to understand.\"","zh":"我有朋友要去发现，有许多事情要去理解。","t":[5725,9538]}]},{"id":"ch21p33","audio":true,"sents":[{"en":"\"One only understands the things that one tames,\" said the fox.","zh":"人只能理解他们驯服的东西，”狐狸说。","t":[138,4288]},{"en":"\"Men have no more time to understand anything.","zh":"人们再也没有时间去理解任何东西了。","t":[4288,7312]},{"en":"They buy things all ready made at the shops.","zh":"他们在商店里买现成的东西。","t":[7312,10112]},{"en":"But there is no shop anywhere where one can buy friendship, and so men have no friends any more.","zh":"但是，在任何地方都没有商店可以买到友谊，所以人们再也没有朋友了。","t":[10112,15612]},{"en":"If you want a friend, tame me...\"","zh":"如果你想有一个朋友，驯服我吧……","t":[15612,17513]}]},{"id":"ch21p34","audio":true,"sents":[{"en":"\"What must I do, to tame you?\" asked the little prince.","zh":"我该怎么做才能驯服你呢？”小王子问。","t":[125,3613]}]},{"id":"ch21p35","audio":true,"sents":[{"en":"\"You must be very patient,\" replied the fox.","zh":"你必须非常耐心，”狐狸回答说。","t":[138,3400]},{"en":"\"First you will sit down at a little distance from me-- like that-- in the grass.","zh":"首先，你将坐在我稍远一点的地方——就像这样——在草地上。","t":[3400,7912]},{"en":"I shall look at you out of the corner of my eye, and you will say nothing.","zh":"我会用眼角的余光看着你，而你什么也不要说。","t":[7912,12162]},{"en":"Words are the source of misunderstandings.","zh":"言语是误解的源头。","t":[12162,15088]},{"en":"But you will sit a little closer to me, every day...\"","zh":"但你每天都要坐得离我近一点……","t":[15088,18087]}]},{"id":"ch21p36","audio":true,"sents":[{"en":"The next day the little prince came back.","zh":"第二天，小王子回来了。","t":[138,2450]}]},{"id":"ch21p37","audio":true,"sents":[{"en":"\"It would have been better to come back at the same hour,\" said the fox.","zh":"“最好是同一时间回来，”狐狸说。","t":[138,4075]},{"en":"\"If, for example, you come at four o'clock in the afternoon, then at three o'clock I shall begin to be happy.","zh":"如果，比如，你下午四点钟来，那么从三点钟起，我就开始快乐了。","t":[4075,10400]},{"en":"I shall feel happier and happier as the hour advances.","zh":"随着时间的推移，我会越来越快乐。","t":[10400,14112]},{"en":"At four o'clock, I shall already be worrying and jumping about.","zh":"四点钟，我就会开始担心和焦急不安。","t":[14112,18125]},{"en":"I shall show you how happy I am!","zh":"我将向你展示我是多么快乐！","t":[18125,20412]},{"en":"But if you come at just any time, I shall never know at what hour my heart is to be ready to greet you...","zh":"但如果你随时来，我就永远不知道何时我的心会准备好迎接你……","t":[20412,26175]},{"en":"One must observe the proper rites...\"","zh":"必须遵守适当的仪式……","t":[26175,28350]}]},{"id":"ch21p38","audio":true,"sents":[{"en":"\"What is a rite?\" asked the little prince.","zh":"“什么是仪式？”小王子问道。","t":[138,2750]}]},{"id":"ch21p39","audio":true,"sents":[{"en":"\"Those also are actions too often neglected,\" said the fox.","zh":"这些也是常常被忽视的行为，”狐狸说。","t":[125,4388]},{"en":"\"They are what make one day different from other days, one hour from other hours.","zh":"它们使得一天与其它日子不同，一小时与其它小时不同。","t":[4388,9125]},{"en":"There is a rite, for example, among my hunters.","zh":"例如，在我的猎人中有一个仪式。","t":[9125,12688]},{"en":"Every Thursday they dance with the village girls.","zh":"每个星期四，他们都和村里的女孩们跳舞。","t":[12688,15762]},{"en":"So Thursday is a wonderful day for me!","zh":"所以，星期四对我来说是个美好的日子！","t":[15762,18412]},{"en":"I can take a walk as far as the vineyards.","zh":"我可以一直走到葡萄园。","t":[18412,21175]},{"en":"But if the hunters danced at just any time, every day would be like every other day, and I should never have any vacation at all.\"","zh":"但如果猎人随时跳舞，每一天就会和其它日子一样，我就永远不会有假期了。","t":[21175,27962]}]},{"id":"ch21p40","audio":true,"sents":[{"en":"So the little prince tamed the fox.","zh":"于是，小王子驯服了狐狸。","t":[112,2662]},{"en":"And when the hour of his departure drew near--","zh":"当小王子离开的时间临近时--","t":[2662,5100]}]},{"id":"ch21p41","audio":true,"sents":[{"en":"\"Ah,\" said the fox, \"I shall cry.\"","zh":"啊，”狐狸说，“我会哭的。","t":[125,2525]}]},{"id":"ch21p42","audio":true,"sents":[{"en":"\"It is your own fault,\" said the little prince.","zh":"这是你自己的错，”小王子说。","t":[138,3150]},{"en":"\"I never wished you any sort of harm; but you wanted me to tame you...\"","zh":"我从未希望给你带来任何伤害；但你却希望我驯服你...","t":[3150,7000]}]},{"id":"ch21p43","audio":true,"sents":[{"en":"\"Yes, that is so,\" said the fox.","zh":"是的，是这样的，”狐狸说。","t":[112,2574]}]},{"id":"ch21p44","audio":true,"sents":[{"en":"\"But now you are going to cry!\" said the little prince.","zh":"但现在你将要哭了！”小王子说。","t":[100,2938]}]},{"id":"ch21p45","audio":true,"sents":[{"en":"\"Yes, that is so,\" said the fox.","zh":"是的，是这样的，”狐狸说。","t":[112,2574]}]},{"id":"ch21p46","audio":true,"sents":[{"en":"\"Then it has done you no good at all!\"","zh":"那么，它对你一点好处都没有！","t":[125,1988]}]},{"id":"ch21p47","audio":true,"sents":[{"en":"\"It has done me good,\" said the fox, \"because of the colour of the wheat fields.\" And then he added:","zh":"它对我有好处，”狐狸说，“因为麦田的颜色。”然后他又补充道：","t":[138,5926]}]},{"id":"ch21p48","audio":true,"sents":[{"en":"\"Go and look again at the roses.","zh":"去再看看那些玫瑰。","t":[100,2338]},{"en":"You will understand now that yours is unique in all the world.","zh":"你现在会明白，你的玫瑰在世界上是独一无二的。","t":[2338,6312]},{"en":"Then come back to say goodbye to me, and I will make you a present of a secret.\"","zh":"然后回来向我告别，我会送你一个秘密作为礼物。","t":[6312,10612]}]},{"id":"ch21p49","audio":true,"sents":[{"en":"The little prince went away, to look again at the roses.","zh":"小王子离开了，再次去看那些玫瑰。","t":[138,3400]}]},{"id":"ch21p50","audio":true,"sents":[{"en":"\"You are not at all like my rose,\" he said.","zh":"你说，‘你一点也不像我那朵玫瑰。’","t":[138,3000]},{"en":"\"As yet you are nothing.","zh":"‘你目前什么都不是。’","t":[3000,4712]},{"en":"No one has tamed you, and you have tamed no one.","zh":"‘没有人驯服过你，你也未曾驯服过任何人。’","t":[4712,8075]},{"en":"You are like my fox when I first knew him.","zh":"‘你就像我第一次认识的那只狐狸。’","t":[8075,10912]},{"en":"He was only a fox like a hundred thousand other foxes.","zh":"‘他只是像成千上万只狐狸一样。’","t":[10912,14500]},{"en":"But I have made him my friend, and now he is unique in all the world.\"","zh":"‘但是我已经让他成为我的朋友，现在他在世界上独一无二。’","t":[14500,18338]}]},{"id":"ch21p51","audio":true,"sents":[{"en":"And the roses were very much embarrassed.","zh":"玫瑰们感到非常尴尬。","t":[138,2525]}]},{"id":"ch21p52","audio":true,"sents":[{"en":"\"You are beautiful, but you are empty,\" he went on.","zh":"‘你很美，但你很空虚，’他继续说。","t":[138,3712]},{"en":"\"One could not die for you.","zh":"‘没有人会为你而死。’","t":[3712,5562]},{"en":"To be sure, an ordinary passer-by would think that my rose looked just like you-- the rose that belongs to me.","zh":"当然，一个普通的过路人会认为我的玫瑰就像你一样——那属于我的玫瑰。","t":[5562,11650]},{"en":"But in herself alone she is more important than all the hundreds of you other roses: because it is she that I have watered; because it is she that I have put under the glass globe; because it is she that I have sheltered behind the screen; because it is for her that I have killed the caterpillars (except the two or three that we saved to become butterflies); because it is she that I have listened to, when she grumbled, or boasted, or even sometimes when she said nothing.","zh":"但仅就她本身而言，她比你们所有成百上千的玫瑰都重要：因为是我给她浇水；因为是我把她放在玻璃球罩下；因为是我给她遮风挡雨；因为是我为她杀死了毛毛虫（除了我们留下变成蝴蝶的那两三只）；因为是我听她抱怨，听她炫耀，甚至有时听她什么也不说。","t":[11650,36138]},{"en":"Because she is my rose.","zh":"因为她是我的玫瑰。","t":[36138,37638]}]},{"id":"ch21p53","audio":true,"sents":[{"en":"And he went back to meet the fox.","zh":"然后他回到了狐狸那里。","t":[138,2026]}]},{"id":"ch21p54","audio":true,"sents":[{"en":"\"Goodbye,\" he said.","zh":"他说：‘再见。’","t":[100,1574]}]},{"id":"ch21p55","audio":true,"sents":[{"en":"\"Goodbye,\" said the fox.","zh":"狐狸说：‘再见。’","t":[100,2288]},{"en":"\"And now here is my secret, a very simple secret: It is only with the heart that one can see rightly; what is essential is invisible to the eye.\"","zh":"‘现在，这是我的秘密，一个非常简单的秘密：只有用心才能看得清楚；真正重要的东西肉眼是看不见的。’","t":[2288,10512]}]},{"id":"ch21p56","audio":true,"sents":[{"en":"\"What is essential is invisible to the eye,\" the little prince repeated, so that he would be sure to remember.","zh":"‘真正重要的东西肉眼是看不见的，’小王子重复道，以便他能够牢记。","t":[125,6075]}]},{"id":"ch21p57","audio":true,"sents":[{"en":"\"It is the time you have wasted for your rose that makes your rose so important.\"","zh":"‘是你为你的玫瑰浪费的时间，使你的玫瑰变得如此重要。’","t":[138,4374]}]},{"id":"ch21p58","audio":true,"sents":[{"en":"\"It is the time I have wasted for my rose--\" said the little prince, so that he would be sure to remember.","zh":"‘是我为我的玫瑰浪费的时间——’小王子说，以便他能够牢记。","t":[138,5413]}]},{"id":"ch21p59","audio":true,"sents":[{"en":"\"Men have forgotten this truth,\" said the fox.","zh":"人们已经忘记了这一真理，”狐狸说。","t":[112,3275]},{"en":"\"But you must not forget it.","zh":"但你绝不能忘记。","t":[3275,5362]},{"en":"You become responsible, forever, for what you have tamed.","zh":"你一旦驯服了什么，就要永远对它负责。","t":[5362,9350]},{"en":"You are responsible for your rose...\"","zh":"你对你的玫瑰负责……","t":[9350,11387]}]},{"id":"ch21p60","audio":true,"sents":[{"en":"\"I am responsible for my rose,\" the little prince repeated, so that he would be sure to remember.","zh":"小王子重复道，以便他能够确信记住，“我对我的玫瑰负责……”","t":[138,5475]}]}]},{"id":"ch22","title_en":"Chapter XXII","title_zh":"第 22 章","paras":[{"id":"ch22p00","audio":true,"sents":[{"en":"\"Good morning,\" said the little prince.","zh":"早上好，”小王子说。","t":[112,2312]}]},{"id":"ch22p01","audio":true,"sents":[{"en":"\"Good morning,\" said the railway switchman.","zh":"早上好，”铁路扳道工说。","t":[100,2513]}]},{"id":"ch22p02","audio":true,"sents":[{"en":"\"What do you do here?\" the little prince asked.","zh":"你在这里做什么？”小王子问道。","t":[125,2737]}]},{"id":"ch22p03","audio":true,"sents":[{"en":"\"I sort out travellers, in bundles of a thousand,\" said the switchman.","zh":"我整理旅客，一捆一千个，”扳道工说。","t":[138,4588]},{"en":"\"I send off the trains that carry them; now to the right, now to the left.\"","zh":"我发送载着他们的火车；现在向右，现在向左。","t":[4588,8888]}]},{"id":"ch22p04","audio":true,"sents":[{"en":"And a brilliantly lighted express train shook the switchman's cabin as it rushed by with a roar like thunder.","zh":"一列灯火辉煌的快车像雷鸣般呼啸而过，震动了扳道工的小屋。","t":[138,5962]}]},{"id":"ch22p05","audio":true,"sents":[{"en":"\"They are in a great hurry,\" said the little prince.","zh":"他们都很匆忙，”小王子说。","t":[125,3212]},{"en":"\"What are they looking for?\"","zh":"他们在寻找什么？","t":[3212,4563]}]},{"id":"ch22p06","audio":true,"sents":[{"en":"\"Not even the locomotive engineer knows that,\" said the switchman.","zh":"甚至连火车司机也不知道，”扳道工说。","t":[125,3788]}]},{"id":"ch22p07","audio":true,"sents":[{"en":"And a second brilliantly lighted express thundered by, in the opposite direction.","zh":"另一列灯火辉煌的快车从相反的方向轰鸣而过。","t":[125,4813]}]},{"id":"ch22p08","audio":true,"sents":[{"en":"\"Are they coming back already?\" demanded the little prince.","zh":"他们已经回来了吗？”小王子问道。","t":[138,3388]}]},{"id":"ch22p09","audio":true,"sents":[{"en":"\"These are not the same ones,\" said the switchman.","zh":"这不是同一列，”扳道工说。","t":[125,3100]},{"en":"\"It is an exchange.\"","zh":"这是一次换乘。","t":[3100,4325]}]},{"id":"ch22p10","audio":true,"sents":[{"en":"\"Were they not satisfied where they were?\" asked the little prince.","zh":"他们不是在原来的地方就满意了吗？”小王子问。","t":[138,3776]}]},{"id":"ch22p11","audio":true,"sents":[{"en":"\"No one is ever satisfied where he is,\" said the switchman.","zh":"没有人会在原地感到满足，”扳道工说。","t":[125,3500]}]},{"id":"ch22p12","audio":true,"sents":[{"en":"And they heard the roaring thunder of a third brilliantly lighted express.","zh":"他们听到了一辆第三列灯火辉煌的快车的轰鸣声。","t":[138,4124]}]},{"id":"ch22p13","audio":true,"sents":[{"en":"\"Are they pursuing the first travellers?\" demanded the little prince.","zh":"‘他们在追赶第一批旅行者吗？’小王子问道。","t":[138,3913]}]},{"id":"ch22p14","audio":true,"sents":[{"en":"\"They are pursuing nothing at all,\" said the switchman.","zh":"‘他们什么也没追赶，’扳道工说。","t":[138,3375]},{"en":"\"They are asleep in there, or if they are not asleep they are yawning.","zh":"‘他们在里面睡觉，或者如果他们没睡觉，他们就会打哈欠。","t":[3375,7125]},{"en":"Only the children are flattening their noses against the windowpanes.\"","zh":"只有孩子们会把他们的鼻子贴在窗户上。’","t":[7125,10963]}]},{"id":"ch22p15","audio":true,"sents":[{"en":"\"Only the children know what they are looking for,\" said the little prince.","zh":"‘只有孩子们知道他们在寻找什么，’小王子说。","t":[112,4200]},{"en":"\"They waste their time over a rag doll and it becomes very important to them; and if anybody takes it away from them, they cry...\"","zh":"‘他们把时间浪费在一个布娃娃上，它对他们来说变得非常重要；如果有人把它从他们那里拿走，他们会哭……’","t":[4200,11200]}]},{"id":"ch22p16","audio":true,"sents":[{"en":"\"They are lucky,\" the switchman said.","zh":"‘他们很幸运，’扳道工说。","t":[138,2213]}]}]},{"id":"ch23","title_en":"Chapter XXIII","title_zh":"第 23 章","paras":[{"id":"ch23p00","audio":true,"sents":[{"en":"\"Good morning,\" said the little prince.","zh":"‘早上好，’小王子说。","t":[112,2312]}]},{"id":"ch23p01","audio":true,"sents":[{"en":"\"Good morning,\" said the merchant.","zh":"‘早上好，’商人说。","t":[100,2500]},{"en":"This was a merchant who sold pills that had been invented to quench thirst.","zh":"这是一个商人，他卖的是一种用来解渴的药丸。","t":[2500,6962]},{"en":"You need only swallow one pill a week, and you would feel no need of anything to drink.","zh":"你只需要每周吞下一颗药丸，你就不会再感到需要喝任何东西。","t":[6962,11476]}]},{"id":"ch23p02","audio":true,"sents":[{"en":"\"Why are you selling those?\" asked the little prince.","zh":"“你为什么要卖这些？”小王子问道。","t":[125,3063]}]},{"id":"ch23p03","audio":true,"sents":[{"en":"\"Because they save a tremendous amount of time,\" said the merchant.","zh":"“因为它们能节省大量的时间，”商人说。","t":[100,4125]},{"en":"\"Computations have been made by experts.","zh":"“专家们已经做了计算。","t":[4125,7238]},{"en":"With these pills, you save fifty-three minutes in every week.\"","zh":"有了这些药丸，你每周可以节省五十三分钟。","t":[7238,10913]}]},{"id":"ch23p04","audio":true,"sents":[{"en":"\"And what do I do with those fifty-three minutes?\"","zh":"“那我用这五十三分钟做什么？”","t":[112,2712]}]},{"id":"ch23p05","audio":true,"sents":[{"en":"\"Anything you like...\"","zh":"你想做什么就做什么……","t":[100,1300]}]},{"id":"ch23p06","audio":true,"sents":[{"en":"\"As for me,\" said the little prince to himself, \"if I had fifty-three minutes to spend as I liked, I should walk at my leisure toward a spring of fresh water.\"","zh":"“至于我，”小王子自言自语道，“如果我有五十三分钟可以随意支配，我会悠闲地走向一个清泉。","t":[138,8512]}]}]},{"id":"ch24","title_en":"Chapter XXIV","title_zh":"第 24 章","paras":[{"id":"ch24p00","audio":true,"sents":[{"en":"It was now the eighth day since I had had my accident in the desert, and I had listened to the story of the merchant as I was drinking the last drop of my water supply.","zh":"自从我在沙漠里出事故以来，现在已经是第八天了，我一边喝着我最后的水，一边听着商人的故事。","t":[138,8713]}]},{"id":"ch24p01","audio":true,"sents":[{"en":"\"Ah,\" I said to the little prince, \"these memories of yours are very charming; but I have not yet succeeded in repairing my plane; I have nothing more to drink; and I, too, should be very happy if I could walk at my leisure toward a spring of fresh water!\"","zh":"“啊，”我对小王子说，“你的这些回忆非常迷人；但我还没有修好我的飞机；我也没有什么可以再喝了；如果我能悠闲地走向一个清泉，我也会非常快乐的！”","t":[125,13663]}]},{"id":"ch24p02","audio":true,"sents":[{"en":"\"My friend the fox--\" the little prince said to me.","zh":"我的朋友，狐狸——小王子对我说。","t":[138,2662]}]},{"id":"ch24p03","audio":true,"sents":[{"en":"\"My dear little man, this is no longer a matter that has anything to do with the fox!\"","zh":"我亲爱的孩子，这已经不再与狐狸有关的事情了！","t":[112,4825]}]},{"id":"ch24p04","audio":true,"sents":[{"en":"\"Why not?\"","zh":"为什么不呢？","t":[112,850]}]},{"id":"ch24p05","audio":true,"sents":[{"en":"\"Because I am about to die of thirst...\"","zh":"因为我快要渴死了……","t":[100,2237]}]},{"id":"ch24p06","audio":true,"sents":[{"en":"He did not follow my reasoning, and he answered me:","zh":"他没有理解我的推理，他回答我说：","t":[138,2950]}]},{"id":"ch24p07","audio":true,"sents":[{"en":"\"It is a good thing to have had a friend, even if one is about to die.","zh":"拥有过朋友是件好事，即使即将离世。","t":[138,4238]},{"en":"I, for instance, am very glad to have had a fox as a friend...\"","zh":"我，比如，很高兴能有一个狐狸作为朋友……","t":[4238,8175]}]},{"id":"ch24p08","audio":true,"sents":[{"en":"\"He has no way of guessing the danger,\" I said to myself.","zh":"他无法预知危险，我心想。","t":[138,3850]},{"en":"\"He has never been either hungry or thirsty.","zh":"他从未感到过饥饿或口渴。","t":[3850,6650]},{"en":"A little sunshine is all he needs...\"","zh":"他只需要一点阳光...","t":[6650,8875]}]},{"id":"ch24p09","audio":true,"sents":[{"en":"But he looked at me steadily, and replied to my thought:","zh":"但他稳稳地看着我，对我的想法做出了回应：","t":[100,3250]}]},{"id":"ch24p10","audio":true,"sents":[{"en":"\"I am thirsty, too.","zh":"我也渴了。","t":[100,2138]},{"en":"Let us look for a well...\"","zh":"让我们去找一口井...","t":[2138,3637]}]},{"id":"ch24p11","audio":true,"sents":[{"en":"I made a gesture of weariness.","zh":"我做出了一副疲惫的姿态。","t":[138,2462]},{"en":"It is absurd to look for a well, at random, in the immensity of the desert.","zh":"在沙漠的浩瀚中随意找一口井是荒谬的。","t":[2462,7162]},{"en":"But nevertheless we started walking.","zh":"但不管怎样，我们开始走路了。","t":[7162,9350]}]},{"id":"ch24p12","audio":true,"sents":[{"en":"When we had trudged along for several hours, in silence, the darkness fell, and the stars began to come out.","zh":"当我们默默地走了几个小时后，黑暗降临，星星开始出现。","t":[138,6838]},{"en":"Thirst had made me a little feverish, and I looked at them as if I were in a dream.","zh":"口渴让我有些发烧，我看着它们，仿佛置身梦境。","t":[6838,11675]},{"en":"The little prince's last words came reeling back into my memory:","zh":"小王子的最后一句话在我脑海中回荡：","t":[11675,15325]}]},{"id":"ch24p13","audio":true,"sents":[{"en":"\"Then you are thirsty, too?\" I demanded.","zh":"那么你也渴了吗？我问道。","t":[125,3250]}]},{"id":"ch24p14","audio":true,"sents":[{"en":"But he did not reply to my question.","zh":"但他没有回答我的问题。","t":[100,2650]},{"en":"He merely said to me:","zh":"他只是对我说：","t":[2650,3900]}]},{"id":"ch24p15","audio":true,"sents":[{"en":"\"Water may also be good for the heart...\"","zh":"水也许对心脏也有好处...","t":[125,2412]}]},{"id":"ch24p16","audio":true,"sents":[{"en":"I did not understand this answer, but I said nothing.","zh":"我没有理解这个答案，但我没有说什么。","t":[138,3700]},{"en":"I knew very well that it was impossible to cross-examine him.","zh":"我非常清楚，不可能对他进行交叉审问。","t":[3700,7126]}]},{"id":"ch24p17","audio":true,"sents":[{"en":"He was tired.","zh":"他累了。","t":[138,1512]},{"en":"He sat down.","zh":"他坐了下来。","t":[1512,2888]},{"en":"I sat down beside him.","zh":"我坐在他旁边。","t":[2888,4850]},{"en":"And, after a little silence, he spoke again: \"The stars are beautiful, because of a flower that cannot be seen.\"","zh":"星星之所以美丽，是因为有一朵看不见的花。","t":[4850,11424]}]},{"id":"ch24p18","audio":true,"sents":[{"en":"I replied, \"Yes, that is so.\" And, without saying anything more, I looked across the ridges of sand that were stretched out before us in the moonlight.","zh":"我回答说：“是的，确实如此。”然后，没有再说任何话，我望向月光下在我们面前延伸的沙丘。","t":[138,9300]}]},{"id":"ch24p19","audio":true,"sents":[{"en":"\"The desert is beautiful,\" the little prince added.","zh":"小王子接着说：“沙漠很美。”","t":[138,3112]}]},{"id":"ch24p20","audio":true,"sents":[{"en":"And that was true.","zh":"这是真的。","t":[112,1625]},{"en":"I have always loved the desert.","zh":"我一直都喜欢沙漠。","t":[1625,3862]},{"en":"One sits down on a desert sand dune, sees nothing, hears nothing.","zh":"一个人坐在沙漠的沙丘上，什么也看不见，什么也听不见。","t":[3862,8475]},{"en":"Yet through the silence something throbs, and gleams...","zh":"然而，在这片寂静中，有什么在跳动，有什么在闪烁……","t":[8475,11712]}]},{"id":"ch24p21","audio":true,"sents":[{"en":"\"What makes the desert beautiful,\" said the little prince, \"is that somewhere it hides a well...\"","zh":"‘是什么让沙漠变得美丽呢，’小王子说，‘是因为它在某个地方隐藏了一口井……’","t":[125,5200]}]},{"id":"ch24p22","audio":true,"sents":[{"en":"I was astonished by a sudden understanding of that mysterious radiation of the sands.","zh":"我突然对沙子的那种神秘辐射有了领悟，感到惊讶。","t":[138,5562]},{"en":"When I was a little boy I lived in an old house, and legend told us that a treasure was buried there.","zh":"当我还是个小男孩的时候，我住在一座老房子里，传说那里埋藏着一笔宝藏。","t":[5562,11375]},{"en":"To be sure, no one had ever known how to find it; perhaps no one had ever even looked for it.","zh":"当然，没有人知道如何找到它；也许从来没有人甚至寻找过它。","t":[11375,17088]},{"en":"But it cast an enchantment over that house.","zh":"但它给那所房子施了魔法。","t":[17088,20050]},{"en":"My home was hiding a secret in the depths of its heart...","zh":"我的家在它的内心深处隐藏着一个秘密……","t":[20050,23362]}]},{"id":"ch24p23","audio":true,"sents":[{"en":"\"Yes,\" I said to the little prince.","zh":"是的，”我对小王子说。","t":[138,2775]},{"en":"\"The house, the stars, the desert-- what gives them their beauty is something that is invisible!\"","zh":"‘房子、星星、沙漠——赋予它们美丽的东西是看不见的！’","t":[2775,8013]}]},{"id":"ch24p24","audio":true,"sents":[{"en":"\"I am glad,\" he said, \"that you agree with my fox.\"","zh":"‘我很高兴，’他说，‘你同意我的狐狸的看法。’","t":[138,3387]}]},{"id":"ch24p25","audio":true,"sents":[{"en":"As the little prince dropped off to sleep, I took him in my arms and set out walking once more.","zh":"当小王子入睡时，我把他抱在怀里，再次出发散步。","t":[138,5700]},{"en":"I felt deeply moved, and stirred.","zh":"我感到深深的感动，内心被触动。","t":[5700,8388]},{"en":"It seemed to me that I was carrying a very fragile treasure.","zh":"我觉得我正在携带一件非常脆弱的宝藏。","t":[8388,12100]},{"en":"It seemed to me, even, that there was nothing more fragile on all Earth.","zh":"甚至在我看来，在地球上没有比这更脆弱的东西了。","t":[12100,16600]},{"en":"In the moonlight I looked at his pale forehead, his closed eyes, his locks of hair that trembled in the wind, and I said to myself: \"What I see here is nothing but a shell.","zh":"在月光下，我看着他那苍白的额头、紧闭的眼睛、随风颤动的头发，对自己说：‘我看到的不过是一个空壳。’","t":[16600,26550]},{"en":"What is most important is invisible...\"","zh":"最重要的东西是看不见的...","t":[26550,28950]}]},{"id":"ch24p26","audio":true,"sents":[{"en":"As his lips opened slightly with the suspicious of a half-smile, I said to myself, again: \"What moves me so deeply, about this little prince who is sleeping here, is his loyalty to a flower-- the image of a rose that shines through his whole being like the flame of a lamp, even when he is asleep...\" And I felt him to be more fragile still.","zh":"当他半带怀疑地微微张开嘴唇，带着一丝微笑时，我对自己又说了一遍：'让我如此深受触动的是这个在这里睡觉的小王子对一朵花的忠诚——那朵玫瑰的形象就像一盏灯的火焰，贯穿他的整个存在，即使在他睡着的时候……'我觉得他更加脆弱了。","t":[100,18888]},{"en":"I felt the need of protecting him, as if he himself were a flame that might be extinguished by a little puff of wind...","zh":"我感到需要保护他，就像他自己是一团火焰，可能被一阵微风吹灭……","t":[18888,25187]}]},{"id":"ch24p27","audio":true,"sents":[{"en":"And, as I walked on so, I found the well, at daybreak.","zh":"就这样走着走着，我在黎明时分找到了那口井。","t":[112,4026]}]}]},{"id":"ch25","title_en":"Chapter XXV","title_zh":"第 25 章","paras":[{"id":"ch25p00","audio":true,"sents":[{"en":"\"Men,\" said the little prince, \"set out on their way in express trains, but they do not know what they are looking for.","zh":"人们啊，”小王子说，“他们乘坐快车出发，却不知道他们在寻找什么。","t":[125,6688]},{"en":"Then they rush about, and get excited, and turn round and round...\"","zh":"然后他们四处奔忙，兴奋起来，团团转……","t":[6688,10712]}]},{"id":"ch25p01","audio":true,"sents":[{"en":"And he added: \"It is not worth the trouble...\"","zh":"他还说：'这不值得麻烦……'","t":[112,2625]}]},{"id":"ch25p02","audio":true,"sents":[{"en":"The well that we had come to was not like the wells of the Sahara.","zh":"我们来到的这口井和撒哈拉沙漠的井不一样。","t":[125,4038]},{"en":"The wells of the Sahara are mere holes dug in the sand.","zh":"撒哈拉沙漠的井只是挖在沙子里的洞。","t":[4038,7525]},{"en":"This one was like a well in a village.","zh":"这口井就像村庄里的井。","t":[7525,10012]},{"en":"But there was no village here, and I thought I must be dreaming...","zh":"但这里没有村庄，我以为我是在做梦……","t":[10012,13400]}]},{"id":"ch25p03","audio":true,"sents":[{"en":"\"It is strange,\" I said to the little prince.","zh":"“这很奇怪，”我对小王子说。","t":[138,3075]},{"en":"\"Everything is ready for use: the pulley, the bucket, the rope...\"","zh":"一切准备就绪：滑轮、水桶、绳索……","t":[3075,7175]}]},{"id":"ch25p04","audio":true,"sents":[{"en":"He laughed, touched the rope, and set the pulley to working.","zh":"他笑了，碰了碰绳子，让滑轮开始转动。","t":[138,4138]},{"en":"And the pulley moaned, like an old weathervane, which the wind has long since forgotten.","zh":"滑轮像一根久被遗忘的老风向标一样呻吟着。","t":[4138,8812]}]},{"id":"ch25p05","audio":true,"sents":[{"en":"\"Do you hear?\" said the little prince.","zh":"你听见了吗？小王子说。","t":[138,2812]},{"en":"\"We have wakened the well, and it is singing...\"","zh":"我们唤醒了井水，它正在歌唱……","t":[2812,5326]}]},{"id":"ch25p06","audio":true,"sents":[{"en":"I did not want him to tire himself with the rope.","zh":"我不想让他累着自己去拉绳子。","t":[138,2850]}]},{"id":"ch25p07","audio":true,"sents":[{"en":"\"Leave it to me,\" I said.","zh":"交给我吧，我说。","t":[112,2188]},{"en":"\"It is too heavy for you.\"","zh":"它对你来说太重了。","t":[2188,3724]}]},{"id":"ch25p08","audio":true,"sents":[{"en":"I hoisted the bucket slowly to the edge of the well and set it there-- happy, tired as I was, over my achievement.","zh":"我慢慢地把水桶提到井边，放在那里——尽管我很累，但为我的成就感到高兴。","t":[138,6938]},{"en":"The song of the pulley was still in my ears, and I could see the sunlight shimmer in the still trembling water.","zh":"滑轮的歌声仍在我的耳边回荡，我可以看到阳光在微微颤抖的水中闪烁。","t":[6938,12713]}]},{"id":"ch25p09","audio":true,"sents":[{"en":"\"I am thirsty for this water,\" said the little prince.","zh":"‘我渴望这水，’小王子说。","t":[138,3600]},{"en":"\"Give me some of it to drink...\"","zh":"‘给我一些喝吧……’","t":[3600,5263]}]},{"id":"ch25p10","audio":true,"sents":[{"en":"And I understood what he had been looking for.","zh":"我明白了他在寻找的是什么。","t":[138,2463]}]},{"id":"ch25p11","audio":true,"sents":[{"en":"I raised the bucket to his lips.","zh":"我把水桶举到他的嘴边。","t":[138,2488]},{"en":"He drank, his eyes closed.","zh":"他闭上眼睛喝了。","t":[2488,4838]},{"en":"It was as sweet as some special festival treat.","zh":"它像节日里的特别美食一样甜。","t":[4838,8150]},{"en":"This water was indeed a different thing from ordinary nourishment.","zh":"这水确实与普通滋养不同。","t":[8150,12375]},{"en":"Its sweetness was born of the walk under the stars, the song of the pulley, and the effort of my arms.","zh":"它的甜美源于在星光下行走、滑轮的歌声以及我手臂的努力。","t":[12375,18412]},{"en":"It was good for the heart, like a present.","zh":"这对心灵来说是一种慰藉，就像一份礼物。","t":[18412,21275]},{"en":"When I was a little boy, the lights of the Christmas tree, the music of the Midnight Mass, the tenderness of smiling faces, used to make up, so, the radiance of the gifts I received.","zh":"当我还是个小男孩的时候，圣诞树的灯光、子夜弥撒的音乐、微笑面庞的温柔，曾经组成我收到的礼物的光辉。","t":[21275,31800]}]},{"id":"ch25p12","audio":true,"sents":[{"en":"\"The men where you live,\" said the little prince, \"raise five thousand roses in the same garden-- and they do not find in it what they are looking for.\"","zh":"‘你所在的地方的人们，’小王子说，‘在同一个花园里种植了五千朵玫瑰——但他们却找不到他们所寻找的东西。’","t":[138,7500]}]},{"id":"ch25p13","audio":true,"sents":[{"en":"\"They do not find it,\" I replied.","zh":"‘他们找不到，’我回答。","t":[138,2250]}]},{"id":"ch25p14","audio":true,"sents":[{"en":"\"And yet what they are looking for could be found in one single rose, or in a little water.\"","zh":"‘然而他们所寻找的东西，也许可以在一朵玫瑰中，或者在一小滴水里找到。’","t":[138,5124]}]},{"id":"ch25p15","audio":true,"sents":[{"en":"\"Yes, that is true,\" I said.","zh":"‘是的，这是真的，’我说。","t":[112,2337]}]},{"id":"ch25p16","audio":true,"sents":[{"en":"And the little prince added:","zh":"小王子接着说：","t":[138,1750]}]},{"id":"ch25p17","audio":true,"sents":[{"en":"\"But the eyes are blind.","zh":"‘但是眼睛是盲的。","t":[100,1925]},{"en":"One must look with the heart...\"","zh":"人们必须用心去看……'","t":[1925,3600]}]},{"id":"ch25p18","audio":true,"sents":[{"en":"I had drunk the water.","zh":"我已经喝过那水了。","t":[138,1925]},{"en":"I breathed easily.","zh":"我呼吸得很轻松。","t":[1925,3525]},{"en":"At sunrise the sand is the colour of honey.","zh":"在日出时分，沙子的颜色像蜂蜜。","t":[3525,6400]},{"en":"And that honey colour was making me happy, too.","zh":"而这蜂蜜般的颜色也让我感到快乐。","t":[6400,9675]},{"en":"What brought me, then, this sense of grief?","zh":"那么，是什么带给我这种悲伤的感觉？","t":[9675,12413]}]},{"id":"ch25p19","audio":true,"sents":[{"en":"\"You must keep your promise,\" said the little prince, softly, as he sat down beside me once more.","zh":"“你必须遵守你的承诺，”小王子轻声说道，然后再次坐在我身边。","t":[138,5863]}]},{"id":"ch25p20","audio":true,"sents":[{"en":"\"What promise?\"","zh":"“什么承诺？”","t":[112,1075]}]},{"id":"ch25p21","audio":true,"sents":[{"en":"\"You know-- a muzzle for my sheep...","zh":"“你知道——给我的羊一个嘴套...","t":[138,2288]},{"en":"I am responsible for this flower...\"","zh":"我对这朵花负有责任...","t":[2288,4300]}]},{"id":"ch25p22","audio":true,"sents":[{"en":"I took my rough drafts of drawings out of my pocket.","zh":"我从口袋里掏出了我的草图。","t":[138,3662]},{"en":"The little prince looked them over, and laughed as he said:","zh":"小王子看了看，笑着说：","t":[3662,6863]}]},{"id":"ch25p23","audio":true,"sents":[{"en":"\"Your baobabs-- they look a little like cabbages.\"","zh":"你的猴面包树——它们看起来有点像卷心菜。","t":[138,2662]}]},{"id":"ch25p24","audio":true,"sents":[{"en":"\"Oh!\"","zh":"哦！","t":[100,412]}]},{"id":"ch25p25","audio":true,"sents":[{"en":"I had been so proud of my baobabs!","zh":"我以前对我的猴面包树感到非常自豪！","t":[138,2262]}]},{"id":"ch25p26","audio":true,"sents":[{"en":"\"Your fox-- his ears look a little like horns; and they are too long.\"","zh":"你的狐狸——它的耳朵看起来有点像角；而且太长了。","t":[138,3788]}]},{"id":"ch25p27","audio":true,"sents":[{"en":"And he laughed again.","zh":"他又笑了起来。","t":[138,1288]}]},{"id":"ch25p28","audio":true,"sents":[{"en":"\"You are not fair, little prince,\" I said.","zh":"“你不公平，小王子，”我说。","t":[138,3200]},{"en":"\"I don't know how to draw anything except boa constrictors from the outside and boa constrictors from the inside.\"","zh":"我不知道怎么画除了从外面看的蟒蛇和从里面看的蟒蛇之外的东西。","t":[3200,9287]}]},{"id":"ch25p29","audio":true,"sents":[{"en":"\"Oh, that will be all right,\" he said, \"children understand.\"","zh":"哦，那没问题，”他说，“孩子们会理解的。”","t":[125,3962]}]},{"id":"ch25p30","audio":true,"sents":[{"en":"So then I made a pencil sketch of a muzzle.","zh":"于是，我画了一张嘴巴的铅笔素描。","t":[125,2912]},{"en":"And as I gave it to him my heart was torn.","zh":"当我把它交给他时，我的心碎了。","t":[2912,5388]}]},{"id":"ch25p31","audio":true,"sents":[{"en":"\"You have plans that I do not know about,\" I said.","zh":"你还有一些我不知道的计划吧，”我说。","t":[138,3124]}]},{"id":"ch25p32","audio":true,"sents":[{"en":"But he did not answer me.","zh":"但他没有回答我。","t":[100,1875]},{"en":"He said to me, instead:","zh":"他反而对我说：","t":[1875,3600]}]},{"id":"ch25p33","audio":true,"sents":[{"en":"\"You know-- my descent to the earth...","zh":"你知道——我降临到地球……","t":[138,2362]},{"en":"Tomorrow will be its anniversary.\"","zh":"明天就是它的周年纪念日。","t":[2362,4313]}]},{"id":"ch25p34","audio":true,"sents":[{"en":"Then, after a silence, he went on:","zh":"然后，在沉默了一会儿之后，他继续说：","t":[125,2776]}]},{"id":"ch25p35","audio":true,"sents":[{"en":"\"I came down very near here.\"","zh":"我降落得离这里很近。","t":[138,1900]}]},{"id":"ch25p36","audio":true,"sents":[{"en":"And he flushed.","zh":"然后，他脸红了。","t":[138,1088]}]},{"id":"ch25p37","audio":true,"sents":[{"en":"And once again, without understanding why, I had a queer sense of sorrow.","zh":"我又一次，不明白为什么，感到一种奇怪的悲伤。","t":[138,4975]},{"en":"One question, however, occurred to me:","zh":"然而，一个问题突然闪现在我的脑海中：","t":[4975,7588]}]},{"id":"ch25p38","audio":true,"sents":[{"en":"\"Then it was not by chance that on the morning when I first met you-- a week ago-- you were strolling along like that, all alone, a thousand miles from any inhabited region?","zh":"那么，一周前我第一次遇见你那天早上，你独自一人，漫步的样子，离任何有人居住的地方都有千里之遥，这难道不是偶然的吗？","t":[125,9250]},{"en":"You were on the your back to the place where you landed?\"","zh":"你当时是背对着你降落的地方吗？","t":[9250,11926]}]},{"id":"ch25p39","audio":true,"sents":[{"en":"The little prince flushed again.","zh":"小王子又脸红了。","t":[138,1850]}]},{"id":"ch25p40","audio":true,"sents":[{"en":"And I added, with some hesitancy:","zh":"我有些犹豫地补充道：","t":[112,2388]}]},{"id":"ch25p41","audio":true,"sents":[{"en":"\"Perhaps it was because of the anniversary?\"","zh":"也许是因为周年纪念吧？","t":[100,2500]}]},{"id":"ch25p42","audio":true,"sents":[{"en":"The little prince flushed once more.","zh":"小王子再次脸红了。","t":[138,2500]},{"en":"He never answered questions-- but when one flushes does that not mean \"Yes\"?","zh":"他从不回答问题——但是当一个人脸红的时候，难道这不就意味着“是”吗？","t":[2500,6600]}]},{"id":"ch25p43","audio":true,"sents":[{"en":"\"Ah,\" I said to him, \"I am a little frightened--\"","zh":"我对他说，‘啊，我有点害怕——’","t":[138,3087]}]},{"id":"ch25p44","audio":true,"sents":[{"en":"But he interrupted me.","zh":"但他打断了我。","t":[100,1475]}]},{"id":"ch25p45","audio":true,"sents":[{"en":"\"Now you must work.","zh":"现在你必须工作了。","t":[125,1762]},{"en":"You must return to your engine.","zh":"你必须回到你的引擎那里。","t":[1762,3900]},{"en":"I will be waiting for you here.","zh":"我在这儿等你。","t":[3900,6012]},{"en":"Come back tomorrow evening...\"","zh":"明天晚上再回来...","t":[6012,7687]}]},{"id":"ch25p46","audio":true,"sents":[{"en":"But I was not reassured.","zh":"但我并没有感到安心。","t":[100,2112]},{"en":"I remembered the fox.","zh":"我想起了狐狸。","t":[2112,3938]},{"en":"One runs the risk of weeping a little, if one lets himself be tamed...","zh":"如果一个人让自己被驯服，他就有可能流一点泪...","t":[3938,8037]}]}]},{"id":"ch26","title_en":"Chapter XXVI","title_zh":"第 26 章","paras":[{"id":"ch26p00","audio":true,"sents":[{"en":"Beside the well there was the ruin of an old stonewall.","zh":"井边有一堵古老的石墙的废墟。","t":[138,3600]},{"en":"When I came back from my work, the next evening, I saw from some distance away my little price sitting on top of a wall, with his feet dangling.","zh":"当我第二天晚上下班回来时，我远远地看到我的小王子正坐在墙上，脚悬在空中。","t":[3600,11962]},{"en":"And I heard him say:","zh":"我听到他这么说：","t":[11962,13225]}]},{"id":"ch26p01","audio":true,"sents":[{"en":"\"Then you don't remember.","zh":"那么，你不记得了。","t":[138,1862]},{"en":"This is not the exact spot.\"","zh":"这不是确切的地方。","t":[1862,3637]}]},{"id":"ch26p02","audio":true,"sents":[{"en":"Another voice must have answered him, for he replied to it:","zh":"一定有另一个声音回答了他，因为他回应了它：","t":[112,3413]}]},{"id":"ch26p03","audio":true,"sents":[{"en":"\"Yes, yes!","zh":"是的，是的！","t":[100,1588]},{"en":"It is the right day, but this is not the place.\"","zh":"这是正确的一天，但这个地方不对。","t":[1588,4325]}]},{"id":"ch26p04","audio":true,"sents":[{"en":"I continued my walk toward the wall.","zh":"我继续朝墙走去。","t":[138,2762]},{"en":"At no time did I see or hear anyone.","zh":"我从未看到或听到过任何人。","t":[2762,5600]},{"en":"The little prince, however, replied once again:","zh":"然而，小王子又回答了一次：","t":[5600,8738]}]},{"id":"ch26p05","audio":true,"sents":[{"en":"\"--Exactly.","zh":"--完全正确。","t":[100,1350]},{"en":"You will see where my track begins, in the sand.","zh":"你会在沙子里看到我的足迹开始的地方。","t":[1350,4650]},{"en":"You have nothing to do but wait for me there.","zh":"你没有什么事可做，只需在那里等我。","t":[4650,7300]},{"en":"I shall be there tonight.\"","zh":"我今晚就会到那里。","t":[7300,8775]}]},{"id":"ch26p06","audio":true,"sents":[{"en":"I was only twenty metres from the wall, and I still saw nothing.","zh":"我离墙只有二十米，但我还是什么也没看到。","t":[138,3776]}]},{"id":"ch26p07","audio":true,"sents":[{"en":"After a silence the little prince spoke again:","zh":"沉默之后，小王子又开口了：","t":[138,2826]}]},{"id":"ch26p08","audio":true,"sents":[{"en":"\"You have good poison?","zh":"你有好毒药吗？","t":[138,1812]},{"en":"You are sure that it will not make me suffer too long?\"","zh":"你确定这不会让我痛苦得太久？","t":[1812,4637]}]},{"id":"ch26p09","audio":true,"sents":[{"en":"I stopped in my tracks, my heart torn asunder; but still I did not understand.","zh":"我停了下来，心如刀割；但我仍然不明白。","t":[138,5150]}]},{"id":"ch26p10","audio":true,"sents":[{"en":"\"Now go away,\" said the little prince.","zh":"现在你走吧，”小王子说。","t":[125,2875]},{"en":"\"I want to get down from the wall.\"","zh":"我想从墙上下来。","t":[2875,4674]}]},{"id":"ch26p11","audio":true,"sents":[{"en":"I dropped my eyes, then, to the foot of the wall-- and I leaped into the air.","zh":"我低头看向墙脚——然后跳了起来。","t":[138,4850]},{"en":"There before me, facing the little prince, was one of those yellow snakes that take just thirty seconds to bring your life to an end.","zh":"就在我面前，面对着小王子，有一条那种只需三十秒就能结束你生命的黄色蛇。","t":[4850,12300]},{"en":"Even as I was digging into my pocked to get out my revolver I made a running step back.","zh":"正当我伸手口袋掏出我的手枪时，我迅速后退了一步。","t":[12300,17625]},{"en":"But, at the noise I made, the snake let himself flow easily across the sand like the dying spray of a fountain, and, in no apparent hurry, disappeared, with a light metallic sound, among the stones.","zh":"但是，我一出声，那条蛇就像喷泉即将枯竭的喷泉一样，在沙地上轻松地滑行，然后，不慌不忙地，带着轻微的金属声，消失在石头中。","t":[17625,29337]}]},{"id":"ch26p12","audio":true,"sents":[{"en":"I reached the wall just in time to catch my little man in my arms; his face was white as snow.","zh":"我及时赶到墙边，抱住了我的小家伙；他的脸色苍白如雪。","t":[138,5562]}]},{"id":"ch26p13","audio":true,"sents":[{"en":"\"What does this mean?\" I demanded.","zh":"“这是什么意思？”我问道。","t":[138,2988]},{"en":"\"Why are you talking with snakes?\"","zh":"“你为什么和蛇说话？”","t":[2988,4724]}]},{"id":"ch26p14","audio":true,"sents":[{"en":"I had loosened the golden muffler that he always wore.","zh":"我解开了他总是戴着的那条金色围巾。","t":[138,3538]},{"en":"I had moistened his temples, and had given him some water to drink.","zh":"我湿润了他的额头，并给他喝了一些水。","t":[3538,7838]},{"en":"And now I did not dare ask him any more questions.","zh":"现在，我不敢再问他任何问题了。","t":[7838,11238]},{"en":"He looked at me very gravely, and put his arms around my neck.","zh":"他非常严肃地看着我，然后搂住了我的脖子。","t":[11238,15338]},{"en":"I felt his heart beating like the heart of a dying bird, shot with someone's rifle...","zh":"我感觉到他的心跳像一只被射杀的鸟的心跳一样，被某人的步枪射中...","t":[15338,20125]}]},{"id":"ch26p15","audio":true,"sents":[{"en":"\"I am glad that you have found what was the matter with your engine,\" he said.","zh":"我很高兴你找到了发动机的问题所在。","t":[138,4512]},{"en":"\"Now you can go back home--\"","zh":"现在你可以回家了——","t":[4512,6000]}]},{"id":"ch26p16","audio":true,"sents":[{"en":"\"How do you know about that?\"","zh":"你是怎么知道那件事的？","t":[125,1550]}]},{"id":"ch26p17","audio":true,"sents":[{"en":"I was just coming to tell him that my work had been successful, beyond anything that I had dared to hope.","zh":"我正要告诉他我的工作已经成功，超出了我敢希望的任何程度。","t":[138,5750]}]},{"id":"ch26p18","audio":true,"sents":[{"en":"He made no answer to my question, but he added: \"I, too, am going back home today...\"","zh":"他没有回答我的问题，但他补充说：‘我也要在今天回家……’","t":[125,5463]}]},{"id":"ch26p19","audio":true,"sents":[{"en":"Then, sadly-- \"It is much farther...","zh":"然后，他悲伤地说——‘那还远着呢……’","t":[100,2538]},{"en":"it is much more difficult...\"","zh":"这要难得多……","t":[2538,3976]}]},{"id":"ch26p20","audio":true,"sents":[{"en":"I realised clearly that something extraordinary was happening.","zh":"我清楚地意识到正在发生一些不同寻常的事情。","t":[138,3988]},{"en":"I was holding him close in my arms as if he were a little child; and yet it seemed to me that he was rushing headlong toward an abyss from which I could do nothing to restrain him...","zh":"我把他紧紧地抱在怀里，就像抱一个小孩子；然而，我觉得他正一头冲向一个深渊，我无法阻止他……","t":[3988,12850]}]},{"id":"ch26p21","audio":true,"sents":[{"en":"His look was very serious, like some one lost far away.","zh":"他的眼神非常严肃，就像一个迷失在远方的人。","t":[138,3687]}]},{"id":"ch26p22","audio":true,"sents":[{"en":"\"I have your sheep.","zh":"我这里有你的羊。","t":[125,1588]},{"en":"And I have the sheep's box.","zh":"还有羊的笼子。","t":[1588,3575]},{"en":"And I have the muzzle...\"","zh":"还有嘴套...","t":[3575,4824]}]},{"id":"ch26p23","audio":true,"sents":[{"en":"And he gave me a sad smile.","zh":"他给了我一个悲伤的微笑。","t":[138,1800]}]},{"id":"ch26p24","audio":true,"sents":[{"en":"I waited a long time.","zh":"我等了很长时间。","t":[138,1925]},{"en":"I could see that he was reviving little by little.","zh":"我能看出他正在慢慢恢复。","t":[1925,4725]}]},{"id":"ch26p25","audio":true,"sents":[{"en":"\"Dear little man,\" I said to him, \"you are afraid...\"","zh":"“亲爱的孩子，”我对他说，“你害怕……”","t":[112,3237]}]},{"id":"ch26p26","audio":true,"sents":[{"en":"He was afraid, there was no doubt about that.","zh":"他害怕，这是毫无疑问的。","t":[138,3212]},{"en":"But he laughed lightly.","zh":"但他轻轻地笑了。","t":[3212,4487]}]},{"id":"ch26p27","audio":true,"sents":[{"en":"\"I shall be much more afraid this evening...\"","zh":"今晚我会更加害怕……","t":[138,2350]}]},{"id":"ch26p28","audio":true,"sents":[{"en":"Once again I felt myself frozen by the sense of something irreparable.","zh":"又一次，我感到自己被一种无法挽回的感觉冻结了。","t":[138,4638]},{"en":"And I knew that I could not bear the thought of never hearing that laughter any more.","zh":"我知道我无法忍受永远不再听到那笑声。","t":[4638,9038]},{"en":"For me, it was like a spring of fresh water in the desert.","zh":"对我来说，它就像沙漠中的一股清泉。","t":[9038,12450]}]},{"id":"ch26p29","audio":true,"sents":[{"en":"\"Little man,\" I said, \"I want to hear you laugh again.\"","zh":"‘小家伙，’我说，‘我想再听到你笑一次。’","t":[138,3288]}]},{"id":"ch26p30","audio":true,"sents":[{"en":"But he said to me:","zh":"但他对我说：","t":[100,1162]}]},{"id":"ch26p31","audio":true,"sents":[{"en":"\"Tonight, it will be a year...","zh":"“今晚，它将是一年...","t":[100,2000]},{"en":"my star, then, can be found right above the place where I came to the Earth, a year ago...\"","zh":"那么，我的星星，现在就可以在一年前我来到地球的地方找到了...","t":[2000,7076]}]},{"id":"ch26p32","audio":true,"sents":[{"en":"\"Little man,\" I said, \"tell me that it is only a bad dream-- this affair of the snake, and the meeting-place, and the star...\"","zh":"‘小家伙，’我说，‘告诉我这只是个噩梦——关于蛇、相遇地点和星星的事情...’","t":[112,6875]}]},{"id":"ch26p33","audio":true,"sents":[{"en":"But he did not answer my plea.","zh":"但他没有回应我的请求。","t":[100,2238]},{"en":"He said to me, instead:","zh":"他对我说的却是：","t":[2238,3950]}]},{"id":"ch26p34","audio":true,"sents":[{"en":"\"The thing that is important is the thing that is not seen...\"","zh":"重要的东西是肉眼看不见的……","t":[138,3287]}]},{"id":"ch26p35","audio":true,"sents":[{"en":"\"Yes, I know...\"","zh":"是的，我知道……","t":[100,1288]}]},{"id":"ch26p36","audio":true,"sents":[{"en":"\"It is just as it is with the flower.","zh":"花也是这样。","t":[138,2625]},{"en":"If you love a flower that lives on a star, it is sweet to look at the sky at night.","zh":"如果你爱上了一朵长在星星上的花，那么在夜晚仰望星空就会变得很甜蜜。","t":[2625,7438]},{"en":"All the stars are a-bloom with flowers...\"","zh":"所有的星星上都开满了花朵……","t":[7438,9862]}]},{"id":"ch26p37","audio":true,"sents":[{"en":"\"Yes, I know...\"","zh":"是的，我知道……","t":[100,1288]}]},{"id":"ch26p38","audio":true,"sents":[{"en":"\"It is just as it is with the water.","zh":"水也是这样。","t":[138,2575]},{"en":"Because of the pulley, and the rope, what you gave me to drink was like music.","zh":"因为有了滑轮和绳子，你给我喝的水就像音乐一样。","t":[2575,7325]},{"en":"You remember-- how good it was.\"","zh":"你还记得——那有多美好。","t":[7325,8987]}]},{"id":"ch26p39","audio":true,"sents":[{"en":"\"Yes, I know...\"","zh":"是的，我知道……","t":[100,1288]}]},{"id":"ch26p40","audio":true,"sents":[{"en":"\"And at night you will look up at the stars.","zh":"夜晚，你将仰望星空。","t":[138,2725]},{"en":"Where I live everything is so small that I cannot show you where my star is to be found.","zh":"在我生活的世界里，一切都很小，我无法向你指出我的那颗星星在哪里。","t":[2725,7800]},{"en":"It is better, like that.","zh":"这样更好。","t":[7800,9912]},{"en":"My star will just be one of the stars, for you.","zh":"我的那颗星星对你来说，将只是众多星星中的一颗。","t":[9912,13325]},{"en":"And so you will love to watch all the stars in the heavens...","zh":"因此，你将喜欢观看天空中所有的星星...","t":[13325,16475]},{"en":"they will all be your friends.","zh":"它们都将成为你的朋友。","t":[16475,18238]},{"en":"And, besides, I am going to make you a present...\"","zh":"而且，我还将送你一份礼物...","t":[18238,21388]}]},{"id":"ch26p41","audio":true,"sents":[{"en":"He laughed again.","zh":"他又笑了。","t":[138,1150]}]},{"id":"ch26p42","audio":true,"sents":[{"en":"\"Ah, little prince, dear little prince!","zh":"啊，小王子，亲爱的、可爱的小王子！","t":[138,3225]},{"en":"I love to hear that laughter!\"","zh":"我喜欢听到那笑声！","t":[3225,4763]}]},{"id":"ch26p43","audio":true,"sents":[{"en":"\"That is my present.","zh":"这是我送给你的礼物。","t":[138,1788]},{"en":"Just that.","zh":"就这一点。","t":[1788,3025]},{"en":"It will be as it was when we drank the water...\"","zh":"它将和我们一起喝过的水一样……","t":[3025,5625]}]},{"id":"ch26p44","audio":true,"sents":[{"en":"\"What are you trying to say?\"","zh":"你到底想说什么？","t":[125,1550]}]},{"id":"ch26p45","audio":true,"sents":[{"en":"\"All men have the stars,\" he answered, \"but they are not the same things for different people.","zh":"每个人心中都有星星，”他回答，“但对于不同的人来说，它们是不同的事物。","t":[138,5362]},{"en":"For some, who are travellers, the stars are guides.","zh":"对于一些旅行者来说，星星是向导。","t":[5362,8988]},{"en":"For others they are no more than little lights in the sky.","zh":"对于其他人来说，它们不过是天空中的小灯。","t":[8988,12400]},{"en":"For others, who are scholars, they are problems.","zh":"对于一些学者来说，它们是问题。","t":[12400,15838]},{"en":"For my businessman they were wealth.","zh":"对于我的商人来说，它们是财富。","t":[15838,18125]},{"en":"But all these stars are silent.","zh":"但所有这些星星都是沉默的。","t":[18125,20488]},{"en":"You-- you alone-- will have the stars as no one else has them--\"","zh":"你——只有你——将拥有别人无法拥有的星星——","t":[20488,23688]}]},{"id":"ch26p46","audio":true,"sents":[{"en":"\"What are you trying to say?\"","zh":"你想说什么？","t":[125,1550]}]},{"id":"ch26p47","audio":true,"sents":[{"en":"\"In one of the stars I shall be living.","zh":"在某一颗星星上，我将居住。","t":[138,2662]},{"en":"In one of them I shall be laughing.","zh":"在其中之一，我会笑出声来。","t":[2662,4912]},{"en":"And so it will be as if all the stars were laughing, when you look at the sky at night...","zh":"于是，当你夜晚仰望星空时，就好像所有的星星都在欢笑……","t":[4912,9588]},{"en":"you-- only you-- will have stars that can laugh!\" And he laughed again.","zh":"你——只有你——将拥有会笑的星星！”他又笑了。","t":[9588,13150]}]},{"id":"ch26p48","audio":true,"sents":[{"en":"\"And when your sorrow is comforted (time soothes all sorrows) you will be content that you have known me.","zh":"当你的悲伤得到慰藉（时间抚平所有的悲伤）时，你将满足于曾认识我。","t":[138,6075]},{"en":"You will always be my friend.","zh":"你将永远是我的朋友。","t":[6075,8200]},{"en":"You will want to laugh with me.","zh":"你想和我一起笑。","t":[8200,10100]},{"en":"And you will sometimes open your window, so, for that pleasure...","zh":"有时你会打开你的窗户，为了那份快乐……","t":[10100,13825]},{"en":"and your friends will be properly astonished to see you laughing as you look up at the sky!","zh":"而且，当你仰望天空时，你的朋友们会惊讶地看到你在笑！","t":[13825,18312]},{"en":"Then you will say to them, 'Yes, the stars always make me laugh!' And they will think you are crazy.","zh":"然后你会对他们说，'是的，星星总是让我笑！' 他们会认为你疯了。","t":[18312,24450]},{"en":"It will be a very shabby trick that I shall have played on you...\"","zh":"这将会是我对你玩的一个非常拙劣的把戏……","t":[24450,27688]}]},{"id":"ch26p49","audio":true,"sents":[{"en":"And he laughed again.","zh":"他又笑了一次。","t":[138,1288]}]},{"id":"ch26p50","audio":true,"sents":[{"en":"\"It will be as if, in place of the stars, I had given you a great number of little bells that knew how to laugh...\"","zh":"那将会像是，在我给你的星星位置，我给了你许多会笑的小铃铛……","t":[138,6337]}]},{"id":"ch26p51","audio":true,"sents":[{"en":"And he laughed again.","zh":"他又笑了一次。","t":[138,1688]},{"en":"Then he quickly became serious:","zh":"然后他很快变得严肃起来：","t":[1688,3700]}]},{"id":"ch26p52","audio":true,"sents":[{"en":"\"Tonight-- you know...","zh":"今晚——你知道……","t":[100,1338]},{"en":"do not come,\" said the little prince.","zh":"不要来，”小王子说。","t":[1338,3563]}]},{"id":"ch26p53","audio":true,"sents":[{"en":"\"I shall not leave you,\" I said.","zh":"我不会离开你，”我说。","t":[138,2063]}]},{"id":"ch26p54","audio":true,"sents":[{"en":"\"I shall look as if I were suffering.","zh":"我将装作自己很痛苦。","t":[138,2438]},{"en":"I shall look a little as if I were dying.","zh":"我会看起来像是快死了。","t":[2438,5100]},{"en":"It is like that.","zh":"就是这样。","t":[5100,6562]},{"en":"Do not come to see that.","zh":"不要去看那个。","t":[6562,8450]},{"en":"It is not worth the trouble...\"","zh":"不值得麻烦。","t":[8450,10013]}]},{"id":"ch26p55","audio":true,"sents":[{"en":"\"I shall not leave you.\"","zh":"我不会离开你的。","t":[138,1376]}]},{"id":"ch26p56","audio":true,"sents":[{"en":"But he was worried.","zh":"但他很担心。","t":[112,1250]}]},{"id":"ch26p57","audio":true,"sents":[{"en":"\"I tell you-- it is also because of the snake.","zh":"我告诉你——这也是因为那条蛇。","t":[138,3050]},{"en":"He must not bite you.","zh":"它不能咬你。","t":[3050,4750]},{"en":"Snakes-- they are malicious creatures.","zh":"蛇——它们是恶毒的生物。","t":[4750,7188]},{"en":"This one might bite you just for fun...\"","zh":"这个家伙可能只是为了好玩就咬你一口...","t":[7188,9275]}]},{"id":"ch26p58","audio":true,"sents":[{"en":"\"I shall not leave you.\"","zh":"我不会离开你的。","t":[138,1376]}]},{"id":"ch26p59","audio":true,"sents":[{"en":"But a thought came to reassure him:","zh":"但一个想法让他安心：","t":[100,2126]}]},{"id":"ch26p60","audio":true,"sents":[{"en":"\"It is true that they have no more poison for a second bite.\"","zh":"确实，它们在第二次咬的时候就没有毒了。","t":[138,3388]}]},{"id":"ch26p61","audio":true,"sents":[{"en":"That night I did not see him set out on his way.","zh":"那天晚上我没有看到他出发。","t":[138,3375]},{"en":"He got away from me without making a sound.","zh":"他没有发出任何声音就从我这里逃走了。","t":[3375,6288]},{"en":"When I succeeded in catching up with him he was walking along with a quick and resolute step.","zh":"当我成功追上他时，他正以快速而坚定的步伐走着。","t":[6288,11662]},{"en":"He said to me merely:","zh":"他只是对我说：","t":[11662,12875]}]},{"id":"ch26p62","audio":true,"sents":[{"en":"\"Ah!","zh":"啊！","t":[100,825]},{"en":"You are there...\"","zh":"你在这里……","t":[825,1612]}]},{"id":"ch26p63","audio":true,"sents":[{"en":"And he took me by the hand.","zh":"他拉着我的手。","t":[138,2012]},{"en":"But he was still worrying.","zh":"但他仍然在担心。","t":[2012,3438]}]},{"id":"ch26p64","audio":true,"sents":[{"en":"\"It was wrong of you to come.","zh":"你来得不对。","t":[138,1988]},{"en":"You will suffer.","zh":"你会受苦的。","t":[1988,3388]},{"en":"I shall look as if I were dead; and that will not be true...\"","zh":"我会看起来像是死了；但这不是真的……","t":[3388,6676]}]},{"id":"ch26p65","audio":true,"sents":[{"en":"I said nothing.","zh":"我说了什么都没有。","t":[138,1150]}]},{"id":"ch26p66","audio":true,"sents":[{"en":"\"You understand...","zh":"你明白……","t":[138,1388]},{"en":"it is too far.","zh":"太远了。","t":[1388,2725]},{"en":"I cannot carry this body with me.","zh":"我无法带着这具尸体离开。","t":[2725,5038]},{"en":"It is too heavy.\"","zh":"太重了。","t":[5038,6163]}]},{"id":"ch26p67","audio":true,"sents":[{"en":"I said nothing.","zh":"我说什么也没说。","t":[138,1150]}]},{"id":"ch26p68","audio":true,"sents":[{"en":"\"But it will be like an old abandoned shell.","zh":"但那将像是一个古老的废弃贝壳。","t":[112,2738]},{"en":"There is nothing sad about old shells...\"","zh":"古老的贝壳没有什么悲伤的...","t":[2738,4988]}]},{"id":"ch26p69","audio":true,"sents":[{"en":"I said nothing.","zh":"我说什么也没说。","t":[138,1150]}]},{"id":"ch26p70","audio":true,"sents":[{"en":"He was a little discouraged.","zh":"他有点泄气。","t":[138,2162]},{"en":"But he made one more effort:","zh":"但他又努力了一次：","t":[2162,3876]}]},{"id":"ch26p71","audio":true,"sents":[{"en":"\"You know, it will be very nice.","zh":"你知道，那会非常美好的。","t":[138,2500]},{"en":"I, too, shall look at the stars.","zh":"我也要看看星星。","t":[2500,5200]},{"en":"All the stars will be wells with a rusty pulley.","zh":"所有的星星都会变成带有生锈滑轮的水井。","t":[5200,8325]},{"en":"All the stars will pour out fresh water for me to drink...\"","zh":"所有的星星都会为我流出新鲜的水来喝...","t":[8325,11713]}]},{"id":"ch26p72","audio":true,"sents":[{"en":"I said nothing.","zh":"我说什么也没说。","t":[138,1150]}]},{"id":"ch26p73","audio":true,"sents":[{"en":"\"That will be so amusing!","zh":"那会很有趣的！","t":[112,2000]},{"en":"You will have five hundred million little bells, and I shall have five hundred million springs of fresh water...\"","zh":"你将拥有五亿个小铃铛，而我将拥有五亿股清泉……","t":[2000,7774]}]},{"id":"ch26p74","audio":true,"sents":[{"en":"And he too said nothing more, because he was crying...","zh":"他也没有再说下去，因为他正在哭泣……","t":[112,3025]}]},{"id":"ch26p75","audio":true,"sents":[{"en":"\"Here it is.","zh":"就在这里。","t":[138,1325]},{"en":"Let me go on by myself.\"","zh":"让我自己继续吧。","t":[1325,3062]}]},{"id":"ch26p76","audio":true,"sents":[{"en":"And he sat down, because he was afraid.","zh":"然后他坐了下来，因为他害怕。","t":[138,3025]},{"en":"Then he said, again:","zh":"然后他又说，再次说道：","t":[3025,4512]}]},{"id":"ch26p77","audio":true,"sents":[{"en":"\"You know-- my flower...","zh":"你知道——我的玫瑰……","t":[138,1712]},{"en":"I am responsible for her.","zh":"我对她负责。","t":[1712,3712]},{"en":"And she is so weak!","zh":"她如此脆弱！","t":[3712,5262]},{"en":"She is so naïve!","zh":"她如此天真！","t":[5262,6938]},{"en":"She has four thorns, of no use at all, to protect herself against all the world...\"","zh":"她有四根刺，毫无用处，却要用来保护自己免受全世界的一切伤害...","t":[6938,11900]}]},{"id":"ch26p78","audio":true,"sents":[{"en":"I too sat down, because I was not able to stand up any longer.","zh":"我也坐了下来，因为我再也无法站起来。","t":[138,3900]}]},{"id":"ch26p79","audio":true,"sents":[{"en":"\"There now-- that is all...\"","zh":"现在好了——这就完了...","t":[125,1388]}]},{"id":"ch26p80","audio":true,"sents":[{"en":"He still hesitated a little; then he got up.","zh":"他还是有点犹豫；然后他站了起来。","t":[138,3462]},{"en":"He took one step.","zh":"他迈出了一步。","t":[3462,5075]},{"en":"I could not move.","zh":"我无法动弹。","t":[5075,6162]}]},{"id":"ch26p81","audio":true,"sents":[{"en":"There was nothing but a flash of yellow close to his ankle.","zh":"在他脚踝附近只有一闪而过的黄色。","t":[138,3600]},{"en":"He remained motionless for an instant.","zh":"他瞬间一动不动。","t":[3600,6262]},{"en":"He did not cry out.","zh":"他没有呼喊。","t":[6262,7975]},{"en":"He fell as gently as a tree falls.","zh":"他像一棵树倒下一样轻轻地跌倒了。","t":[7975,10588]},{"en":"There was not even any sound, because of the sand.","zh":"因为沙子，甚至没有发出任何声音。","t":[10588,13587]}]}]},{"id":"ch27","title_en":"Chapter XXVII","title_zh":"第 27 章","paras":[{"id":"ch27p00","audio":true,"sents":[{"en":"And now six years have already gone by...","zh":"而现在，六年已经过去了...","t":[112,2462]}]},{"id":"ch27p01","audio":true,"sents":[{"en":"I have never yet told this story.","zh":"我从未告诉过这个故事。","t":[138,2462]},{"en":"The companions who met me on my return were well content to see me alive.","zh":"在我回来时遇见我的同伴们看到我还活着都很高兴。","t":[2462,7000]},{"en":"I was sad, but I told them: \"I am tired.\"","zh":"我很伤心，但我告诉他们：“我累了。”","t":[7000,9963]}]},{"id":"ch27p02","audio":true,"sents":[{"en":"Now my sorrow is comforted a little.","zh":"现在我的悲伤得到了一点安慰。","t":[112,2712]},{"en":"That is to say-- not entirely.","zh":"也就是说——并不完全。","t":[2712,4838]},{"en":"But I know that he did go back to his planet, because I did not find his body at daybreak.","zh":"但我知道他确实回到了他的星球，因为我在黎明时分没有找到他的尸体。","t":[4838,10188]},{"en":"It was not such a heavy body...","zh":"它并不算是一个沉重的身体...","t":[10188,12138]},{"en":"and at night I love to listen to the stars.","zh":"而在夜晚，我喜欢倾听星星。","t":[12138,14712]},{"en":"It is like five hundred million little bells...","zh":"这就像五亿个小铃铛...","t":[14712,17413]}]},{"id":"ch27p03","audio":true,"sents":[{"en":"But there is one extraordinary thing...","zh":"但有一件非常特别的事情...","t":[100,2225]},{"en":"when I drew the muzzle for the little prince, I forgot to add the leather strap to it.","zh":"当我为小王子画上嘴巴时，我忘记给它加上皮带。","t":[2225,6800]},{"en":"He will never have been able to fasten it on his sheep.","zh":"所以他永远都无法把它系在他的羊身上。","t":[6800,10012]},{"en":"So now I keep wondering: what is happening on his planet?","zh":"所以我现在一直在想：他的星球上发生了什么？","t":[10012,13812]},{"en":"Perhaps the sheep has eaten the flower...","zh":"也许羊吃掉了那朵花...","t":[13812,16013]}]},{"id":"ch27p04","audio":true,"sents":[{"en":"At one time I say to myself: \"Surely not!","zh":"有时候我会对自己说：'肯定不是！'","t":[138,3450]},{"en":"The little prince shuts his flower under her glass globe every night, and he watches over his sheep very carefully...\" Then I am happy.","zh":"小王子每晚都会把他的玫瑰关在他的玻璃球下面，他非常小心地照看着他的羊。然后我就感到快乐。","t":[3450,11425]},{"en":"And there is sweetness in the laughter of all the stars.","zh":"在所有星星的笑声中，都充满了甜蜜。","t":[11425,14337]}]},{"id":"ch27p05","audio":true,"sents":[{"en":"But at another time I say to myself: \"At some moment or other one is absent-minded, and that is enough!","zh":"但有时我会对自己说：'在某个时刻，人们都会心不在焉，这就足够了！'","t":[100,6562]},{"en":"On some one evening he forgot the glass globe, or the sheep got out, without making any noise, in the night...\" And then the little bells are changed to tears...","zh":"有一天晚上，他忘了玻璃球，或者羊在夜里悄无声息地逃走了……然后，小铃铛就变成了泪水……","t":[6562,15775]}]},{"id":"ch27p06","audio":true,"sents":[{"en":"Here, then, is a great mystery.","zh":"这里，有一个伟大的奥秘。","t":[138,2775]},{"en":"For you who also love the little prince, and for me, nothing in the universe can be the same if somewhere, we do not know where, a sheep that we never saw has-- yes or no?-- eaten a rose...","zh":"对于你们这些也爱小王子的人，以及我来说，如果某个地方——我们不知道在哪里——有一只我们从未见过的羊——是或者不是？——吃了一朵玫瑰……那么，宇宙中的任何事物都将不再相同……","t":[2775,13050]}]},{"id":"ch27p07","audio":true,"sents":[{"en":"Look up at the sky.","zh":"抬头看看天空。","t":[112,1712]},{"en":"Ask yourselves: is it yes or no?","zh":"问问自己：是或者不是？","t":[1712,4500]},{"en":"Has the sheep eaten the flower?","zh":"羊吃掉了那朵花吗？","t":[4500,6575]},{"en":"And you will see how everything changes...","zh":"你们将会看到一切是如何改变的……","t":[6575,8912]}]},{"id":"ch27p08","audio":true,"sents":[{"en":"And no grown-up will ever understand that this is a matter of so much importance!","zh":"而且，任何成年人都不可能理解这件事有多么重要！","t":[138,4562]}]},{"id":"ch27p09","audio":true,"sents":[{"en":"This is, to me, the loveliest and saddest landscape in the world.","zh":"对我来说，这是世界上最美丽而又最悲伤的风景。","t":[125,4638]},{"en":"It is the same as that on the preceding page, but I have drawn it again to impress it on your memory.","zh":"它和上一页上的风景一样，但我又画了一遍，以便让你记住。","t":[4638,10388]},{"en":"It is here that the little prince appeared on Earth, and disappeared.","zh":"小王子就是在这里来到地球，又消失在这里。","t":[10388,14037]}]},{"id":"ch27p10","audio":true,"sents":[{"en":"Look at it carefully so that you will be sure to recognise it in case you travel some day to the African desert.","zh":"仔细看看，这样你将来有一天去非洲沙漠旅行时，一定能认出它。","t":[100,6325]},{"en":"And, if you should come upon this spot, please do not hurry on.","zh":"如果你来到这个地方，请不要急于前行。","t":[6325,10375]},{"en":"Wait for a time, exactly under the star.","zh":"等待一段时间，就在那颗星星下面。","t":[10375,13400]},{"en":"Then, if a little man appears who laughs, who has golden hair and who refuses to answer questions, you will know who he is.","zh":"然后，如果有一个笑起来、金色头发、拒绝回答问题的矮人出现，你就会知道他是谁。","t":[13400,20825]},{"en":"If this should happen, please comfort me.","zh":"如果发生了这样的事，请安慰我。","t":[20825,23525]},{"en":"Send me word that he has come back.","zh":"告诉我他回来了。","t":[23525,25687]}]},{"id":"ch27p11","audio":true,"sents":[{"en":"Saint-Exupéry: A Short Biography","zh":"圣埃克苏佩里：简传","t":[100,2688]}]},{"id":"ch27p12","audio":true,"sents":[{"en":"His friends called him Saint-Ex.","zh":"他的朋友们叫他圣埃克苏佩里。","t":[138,2538]},{"en":"In reality, he was named Antoine de Saint-Exupéry.","zh":"实际上，他名叫安东尼·德·圣埃克苏佩里。","t":[2538,6425]},{"en":"He is one of the greatest French writers.","zh":"他是法国最伟大的作家之一。","t":[6425,9150]},{"en":"He is also one of the pioneers of aviation.","zh":"他也是航空领域的先驱之一。","t":[9150,12362]},{"en":"Here is his story.","zh":"这就是他的故事。","t":[12362,13550]}]},{"id":"ch27p13","audio":true,"sents":[{"en":"Saint-Exupéry was born in Lyon in 1900.","zh":"圣埃克苏佩里于1900年出生于里昂。","t":[125,3875]},{"en":"At an early age, he dreamt of adventure.","zh":"在很小的时候，他就梦想着冒险。","t":[3875,6862]},{"en":"His greatest ambition was to be an officer in the Navy.","zh":"他最大的愿望是成为一名海军军官。","t":[6862,10462]},{"en":"In order to become a Naval officer, one had to pass a very difficult exam.","zh":"为了成为一名海军军官，必须通过一个非常困难的考试。","t":[10462,15250]},{"en":"Saint-Exupéry took the exam and failed...","zh":"圣埃克苏佩里参加了考试，但失败了...","t":[15250,18025]},{"en":"there was, fortunately, another solution-- aviation.","zh":"幸运的是，还有一个解决办法——航空。","t":[18025,21588]},{"en":"At this time, aviation was extremely dangerous.","zh":"在这个时候，航空极其危险。","t":[21588,25225]},{"en":"Danger, risk-- this is precisely for what Saint-Exupéry wished.","zh":"危险，风险——这正是圣埃克苏佩里所追求的。","t":[25225,29512]},{"en":"During his military service, he learned to pilot airplanes.","zh":"在他的军事服务期间，他学会了驾驶飞机。","t":[29512,33475]},{"en":"Saint-Exupéry had only one idea in his head: to fly.","zh":"圣埃克苏佩里心中只有一个想法：去飞行。","t":[33475,37200]}]},{"id":"ch27p14","audio":true,"sents":[{"en":"After his military service, he presented himself to the director of an airline company and expressed to him his desire to become a pilot.","zh":"军事服务结束后，他向一家航空公司的经理自我介绍，并表达了他想成为一名飞行员的愿望。","t":[138,7975]},{"en":"The director told him, \"Do like everyone else.","zh":"经理告诉他：“像其他人一样。","t":[7975,11238]},{"en":"First, you must become a mechanic.\"","zh":"首先，你必须成为一名机械师。","t":[11238,13562]}]},{"id":"ch27p15","audio":true,"sents":[{"en":"Saint-Exupéry worked to become a mechanic.","zh":"圣埃克苏佩里努力成为一名机械师。","t":[112,3162]},{"en":"In 1927, he finally reached his goal.","zh":"1927年，他终于实现了他的目标。","t":[3162,6762]},{"en":"He was the pilot of a formation.","zh":"他是机队的飞行员。","t":[6762,9150]},{"en":"He completed dangerous missions over the Mediterranean, over the Sahara.","zh":"他在地中海、撒哈拉上空完成了许多危险的使命。","t":[9150,13888]},{"en":"He had many accidents over the middle of the desert.","zh":"他在沙漠中部遭遇了许多事故。","t":[13888,17100]},{"en":"Later, he was named the director of his own aviation company in South America.","zh":"后来，他被任命为他在南美洲自己的航空公司的总监。","t":[17100,22338]},{"en":"There also, he accomplished many dangerous missions over the Andes.","zh":"在那里，他也完成了许多危险的安第斯山脉上的使命。","t":[22338,26438]}]},{"id":"ch27p16","audio":true,"sents":[{"en":"For Saint-Exupéry, flying wasn't just piloting an airplane.","zh":"对圣埃克苏佩里来说，飞行不仅仅是驾驶飞机。","t":[125,4312]},{"en":"It was also meditating, reflecting.","zh":"它也是冥想，反思。","t":[4312,7325]},{"en":"During his missions, Saint-Exupéry thought deeply about solitude, friendship, the meaning of life, the human condition, and liberty.","zh":"在他的任务期间，圣埃克苏佩里深入思考了孤独、友谊、生活的意义、人类状况和自由。","t":[7325,15925]},{"en":"He published his reflections.","zh":"他发表了这些反思。","t":[15925,18150]},{"en":"His books had immediate success.","zh":"他的书立即获得了成功。","t":[18150,20200]}]},{"id":"ch27p17","audio":true,"sents":[{"en":"Unfortunately, the aviation company for which Saint-Exupéry worked was having serious financial problems.","zh":"不幸的是，圣埃克苏佩里工作的航空公司正面临严重的财务问题。","t":[112,6812]},{"en":"Saint-Exupéry had to quit the company.","zh":"圣埃克苏佩里不得不辞去公司。","t":[6812,9500]},{"en":"He became a journalist.","zh":"他成为了一名记者。","t":[9500,11412]},{"en":"He went to Spain, Russia, and Germany.","zh":"他前往西班牙、俄罗斯和德国。","t":[11412,14488]},{"en":"He flew when he could.","zh":"他能飞的时候就会飞。","t":[14488,15774]}]},{"id":"ch27p18","audio":true,"sents":[{"en":"In 1939, France went to war with Germany.","zh":"1939年，法国与德国开战。","t":[138,3938]},{"en":"Saint-Exupéry enlisted immediately in the army.","zh":"圣埃克苏佩里立即参军。","t":[3938,7312]},{"en":"Defeat came soon.","zh":"失败很快降临。","t":[7312,9050]},{"en":"France was occupied by Hitler's troops.","zh":"法国被希特勒的军队占领。","t":[9050,11587]}]},{"id":"ch27p19","audio":true,"sents":[{"en":"Saint-Exupéry didn't accept the defeat.","zh":"圣埃克苏佩里不接受失败。","t":[112,3062]},{"en":"He decided to leave France.","zh":"他决定离开法国。","t":[3062,5275]},{"en":"He settled in the United States, where he continued to write.","zh":"他在美国定居，继续写作。","t":[5275,9275]},{"en":"It was in New York that he published The Little Prince, one of his most celebrated books.","zh":"正是在纽约，他出版了《小王子》，这是他最著名的书籍之一。","t":[9275,14324]}]},{"id":"ch27p20","audio":true,"sents":[{"en":"In 1942, American troops landed in North Africa.","zh":"1942年，美军在北非登陆。","t":[112,4550]},{"en":"Saint-Exupéry decided to join the American army.","zh":"圣埃克苏佩里决定加入美国军队。","t":[4550,8000]},{"en":"At age 42, he volunteered to be a pilot.","zh":"42岁时，他志愿成为一名飞行员。","t":[8000,11575]},{"en":"He was told that he was too old.","zh":"有人告诉他他太老了。","t":[11575,13962]},{"en":"He persisted.","zh":"他坚持不懈。","t":[13962,15338]},{"en":"Finally he obtained satisfaction.","zh":"最终他得到了满足。","t":[15338,18025]},{"en":"He was given an airplane.","zh":"他被分配了一架飞机。","t":[18025,19888]},{"en":"He accomplished many missions over occupied France.","zh":"他在被占领的法国完成了许多任务。","t":[19888,23126]}]},{"id":"ch27p21","audio":true,"sents":[{"en":"On the 31st of July, 1944, Saint-Exupéry left for his last mission.","zh":"1944年7月31日，圣埃克苏佩里出发执行他最后的任务。","t":[138,6138]},{"en":"His airplane was destroyed by Germans over the Mediterranean.","zh":"他的飞机在地中海上被德国人摧毁。","t":[6138,10188]},{"en":"On that day, Saint-Exupéry didn't return...","zh":"那天，圣埃克苏佩里没有回来...","t":[10188,13100]},{"en":"in the open sky, he found risk, death, and glory.","zh":"在广阔的天空中，他找到了风险、死亡和荣耀。","t":[13100,16712]}]}]}]};